export const examples = {"all-named-html-entities":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { allNamedEntities } from \"all-named-html-entities\";\n\nassert.equal(allNamedEntities.AElig, \"Æ\");"},"allNamedEntities.js":{"title":"`allNamedEntities`","code":"import { strict as assert } from \"node:assert\";\n\nimport { allNamedEntities } from \"all-named-html-entities\";\n\n// total named entities count:\nassert.equal(Object.keys(allNamedEntities).length, 2125);\n\n// show the first-one:\nassert.equal(Object.keys(allNamedEntities).sort()[0], \"AElig\");\n\n// &AElig; decoded:\nassert.equal(allNamedEntities.AElig, \"Æ\");"},"decode.js":{"title":"Decode a named HTML entity","code":"import { strict as assert } from \"node:assert\";\n\nimport { decode } from \"all-named-html-entities\";\n\nassert.equal(decode(\"&aleph;\"), \"ℵ\");\nassert.equal(decode(\"&notARealEntity;\"), null);"},"entEndsWith.js":{"title":"`entEndsWith`","code":"import { strict as assert } from \"node:assert\";\n\nimport { entEndsWith } from \"all-named-html-entities\";\n\n// here's list of named HTML entities which end with character \"2\":\nassert.deepEqual(entEndsWith[\"2\"], {\n  1: [\"blk12\", \"frac12\"],\n  p: [\"sup2\"],\n});\n\n// query directly\nassert.equal(entEndsWith[\"2\"].p[0], \"sup2\");"},"entEndsWithCaseInsensitive.js":{"title":"Find entity names by a case-insensitive suffix","code":"import { strict as assert } from \"node:assert\";\n\nimport { entEndsWithCaseInsensitive } from \"all-named-html-entities\";\n\nassert.deepEqual(entEndsWithCaseInsensitive.u.m, [\"mu\"]);"},"entStartsWith.js":{"title":"`entStartsWith`","code":"import { strict as assert } from \"node:assert\";\n\nimport { entStartsWith } from \"all-named-html-entities\";\n\n// for perf reasons, they're pre-grouped by first two letters\nassert.deepEqual(entStartsWith.A, {\n  a: [\"Aacute\"],\n  b: [\"Abreve\"],\n  c: [\"Acirc\", \"Acy\"],\n  E: [\"AElig\"],\n  f: [\"Afr\"],\n  g: [\"Agrave\"],\n  l: [\"Alpha\"],\n  m: [\"Amacr\"],\n  M: [\"AMP\"],\n  n: [\"And\"],\n  o: [\"Aogon\", \"Aopf\"],\n  p: [\"ApplyFunction\"],\n  r: [\"Aring\"],\n  s: [\"Ascr\", \"Assign\"],\n  t: [\"Atilde\"],\n  u: [\"Auml\"],\n});\n\n// query directly\nassert.equal(entStartsWith.A.E[0], \"AElig\");"},"entStartsWithCaseInsensitive.js":{"title":"`entStartsWithCaseInsensitive`","code":"import { strict as assert } from \"node:assert\";\n\nimport { entStartsWithCaseInsensitive } from \"all-named-html-entities\";\n\n// case-insensitive \"entStartsWithCaseInsensitive\" is useful\n// when looking for possibly mis-typed entities; emlint uses it\n\n// which entities, lowercased, start with \"j\"?\nassert.deepEqual(entStartsWithCaseInsensitive.j, {\n  c: [\"jcirc\", \"jcy\"],\n  f: [\"jfr\"],\n  m: [\"jmath\"],\n  o: [\"jopf\"],\n  s: [\"jscr\", \"jsercy\"],\n  u: [\"jukcy\"],\n});"},"entityMetadata.js":{"title":"Inspect entity-name metadata","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  brokenNamedEntities,\n  maxLength,\n  minLength,\n  uncertain,\n} from \"all-named-html-entities\";\n\nassert.equal(minLength, 2);\nassert.equal(maxLength, 31);\nassert.equal(typeof brokenNamedEntities, \"object\");\nassert.equal(uncertain.Alpha.addAmpIfSemiPresent, false);\nassert.equal(uncertain.Alpha.addSemiIfAmpPresent, \"edge only\");"},"entitySets.js":{"title":"Test whether a name is a known entity","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  allNamedEntitiesSetOnly,\n  allNamedEntitiesSetOnlyCaseInsensitive,\n} from \"all-named-html-entities\";\n\nassert.equal(allNamedEntitiesSetOnly.has(\"AElig\"), true);\nassert.equal(allNamedEntitiesSetOnly.has(\"aelig\"), true);\nassert.equal(allNamedEntitiesSetOnlyCaseInsensitive.has(\"aelig\"), true);\nassert.equal(allNamedEntitiesSetOnlyCaseInsensitive.has(\"AElig\"), false);"}},"array-group-str-omit-num-char":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { groupStr } from \"array-group-str-omit-num-char\";\n\nassert.deepEqual(groupStr([\"a1-1\", \"a2-2\", \"b3-3\", \"c4-4\"]), {\n  \"a*-*\": 2,\n  \"b3-3\": 1,\n  \"c4-4\": 1,\n});"},"custom-wildcard.js":{"title":"Use a custom wildcard in grouped patterns","code":"import { strict as assert } from \"node:assert\";\n\nimport { groupStr } from \"array-group-str-omit-num-char\";\n\nassert.deepEqual(\n  groupStr([\"width-1\", \"width-2\", \"height-1\", \"height-2\"], {\n    wildcard: \"{n}\",\n  }),\n  {\n    \"width-{n}\": 2,\n    \"height-{n}\": 2,\n  },\n);"},"keep-duplicates.js":{"title":"Count duplicate strings instead of deduplicating them","code":"import { strict as assert } from \"node:assert\";\n\nimport { groupStr } from \"array-group-str-omit-num-char\";\n\nassert.deepEqual(\n  groupStr([\"item-1\", \"item-1\", \"item-1\"], {\n    dedupePlease: false,\n  }),\n  {\n    \"item-1\": 3,\n  },\n);"},"preserve-constant-numbers.js":{"title":"Preserve numeric chunks that stay constant across a group","code":"import { strict as assert } from \"node:assert\";\n\nimport { groupStr } from \"array-group-str-omit-num-char\";\n\nassert.deepEqual(\n  groupStr([\"width425-margin1px\", \"width425-margin2px\", \"width425-margin3px\"]),\n  {\n    \"width425-margin*px\": 3,\n  },\n);"},"strings-without-numbers.js":{"title":"Keep strings that contain no numeric chunks","code":"import { strict as assert } from \"node:assert\";\n\nimport { groupStr } from \"array-group-str-omit-num-char\";\n\nassert.deepEqual(groupStr([\"alpha\", \"beta\", \"alpha\"]), {\n  alpha: 1,\n  beta: 1,\n});"}},"array-includes-with-glob":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { includesWithGlob } from \"array-includes-with-glob\";\n\nassert.equal(includesWithGlob([\"xc\", \"yc\", \"zc\"], \"*c\"), true);"},"arrayVsArrayAllMustBeFound.js":{"title":"`opts.arrayVsArrayAllMustBeFound`","code":"import { strict as assert } from \"node:assert\";\n\nimport { includesWithGlob } from \"array-includes-with-glob\";\n\nconst source = [\"aaa\", \"bbb\", \"ccc\"];\nconst whatToLookFor = [\"a*\", \"d*\"];\n\n// the default setting for opts.arrayVsArrayAllMustBeFound is \"any\"\nassert.equal(includesWithGlob(source, whatToLookFor), true);\nassert.equal(\n  includesWithGlob(source, whatToLookFor, {\n    arrayVsArrayAllMustBeFound: \"any\",\n  }),\n  true,\n);\n// true, because one element, 'a*' was found in source (it was its first element)\n\nassert.equal(\n  includesWithGlob(source, whatToLookFor, {\n    arrayVsArrayAllMustBeFound: \"all\",\n  }),\n  false,\n);\n// false, because not all elements were found, the 'd*' is missing"},"case-insensitive.js":{"title":"Match glob patterns without matching letter case","code":"import { strict as assert } from \"node:assert\";\n\nimport { includesWithGlob } from \"array-includes-with-glob\";\n\nassert.equal(\n  includesWithGlob([\"README.md\"], \"read*.MD\", { caseSensitive: false }),\n  true,\n);"},"no-match.js":{"title":"Handle a glob that matches no array items","code":"import { strict as assert } from \"node:assert\";\n\nimport { includesWithGlob } from \"array-includes-with-glob\";\n\nassert.equal(includesWithGlob([\"xc\", \"yc\", \"zc\"], \"*a\"), false);"},"string-input.js":{"title":"Match a glob against a single string","code":"import { strict as assert } from \"node:assert\";\n\nimport { includesWithGlob } from \"array-includes-with-glob\";\n\nassert.equal(includesWithGlob(\"src/main.ts\", \"src/*.ts\"), true);"}},"array-pull-all-with-glob":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { pull } from \"array-pull-all-with-glob\";\n\nassert.deepEqual(\n  pull(\n    [\"keep_me\", \"name-1\", \"name-2\", \"name-jhkgdhgkhdfghdkghfdk\"],\n    [\"name-*\"],\n  ),\n  [\"keep_me\"],\n);"},"case-insensitive.js":{"title":"Match removal patterns without regard to letter case","code":"import { strict as assert } from \"node:assert\";\n\nimport { pull } from \"array-pull-all-with-glob\";\n\nassert.deepEqual(\n  pull([\"Draft.md\", \"README.md\", \"notes.txt\"], [\"*.MD\"], {\n    caseSensitive: false,\n  }),\n  [\"notes.txt\"],\n);"},"multiple-patterns.js":{"title":"Remove values that match any of several patterns","code":"import { strict as assert } from \"node:assert\";\n\nimport { pull } from \"array-pull-all-with-glob\";\n\nassert.deepEqual(\n  pull(\n    [\"app.js\", \"app.test.js\", \"readme.md\", \"notes.txt\"],\n    [\"*.test.js\", \"*.md\"],\n  ),\n  [\"app.js\", \"notes.txt\"],\n);"},"remove-everything.js":{"title":"Remove every value with the catch-all glob","code":"import { strict as assert } from \"node:assert\";\n\nimport { pull } from \"array-pull-all-with-glob\";\n\nassert.deepEqual(pull([\"one\", \"two\", \"three\"], \"*\"), []);"},"string-pattern.js":{"title":"Pass one removal pattern as a string","code":"import { strict as assert } from \"node:assert\";\n\nimport { pull } from \"array-pull-all-with-glob\";\n\nassert.deepEqual(pull([\"keep\", \"temp-1\", \"temp-2\"], \"temp-*\"), [\"keep\"]);"}},"arrayiffy-if-string":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { arrayiffy } from \"arrayiffy-if-string\";\n\nassert.deepEqual(arrayiffy(\"aaa\"), [\"aaa\"]);"},"empty-string.js":{"title":"Turn an empty string into an empty array","code":"import { strict as assert } from \"node:assert\";\n\nimport { arrayiffy } from \"arrayiffy-if-string\";\n\nassert.deepEqual(arrayiffy(\"\"), []);"},"pass-through-non-strings.js":{"title":"Pass non-string values through untouched","code":"import { strict as assert } from \"node:assert\";\n\nimport { arrayiffy } from \"arrayiffy-if-string\";\n\nconst config = { enabled: true };\n\nassert.equal(arrayiffy(config), config);\nassert.equal(arrayiffy(42), 42);\nassert.equal(arrayiffy(null), null);"}},"ast-compare":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\n// Check whether the second nested value is equal to, or a subset of, the first.\nassert.equal(\n  compare(\n    {\n      a: {\n        b: \"d\",\n        c: [],\n        e: \"f\",\n        g: \"h\",\n      },\n    },\n    {\n      a: {\n        b: \"d\",\n        c: [],\n      },\n    },\n  ),\n  true,\n);"},"compare-arrays.js":{"title":"Compare Arrays","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\nassert.equal(compare([\"a\", \"b\", \"c\"], [\"a\", \"b\"]), true);\n// true, because second is a subset of first\n\nassert.equal(compare([\"a\", \"b\", \"c\"], [\"b\", \"a\"]), false);\n// => false, because order is wrong\n\nassert.equal(compare([\"a\", \"b\"], [\"a\", \"b\", \"c\"]), false);\n// => false, because second is not a subset of first (it's opposite)\n\nassert.equal(\n  compare([{ a: \"b\" }, { c: \"d\" }, { e: \"f\" }], [{ a: \"b\" }, { c: \"d\" }]),\n  true,\n);\n// => plain objects nested in arrays"},"compare-objects.js":{"title":"Compare Plain Objects","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\n// Check whether the second object is equal to, or a subset of, the first.\nassert.equal(compare({ a: \"1\", b: \"2\", c: \"3\" }, { a: \"1\", b: \"2\" }), true);\n// true, because the second object is a subset of the first object.\n\nassert.equal(compare({ a: \"1\", b: \"2\" }, { a: \"1\", b: \"2\", c: \"3\" }), false);\n// false, because the second object is not a subset of the first object."},"compare-strings.js":{"title":"Compare Strings","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\nassert.equal(compare(\"a\\nb\", \"a\\nb\"), true);\n\nassert.equal(compare(\"a\", \"b\"), false);"},"opts-arrayOrder.js":{"title":"`opts.arrayOrder`","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\n// Array order stays significant by default, but can be ignored at every depth:\nassert.equal(\n  compare([\"first\", \"second\"], [\"second\", \"first\"], {\n    arrayOrder: \"any\",\n  }),\n  true,\n);"},"opts-hungryForWhitespace.js":{"title":"`opts.hungryForWhitespace`","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\n// by default, key values will be strictly matched using `===`\nassert.equal(\n  compare(\n    { a: \"\\n\\n\\n\", b: \"\\t\\t\\t\", c: \"whatever\" },\n    { a: \"\\r\\r\\r\", b: \"       \" },\n    {\n      hungryForWhitespace: false,\n    },\n  ),\n  false,\n);\n\n// whitespace is matched leniently with the following option:\nassert.equal(\n  compare(\n    { a: \"\\n\\n\\n\", b: \"\\t\\t\\t\", c: \"whatever\" },\n    { a: \"\\r\\r\\r\", b: \"       \" },\n    {\n      hungryForWhitespace: true,\n    },\n  ),\n  true,\n);\n\n// Empty structures containing only whitespace strings also match:\nassert.equal(\n  compare(\n    { a: { z: \"\\n\\n\\n\" }, b: [\"\\t\\t\\t\"], c: \"whatever\" },\n    { a: [[[[[\"\\r\\r\\r\"]]]]], b: { c: { d: \" \" } } },\n    {\n      hungryForWhitespace: true, // <--- !\n    },\n  ),\n  true, // <--- !!!\n);\n// An empty value is:\n//   - string that trims to zero-length\n//   - array with zero or more whitespace strings only\n//   - plain object with zero or more keys with \"empty\" values\n//     (empty arrays, empty plain objects or empty strings)"},"opts-matchStrictly.js":{"title":"`opts.matchStrictly`","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\nconst complete = { name: \"Ada\", role: \"admin\" };\nconst subset = { name: \"Ada\" };\n\nassert.equal(compare(complete, subset), true);\nassert.equal(compare(complete, subset, { matchStrictly: true }), false);"},"opts-useWildcards.js":{"title":"`opts.useWildcards`","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\n// By default, string values are compared literally.\nassert.equal(\n  compare(\n    { a: \"1\", b: \"2a\", c: \"3\" },\n    { a: \"1\", b: \"2*\" },\n    { useWildcards: false },\n  ),\n  false,\n);\n\n// once enabled, strings use wildcard matching, where \"*\" means any sequence\n// of characters\nassert.equal(\n  compare(\n    { a: \"1\", b: \"2a\", c: \"3\" },\n    { a: \"1\", b: \"2*\" },\n    { useWildcards: true },\n  ),\n  true,\n);"},"opts-verboseWhenMismatches.js":{"title":"`opts.verboseWhenMismatches`","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\n// by default, returns a boolean without explanation\nassert.equal(\n  compare(\n    { a: \"1\", b: \"2\" },\n    { a: \"1\", b: \"2\", c: \"3\" },\n    {\n      verboseWhenMismatches: false, // <---\n    },\n  ),\n  false,\n);\n\nconst mismatch = compare(\n  { a: \"1\", b: \"2\" },\n  { a: \"1\", b: \"2\", c: \"3\" },\n  {\n    verboseWhenMismatches: true, // <---\n  },\n);\nassert.equal(typeof mismatch, \"string\");\n\n// when opts.verboseWhenMismatches is enabled, a negative result is\n// string (explanation). A positive result is boolean \"true\".\nassert.equal(\n  compare(\n    { a: \"1\", b: \"2\" },\n    { a: \"1\", b: \"2\" },\n    {\n      verboseWhenMismatches: true, // <---\n    },\n  ),\n  true,\n);"},"report-completion.js":{"title":"Report deterministic work and elapsed time","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\nlet completion;\nassert.equal(\n  compare([\"alpha\", \"beta\"], [\"beta\", \"alpha\"], {\n    arrayOrder: \"any\",\n    reportCompletionFunc: (stats) => {\n      completion = stats;\n    },\n  }),\n  true,\n);\nassert.equal(completion.candidateComparisons, 4);\nassert.equal(completion.comparisons, 5);\nassert.equal(completion.matchingEdges, 2);\nassert.equal(typeof completion.timeTakenInMilliseconds, \"number\");"},"report-progress.js":{"title":"Report comparison progress","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\nconst progress = [];\nassert.equal(\n  compare([\"alpha\", \"beta\"], [\"beta\", \"alpha\"], {\n    arrayOrder: \"any\",\n    reportProgressFunc: (percentageDone) => progress.push(percentageDone),\n    reportProgressFuncFrom: 20,\n    reportProgressFuncTo: 40,\n  }),\n  true,\n);\nassert.deepEqual(progress, [20, 40]);"},"unordered-matches-consume-elements-once.js":{"title":"Match each unordered array element only once","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\nassert.equal(compare([\"a\", \"b\"], [\"a\", \"a\"], { arrayOrder: \"any\" }), false);\nassert.equal(compare([\"a\", \"a\"], [\"a\", \"a\"], { arrayOrder: \"any\" }), true);"},"unordered-nested-arrays.js":{"title":"Compare nested arrays without regard to order","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\nconst actual = {\n  groups: [\n    [1, 2],\n    [3, 4],\n  ],\n};\nconst expected = {\n  groups: [\n    [4, 3],\n    [2, 1],\n  ],\n};\n\nassert.equal(\n  compare(actual, expected, { arrayOrder: \"any\", matchStrictly: true }),\n  true,\n);"},"wildcards-in-object-keys.js":{"title":"Match object keys using wildcards","code":"import { strict as assert } from \"node:assert\";\n\nimport { compare } from \"ast-compare\";\n\n// A wildcard property matches one key and recursively compares its value.\nassert.equal(\n  compare(\n    { dataPrimary: 1, dataSecondary: 2, title: \"Example\" },\n    { \"data*\": 1 },\n    { useWildcards: true },\n  ),\n  true,\n);"}},"ast-contains-only-empty-space":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { empty } from \"ast-contains-only-empty-space\";\n\nassert.equal(\n  empty({\n    a: [\n      {\n        x: {\n          y: [\n            {\n              z: [\"\\n\"],\n            },\n          ],\n        },\n      },\n    ],\n    b: [\"\\t\\t\\t  \"],\n    c: [\"\\n \\n\\n\"],\n    d: [\"\\t   \"],\n  }),\n  true,\n);"},"non-object-values.js":{"title":"Non-object values","code":"import { strict as assert } from \"node:assert\";\n\nimport { empty } from \"ast-contains-only-empty-space\";\n\n// Only strings, arrays and plain objects are meaningful AST containers.\nassert.equal(empty(null), false);\nassert.equal(empty(true), false);\nassert.equal(\n  empty(() => {}),\n  false,\n);"},"non-plain-object.js":{"title":"Non-plain objects","code":"import { strict as assert } from \"node:assert\";\n\nimport { empty } from \"ast-contains-only-empty-space\";\n\n// Instances such as Date are meaningful opaque values, not empty containers.\nassert.equal(empty(new Date(0)), false);"},"report-completion.js":{"title":"Report completion statistics","code":"import { strict as assert } from \"node:assert\";\n\nimport { empty } from \"ast-contains-only-empty-space\";\n\nlet completion;\n\nassert.equal(\n  empty([\" \", { nested: \"\\n\" }], {\n    reportCompletionFunc: (stats) => {\n      completion = stats;\n    },\n  }),\n  true,\n);\nassert.equal(completion.arrayElementsVisited, 2);\nassert.equal(completion.objectPropertiesVisited, 1);\nassert.equal(completion.uniqueContainersVisited, 2);\nassert.equal(Object.isFrozen(completion), true);"},"report-progress.js":{"title":"Compose progress into a caller's range","code":"import { strict as assert } from \"node:assert\";\n\nimport { empty } from \"ast-contains-only-empty-space\";\n\nconst progress = [];\n\nassert.equal(\n  empty([\" \", { nested: [\"\\n\"] }], {\n    reportProgressFunc: (percentageDone) => {\n      progress.push(percentageDone);\n    },\n    reportProgressFuncFrom: 20,\n    reportProgressFuncTo: 80,\n  }),\n  true,\n);\nassert.equal(progress[0], 20);\nassert.equal(progress[progress.length - 1], 80);\nassert.equal(\n  progress.every((value, index) => index === 0 || value >= progress[index - 1]),\n  true,\n);"},"various.js":{"title":"Various","code":"import { strict as assert } from \"node:assert\";\n\nimport { empty } from \"ast-contains-only-empty-space\";\n\nassert.equal(empty([{ content: {} }]), true);\n\nassert.equal(empty([{ tag: \"style\" }]), false);\n\n// Works on simple arrays as well:\nassert.equal(empty([\"   \", \" \"]), true);\n\n// Works on strings as well:\nassert.equal(empty(\"   \"), true);\n\n// Empty arrays and plain objects are empty, but other leaves are meaningful:\nassert.equal(empty({ a: [] }), true);\nassert.equal(empty({ a: null }), false);"}},"ast-deep-contains":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { deepContains } from \"ast-deep-contains\";\n\nconst gathered = [];\nconst errors = [];\n\ndeepContains(\n  { title: \"Release notes\", author: \"Ada\", draft: false },\n  { title: \"Release notes\", author: \"Ada\" },\n  (leftSideVal, rightSideVal) => {\n    gathered.push([leftSideVal, rightSideVal]);\n  },\n  (err) => {\n    errors.push(err);\n  },\n);\n\nassert.deepEqual(gathered, [\n  [\"Release notes\", \"Release notes\"],\n  [\"Ada\", \"Ada\"],\n]);\nassert.equal(errors.length, 0);"},"include-containers.js":{"title":"Receive container values as well as leaf values","code":"import { strict as assert } from \"node:assert\";\n\nimport { deepContains } from \"ast-deep-contains\";\n\nconst gathered = [];\n\ndeepContains(\n  { section: { title: \"News\", count: 3 } },\n  { section: { title: \"News\" } },\n  (leftValue, rightValue, path) => {\n    gathered.push([leftValue, rightValue, path]);\n  },\n  assert.fail,\n  { skipContainers: false },\n);\n\nassert.deepEqual(gathered, [\n  [{ title: \"News\", count: 3 }, { title: \"News\" }, \"section\"],\n  [\"News\", \"News\", \"section.title\"],\n]);"},"missing-path.js":{"title":"Handle a path that is absent from the reference tree","code":"import { strict as assert } from \"node:assert\";\n\nimport { deepContains } from \"ast-deep-contains\";\n\nconst errors = [];\n\ndeepContains(\n  { title: \"Release notes\" },\n  { title: \"Release notes\", author: \"Ada\" },\n  () => {},\n  (message) => errors.push(message),\n);\n\nassert.equal(errors.length, 1);\nassert.match(errors[0], /does not have the path \"author\"/u);"},"strict-array-order.js":{"title":"Compare array elements at their exact positions","code":"import { strict as assert } from \"node:assert\";\n\nimport { deepContains } from \"ast-deep-contains\";\n\nconst mismatches = [];\n\ndeepContains(\n  [{ id: \"first\" }, { id: \"second\" }],\n  [{ id: \"second\" }, { id: \"first\" }],\n  (leftValue, rightValue) => {\n    if (leftValue !== rightValue) {\n      mismatches.push([leftValue, rightValue]);\n    }\n  },\n  assert.fail,\n  { arrayStrictComparison: true },\n);\n\nassert.deepEqual(mismatches, [\n  [\"first\", \"second\"],\n  [\"second\", \"first\"],\n]);"},"type-mismatch.js":{"title":"Handle inputs with different container types","code":"import { strict as assert } from \"node:assert\";\n\nimport { deepContains } from \"ast-deep-contains\";\n\nlet errorMessage = \"\";\n\ndeepContains(\n  [],\n  {},\n  () => {},\n  (message) => {\n    errorMessage = message;\n  },\n);\n\nassert.match(errorMessage, /first input arg is of a type array/u);\nassert.match(errorMessage, /second is object/u);"},"unordered-array-matching.js":{"title":"Match arrays of objects regardless of their order","code":"import { strict as assert } from \"node:assert\";\n\nimport { deepContains } from \"ast-deep-contains\";\n\nconst gathered = [];\nconst errors = [];\n\ndeepContains(\n  [{ c: \"2\" }, { a: \"1\", b: \"2\", c: \"3\" }, { x: \"8\", y: \"9\", z: \"0\" }],\n  [\n    { a: \"1\", b: \"2\", c: \"3\" },\n    { x: \"8\", y: \"9\" },\n  ],\n  (leftSideVal, rightSideVal) => {\n    gathered.push([leftSideVal, rightSideVal]);\n  },\n  (error) => {\n    errors.push(error);\n  },\n);\n\nassert.deepEqual(gathered, [\n  [\"1\", \"1\"],\n  [\"2\", \"2\"],\n  [\"3\", \"3\"],\n  [\"8\", \"8\"],\n  [\"9\", \"9\"],\n]);\nassert.equal(errors.length, 0);"}},"ast-delete-object":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteObj } from \"ast-delete-object\";\n\n// if all keys in source object match target object's keys, the\n// source object gets deleted:\nassert.deepEqual(\n  deleteObj(\n    [\n      \"elem1\",\n      {\n        findme1: \"zzz\",\n        findme2: \"yyy\",\n        somethingelse: \"qqq\",\n      },\n      \"elem2\",\n    ],\n    {\n      findme1: \"zzz\",\n      findme2: \"yyy\",\n    },\n  ),\n  [\"elem1\", \"elem2\"],\n);"},"delete-empty-objects.js":{"title":"Delete empty objects throughout a tree","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteObj } from \"ast-delete-object\";\n\nassert.deepEqual(deleteObj([{}, { content: \"kept\" }, {}], {}), [\n  { content: \"kept\" },\n]);"},"delete-multiple-matches.js":{"title":"Delete every object that contains the requested pair","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteObj } from \"ast-delete-object\";\n\nassert.deepEqual(\n  deleteObj(\n    [\n      { remove: true, id: 1 },\n      { remove: false, id: 2 },\n      { remove: true, id: 3 },\n    ],\n    { remove: true },\n  ),\n  [{ remove: false, id: 2 }],\n);"},"delete-nested-object.js":{"title":"Delete a matching object nested under another object","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteObj } from \"ast-delete-object\";\n\nassert.deepEqual(\n  deleteObj(\n    {\n      title: \"Example\",\n      metadata: { internal: true, owner: \"Docs\" },\n    },\n    { internal: true },\n  ),\n  { title: \"Example\" },\n);"},"delete-root-object.js":{"title":"Delete the root object when it contains the requested key-value pairs","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteObj } from \"ast-delete-object\";\n\nassert.deepEqual(\n  deleteObj({ status: \"draft\", title: \"Example\" }, { status: \"draft\" }),\n  {},\n);"},"keep-whitespace-only-objects.js":{"title":"Keep whitespace-only objects when hungry matching is disabled","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteObj } from \"ast-delete-object\";\n\nconst source = [{ a: \"\\n\" }, { key: \"value\" }, { b: \"   \" }, { c: \"\" }];\n\nassert.deepEqual(\n  deleteObj(\n    source,\n    {},\n    {\n      matchKeysStrictly: false,\n      hungryForWhitespace: false,\n    },\n  ),\n  source,\n);"},"opts-hungryForWhitespace.js":{"title":"`opts.hungryForWhitespace`","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteObj } from \"ast-delete-object\";\n\nassert.deepEqual(\n  deleteObj(\n    [\n      { a: \"\\n\" }, // that's empty\n      {\n        key3: \"val3\",\n        key4: \"val4\",\n      },\n      { b: \"   \" }, // that's empty\n      { c: \"\" }, // that's empty\n    ],\n    {}, // empty thing to match again - we match \"empty\" vs \"empty\"\n    { matchKeysStrictly: false, hungryForWhitespace: true },\n  ),\n  [\n    {\n      key3: \"val3\",\n      key4: \"val4\",\n    },\n  ],\n);"},"opts-matchKeysStrictly.js":{"title":"`opts.matchKeysStrictly`","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteObj } from \"ast-delete-object\";\n\nconst source = [\n  \"elem1\",\n  {\n    findme1: \"zzz\",\n    findme2: \"yyy\",\n    somethingelse: \"qqq\", // <--- this key will block deletion\n  },\n  \"elem2\",\n];\n\n// nothing happens - matching was strict\nassert.deepEqual(\n  deleteObj(\n    source,\n    {\n      findme1: \"zzz\",\n      findme2: \"yyy\",\n    },\n    {\n      matchKeysStrictly: true, // <--- strict matching\n    },\n  ),\n  source,\n);"},"relaxed-key-matching.js":{"title":"Delete an object that contains additional keys","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteObj } from \"ast-delete-object\";\n\nconst source = [\n  \"before\",\n  { findme1: \"zzz\", findme2: \"yyy\", additional: \"value\" },\n  \"after\",\n];\n\nassert.deepEqual(\n  deleteObj(\n    source,\n    { findme1: \"zzz\", findme2: \"yyy\" },\n    { matchKeysStrictly: false },\n  ),\n  [\"before\", \"after\"],\n);"}},"ast-get-object":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { getObj } from \"ast-get-object\";\n\n// Get matching objects using two input arguments\nassert.deepEqual(\n  getObj(\n    [\n      // <- search in this, the first argument, in this case, a nested array\n      {\n        tag: \"meta\",\n        content: \"UTF-8\",\n        something: \"else\",\n      },\n      {\n        tag: \"title\",\n        attrs: \"Text of the title\",\n      },\n    ],\n    {\n      // <- search for this object, the second argument\n      tag: \"meta\",\n    },\n  ),\n  [\n    {\n      tag: \"meta\",\n      content: \"UTF-8\",\n      something: \"else\",\n    },\n  ],\n);"},"get-multiple-matches.js":{"title":"Find every matching object in a nested AST","code":"import { strict as assert } from \"node:assert\";\n\nimport { getObj } from \"ast-get-object\";\n\nassert.deepEqual(\n  getObj(\n    [\n      { type: \"text\", value: \"Title\" },\n      { children: [{ type: \"text\", value: \"Body\" }] },\n    ],\n    { type: \"text\" },\n  ),\n  [\n    { type: \"text\", value: \"Title\" },\n    { type: \"text\", value: \"Body\" },\n  ],\n);"},"get-nested-value.js":{"title":"Match an object by a nested value","code":"import { strict as assert } from \"node:assert\";\n\nimport { getObj } from \"ast-get-object\";\n\nassert.deepEqual(\n  getObj(\n    [\n      { type: \"page\", meta: { author: \"Ada\", draft: false } },\n      { type: \"page\", meta: { author: \"Grace\", draft: true } },\n    ],\n    { meta: { author: \"Ada\" } },\n  ),\n  [{ type: \"page\", meta: { author: \"Ada\", draft: false } }],\n);"},"remove-matched-property.js":{"title":"Replace a match with an object that omits an unwanted property","code":"import { strict as assert } from \"node:assert\";\n\nimport { getObj } from \"ast-get-object\";\n\nassert.deepEqual(\n  getObj(\n    [{ tag: [[\"meta\"]], content: \"UTF-8\", obsolete: true }],\n    { tag: [[\"meta\"]] },\n    [{ content: \"UTF-8\" }],\n  ),\n  [{ content: \"UTF-8\" }],\n);"},"replace-multiple-matches.js":{"title":"Replace matching objects in traversal order","code":"import { strict as assert } from \"node:assert\";\n\nimport { getObj } from \"ast-get-object\";\n\nassert.deepEqual(\n  getObj(\n    [\n      { type: \"text\", value: \"old heading\" },\n      { children: [{ type: \"text\", value: \"old body\" }] },\n    ],\n    { type: \"text\" },\n    [\n      { type: \"text\", value: \"new heading\" },\n      { type: \"text\", value: \"new body\" },\n    ],\n  ),\n  [\n    { type: \"text\", value: \"new heading\" },\n    { children: [{ type: \"text\", value: \"new body\" }] },\n  ],\n);"}},"ast-get-values-by-key":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { getByKey } from \"ast-get-values-by-key\";\n\n// returns \"object-path\" notation paths where arrays use dots:\nassert.deepEqual(\n  getByKey(\n    {\n      parsed: [\n        {\n          tag: \"html\",\n        },\n      ],\n    },\n    \"tag\", // value to search for\n  ),\n  [{ val: \"html\", path: \"parsed.0.tag\" }],\n);"},"case-sensitive-key-match.js":{"title":"Match keys case-sensitively","code":"import { strict as assert } from \"node:assert\";\n\nimport { getByKey } from \"ast-get-values-by-key\";\n\nassert.deepEqual(getByKey({ tag: \"lower\", Tag: \"upper\" }, \"tag\"), [\n  { val: \"lower\", path: \"tag\" },\n]);"},"multiple-key-patterns.js":{"title":"Fetch the values of several keys at once","code":"import { strict as assert } from \"node:assert\";\n\nimport { getByKey } from \"ast-get-values-by-key\";\n\nassert.deepEqual(\n  getByKey(\n    {\n      firstName: \"Ada\",\n      lastName: \"Lovelace\",\n      age: 36,\n    },\n    [\"firstName\", \"lastName\"],\n  ),\n  [\n    { val: \"Ada\", path: \"firstName\" },\n    { val: \"Lovelace\", path: \"lastName\" },\n  ],\n);"},"real-use.js":{"title":"Replace all null's in keys `amount` with zero, but only under `orders`","code":"import { strict as assert } from \"node:assert\";\n\nimport { getByKey } from \"ast-get-values-by-key\";\n\nconst source = {\n  orders: [\n    {\n      date: \"2020-09-26\",\n      amount: null, // replace\n      product: \"Bramble\",\n    },\n    {\n      date: \"2020-09-26\",\n      amount: 2,\n      product: \"Croodle\",\n    },\n    {\n      date: \"2020-09-26\",\n      amount: null, // replace\n      product: \"Zapple\",\n    },\n  ],\n};\n\n// first GET\nconst findings = getByKey(\n  source, // what to process\n  \"amount\", // what to look for\n);\nassert.equal(findings.length, 3);\n\n// prepare replacement array for SET third input argument\nconst replacement = findings.map(({ val }) => +val);\nassert.equal(replacement.join(\",\"), \"0,2,0\");\n\n// then SET\nconst result = getByKey(\n  source, // what to process\n  \"amount\", // what to look for\n  replacement, // pot of replacement values to consume (single-use, FIFO stack)\n);\nassert.deepEqual(result, {\n  orders: [\n    {\n      date: \"2020-09-26\",\n      amount: 0, // replace\n      product: \"Bramble\",\n    },\n    {\n      date: \"2020-09-26\",\n      amount: 2,\n      product: \"Croodle\",\n    },\n    {\n      date: \"2020-09-26\",\n      amount: 0, // replace\n      product: \"Zapple\",\n    },\n  ],\n});"},"replace-matches-in-order.js":{"title":"Replace each match with the next value in the array","code":"import { strict as assert } from \"node:assert\";\n\nimport { getByKey } from \"ast-get-values-by-key\";\n\nassert.deepEqual(\n  getByKey(\n    {\n      parsed: [{ tag: \"html\" }],\n      foo: { tag: null },\n      bar: { tag: null },\n    },\n    \"tag\",\n    [123, 456],\n  ),\n  {\n    parsed: [{ tag: 123 }],\n    foo: { tag: 456 },\n    bar: { tag: null },\n  },\n);"},"scalar-replacement-is-used-once.js":{"title":"A single replacement value is used only once","code":"import { strict as assert } from \"node:assert\";\n\nimport { getByKey } from \"ast-get-values-by-key\";\n\nassert.deepEqual(\n  getByKey(\n    {\n      first: { status: \"pending\" },\n      second: { status: \"pending\" },\n    },\n    \"status\",\n    \"done\",\n  ),\n  {\n    first: { status: \"done\" },\n    second: { status: \"pending\" },\n  },\n);"},"wildcard-setter.js":{"title":"Set the values of keys matched by a wildcard","code":"import { strict as assert } from \"node:assert\";\n\nimport { getByKey } from \"ast-get-values-by-key\";\n\nconst source = {\n  popsicles: 1,\n  tentacles: 0,\n  nested: [{ cutticles: \"yes\" }],\n};\n\nassert.deepEqual(getByKey(source, [\"*cles\"], [\"a\", \"b\", \"c\"]), {\n  popsicles: \"a\",\n  tentacles: \"b\",\n  nested: [{ cutticles: \"c\" }],\n});"},"wildcards.js":{"title":"Using wildcard patterns","code":"import { strict as assert } from \"node:assert\";\n\nimport { getByKey } from \"ast-get-values-by-key\";\n\nconst source = {\n  popsicles: 1,\n  tentacles: 0,\n  nested: [\n    {\n      cutticles: \"yes\",\n    },\n  ],\n};\n\nconst findings = getByKey(source, [\"*cles\"]);\n\nassert.deepEqual(findings, [\n  {\n    val: 1,\n    path: \"popsicles\",\n  },\n  {\n    val: 0,\n    path: \"tentacles\",\n  },\n  {\n    val: \"yes\",\n    path: \"nested.0.cutticles\",\n  },\n]);"}},"ast-is-empty":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { isEmpty } from \"ast-is-empty\";\n\nassert.equal(\n  isEmpty({\n    a: \"\",\n  }),\n  true,\n);"},"graphs.js":{"title":"Terminate on cycles and reuse completed shared subtrees","code":"import { strict as assert } from \"node:assert\";\n\nimport { isEmpty } from \"ast-is-empty\";\n\nconst cycle = {};\ncycle.self = cycle;\nassert.equal(isEmpty(cycle), null);\n\nconst shared = { value: \"\" };\nassert.equal(isEmpty([shared, shared]), true);"},"nested-empty-structures.js":{"title":"Recognise a tree made only from empty strings and containers","code":"import { strict as assert } from \"node:assert\";\n\nimport { isEmpty } from \"ast-is-empty\";\n\nassert.equal(isEmpty({ sections: [{ title: \"\", children: [\"\", {}] }] }), true);"},"report-completion.js":{"title":"Inspect frozen completion statistics","code":"import { strict as assert } from \"node:assert\";\n\nimport { isEmpty } from \"ast-is-empty\";\n\nlet completion;\nassert.equal(\n  isEmpty({ title: \"\", children: [\"\"] }, {\n    reportCompletionFunc(stats) {\n      completion = stats;\n    },\n  }),\n  true,\n);\nassert.equal(completion.uniqueContainersVisited, 2);\nassert.equal(completion.objectPropertiesVisited, 2);\nassert.equal(completion.arrayElementsVisited, 1);\nassert.equal(Object.isFrozen(completion), true);"},"report-progress.js":{"title":"Compose progress reporting into a caller's range","code":"import { strict as assert } from \"node:assert\";\n\nimport { isEmpty } from \"ast-is-empty\";\n\nconst progress = [];\nassert.equal(\n  isEmpty([\"\", { value: \"\" }], {\n    reportProgressFunc(percentageDone) {\n      progress.push(percentageDone);\n    },\n    reportProgressFuncFrom: 25,\n    reportProgressFuncTo: 50,\n  }),\n  true,\n);\nassert.equal(progress[0], 25);\nassert.equal(progress[progress.length - 1], 50);"},"unsupported-values.js":{"title":"Return null when the tree contains an unsupported value type","code":"import { strict as assert } from \"node:assert\";\n\nimport { isEmpty } from \"ast-is-empty\";\n\nassert.equal(isEmpty({ title: \"\", count: 0 }), null);\nassert.equal(isEmpty({ title: \"visible\", count: 0 }), null);\nassert.equal(isEmpty({ count: 0, title: \"visible\" }), null);\nassert.equal(isEmpty(null), null);"},"whitespace-is-content.js":{"title":"Treat whitespace-only strings as content","code":"import { strict as assert } from \"node:assert\";\n\nimport { isEmpty } from \"ast-is-empty\";\n\nassert.equal(isEmpty({ title: \"\", body: \" \" }), false);"}},"ast-loose-compare":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { looseCompare } from \"ast-loose-compare\";\n\nassert.equal(\n  looseCompare(\n    {\n      a: {\n        b: \"d\",\n        c: [],\n        e: \"f\",\n        g: \"h\",\n      },\n    },\n    {\n      a: {\n        b: \"d\",\n        c: [],\n      },\n    },\n  ),\n  true,\n);"},"empty-values-across-types.js":{"title":"Treat structurally different empty values as equivalent","code":"import { strict as assert } from \"node:assert\";\n\nimport { looseCompare } from \"ast-loose-compare\";\n\nassert.equal(looseCompare([], {}), true);"},"more-examples.js":{"title":"More Examples","code":"import { strict as assert } from \"node:assert\";\n\nimport { looseCompare } from \"ast-loose-compare\";\n\nassert.equal(\n  looseCompare({ a: \"1\", b: \"2\", c: \"3\" }, { a: \"1\", b: \"2\" }),\n  true,\n);\n// true, because second (smallObj) is subset of (or equal) first (bigObj).\n\nassert.equal(\n  looseCompare({ a: \"1\", b: \"2\" }, { a: \"1\", b: \"2\", c: \"3\" }),\n  false,\n);\n// false, because second (smallObj) is not a subset (or equal) to first (bigObj).\n\nassert.equal(looseCompare([\"a\", \"b\", \"c\"], [\"a\", \"b\"]), true);\n// true, because second is a subset of first\n\nassert.equal(looseCompare([\"a\", \"b\"], [\"a\", \"b\", \"c\"]), false);\n// false, because second is not a subset of first\n\nassert.equal(looseCompare(\"aaaaa\\nbbbbb\", \"aaaaa\\nbbbbb\"), true);\n// true, because strings are equal\n\nassert.equal(looseCompare({ a: \"a\" }), undefined);\n// the second argument is missing"},"nested-array-subset.js":{"title":"Compare objects nested inside arrays as subsets","code":"import { strict as assert } from \"node:assert\";\n\nimport { looseCompare } from \"ast-loose-compare\";\n\nassert.equal(\n  looseCompare(\n    [{ type: \"link\", url: \"/docs\", title: \"Documentation\" }],\n    [{ type: \"link\", url: \"/docs\" }],\n  ),\n  true,\n);"},"whitespace.js":{"title":"Empty Values","code":"import { strict as assert } from \"node:assert\";\n\nimport { looseCompare } from \"ast-loose-compare\";\n\n// both values are empty - they trim() to zero-length\nassert.equal(\n  looseCompare(\n    {\n      a: \"a\",\n      b: \"\\n \\n\\n\",\n    },\n    {\n      a: \"a\",\n      b: \"\\t\\t \\t\",\n    },\n  ),\n  true,\n);"}},"ast-monkey":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { find } from \"ast-monkey\";\n\nassert.deepEqual(\n  find(\n    {\n      a1: {\n        b1: \"c1\",\n      },\n      a2: {\n        b2: \"c2\",\n      },\n      z1: {\n        x1: \"y1\",\n      },\n    },\n    { key: \"a*\" },\n  ),\n  [\n    {\n      index: 1,\n      key: \"a1\",\n      val: {\n        b1: \"c1\",\n      },\n      path: [1],\n    },\n    {\n      index: 3,\n      key: \"a2\",\n      val: {\n        b2: \"c2\",\n      },\n      path: [3],\n    },\n  ],\n);"},"delete-array-values-only.js":{"title":"Delete matches from arrays only","code":"import { strict as assert } from \"node:assert\";\n\nimport { del } from \"ast-monkey\";\n\nassert.deepEqual(\n  del(\n    { status: \"draft\", history: [\"draft\", \"published\"] },\n    {\n      key: \"draft\",\n      only: \"array\",\n    },\n  ),\n  { status: \"draft\", history: [\"published\"] },\n);"},"delete-by-key.js":{"title":"Delete every object key of a given name","code":"import { strict as assert } from \"node:assert\";\n\nimport { del } from \"ast-monkey\";\n\nassert.deepEqual(\n  del(\n    {\n      user: { password: \"secret\", name: \"Ada\" },\n      metadata: { password: \"legacy\" },\n    },\n    { key: \"password\" },\n  ),\n  {\n    user: { name: \"Ada\" },\n    metadata: {},\n  },\n);"},"delete-by-value.js":{"title":"Delete nodes by value","code":"import { strict as assert } from \"node:assert\";\n\nimport { del } from \"ast-monkey\";\n\nassert.deepEqual(\n  del(\n    {\n      primary: { status: \"ready\" },\n      fallback: { status: \"waiting\" },\n    },\n    { val: { status: \"ready\" } },\n  ),\n  { fallback: { status: \"waiting\" } },\n);"},"drop-by-traversal-index.js":{"title":"Drop a node by its traversal index","code":"import { strict as assert } from \"node:assert\";\n\nimport { drop } from \"ast-monkey\";\n\nassert.deepEqual(drop({ user: { name: \"Ada\", active: false } }, { index: 2 }), {\n  user: { active: false },\n});"},"find-by-key-and-value.js":{"title":"Find nodes matching both a key and a value","code":"import { strict as assert } from \"node:assert\";\n\nimport { find } from \"ast-monkey\";\n\nconst findings = find(\n  {\n    first: { status: \"ready\" },\n    second: { status: \"waiting\" },\n  },\n  { key: \"status\", val: \"ready\" },\n);\n\nassert.equal(findings.length, 1);\nassert.equal(findings[0].key, \"status\");\nassert.equal(findings[0].val, \"ready\");"},"find-by-value.js":{"title":"Find nodes by value alone","code":"import { strict as assert } from \"node:assert\";\n\nimport { find } from \"ast-monkey\";\n\nconst findings = find(\n  {\n    primary: { status: \"ready\" },\n    fallback: { status: \"waiting\" },\n  },\n  { key: null, val: { status: \"ready\" } },\n);\n\nassert.equal(findings.length, 1);\nassert.equal(findings[0].key, \"primary\");\nassert.equal(findings[0].index, 1);"},"find-explicit-undefined.js":{"title":"Find explicit undefined values","code":"import { strict as assert } from \"node:assert\";\n\nimport { find } from \"ast-monkey\";\n\nassert.deepEqual(\n  find([undefined, \"present\"], {\n    criteria: { kind: \"value\", value: undefined },\n  }),\n  [{ index: 1, key: undefined, val: undefined, path: [1] }],\n);"},"find-only-array-items.js":{"title":"Search array elements only","code":"import { strict as assert } from \"node:assert\";\n\nimport { find } from \"ast-monkey\";\n\nassert.deepEqual(\n  find(\n    { objectValue: \"remove\", items: [\"keep\", \"remove\"] },\n    {\n      key: \"remove\",\n      only: \"array\",\n    },\n  ),\n  [\n    {\n      index: 4,\n      key: \"remove\",\n      val: undefined,\n      path: [2, 4],\n    },\n  ],\n);"},"find-only-object-properties.js":{"title":"Search object properties only","code":"import { strict as assert } from \"node:assert\";\n\nimport { find } from \"ast-monkey\";\n\nconst findings = find(\n  { objectValue: \"remove\", items: [\"keep\", \"remove\"] },\n  { val: \"remove\", only: \"object\" },\n);\n\nassert.equal(findings.length, 1);\nassert.equal(findings[0].key, \"objectValue\");"},"get-by-traversal-index.js":{"title":"Get a node by its traversal index","code":"import { strict as assert } from \"node:assert\";\n\nimport { get } from \"ast-monkey\";\n\nassert.deepEqual(get({ user: { name: \"Ada\" } }, { index: 2 }), {\n  name: \"Ada\",\n});"},"keep-first-array-elements.js":{"title":"Keep only the first element of every array","code":"import { strict as assert } from \"node:assert\";\n\nimport { arrayFirstOnly } from \"ast-monkey\";\n\nassert.deepEqual(\n  arrayFirstOnly({\n    users: [\n      { name: \"Ada\", roles: [\"admin\", \"author\"] },\n      { name: \"Grace\", roles: [\"reader\"] },\n    ],\n  }),\n  { users: [{ name: \"Ada\", roles: [\"admin\"] }] },\n);"},"set-by-traversal-index.js":{"title":"Set a node's value by its traversal index","code":"import { strict as assert } from \"node:assert\";\n\nimport { set } from \"ast-monkey\";\n\nassert.deepEqual(\n  set({ user: { name: \"Ada\", active: false } }, { index: 2, val: \"Grace\" }),\n  { user: { name: \"Grace\", active: false } },\n);"},"set-explicit-undefined.js":{"title":"Set a value to undefined","code":"import { strict as assert } from \"node:assert\";\n\nimport { set } from \"ast-monkey\";\n\nassert.deepEqual(set({ status: \"ready\" }, { index: 1, val: undefined }), {\n  status: undefined,\n});"},"set-using-key-value.js":{"title":"Set a node using `key` instead of `val`","code":"import { strict as assert } from \"node:assert\";\n\nimport { set } from \"ast-monkey\";\n\nassert.deepEqual(\n  set({ user: { name: \"Ada\", active: false } }, { index: \"2\", key: \"Grace\" }),\n  { user: { name: \"Grace\", active: false } },\n);"},"traverse-delete-token.js":{"title":"Delete during traversal with the collision-free token","code":"import { strict as assert } from \"node:assert\";\n\nimport { DELETE, traverse } from \"ast-monkey\";\n\nassert.deepEqual(\n  traverse([Number.NaN, \"remove\"], (value) =>\n    value === \"remove\" ? DELETE : value,\n  ),\n  [Number.NaN],\n);"},"traverse-re-export.js":{"title":"Traverse a tree using the re-exported `traverse`","code":"import { strict as assert } from \"node:assert\";\n\nimport { traverse } from \"ast-monkey\";\n\nconst result = traverse(\n  { count: 1, nested: { count: 2 } },\n  (key, value, innerObj) => {\n    const current = innerObj.parentType === \"object\" ? value : key;\n    return key === \"count\" ? current + 1 : current;\n  },\n);\n\nassert.deepEqual(result, { count: 2, nested: { count: 3 } });"}},"ast-monkey-traverse":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { traverse } from \"ast-monkey-traverse\";\n\nconst paths = [];\nconst source = {\n  a: {\n    foo: {\n      bar: [\n        {\n          foo: \"c\",\n        },\n      ],\n      d: {\n        e: {\n          foo: \"f\",\n        },\n      },\n    },\n  },\n};\n\ntraverse(source, (key, val, innerObj) => {\n  // Objects supply a property key and value; arrays supply the element as key.\n  let current = innerObj.parentType === \"object\" ? val : key;\n  if (\n    // it's object (not array)\n    innerObj.parentType === \"object\" &&\n    // and has the key we need\n    key === \"foo\"\n  ) {\n    // push the path to array in the outer scope\n    paths.push(innerObj.path);\n  }\n  return current;\n});\n\n// notice object-path notation \"a.foo.bar.0.foo\" - array segments use dots too:\nassert.deepEqual(paths, [\"a.foo\", \"a.foo.bar.0.foo\", \"a.foo.d.e.foo\"]);"},"collect-all-paths.js":{"title":"Collect the path of every visited node","code":"import { strict as assert } from \"node:assert\";\n\nimport { traverse } from \"ast-monkey-traverse\";\n\nconst paths = [];\n\ntraverse({ a: \"1\", b: { c: \"2\" } }, (key, value, metadata) => {\n  paths.push(metadata.path);\n  return metadata.parentType === \"object\" ? value : key;\n});\n\nassert.deepEqual(paths, [\"a\", \"b\", \"b.c\"]);"},"compatible-with-object-path.js":{"title":"Compatible With `object-path`","code":"import { strict as assert } from \"node:assert\";\nimport op from \"object-path\";\n\nimport { traverse } from \"ast-monkey-traverse\";\n\nconst input = { a: \"1\", b: [{ c: \"2\" }] };\nObject.freeze(input); // let's freeze it, just for fun\nconst result1 = [];\n\n// the full traversal would look like this:\ntraverse(input, (key1, val1, innerObj) => {\n  let current = innerObj.parentType === \"object\" ? val1 : key1;\n  result1.push(innerObj.path);\n  return current;\n});\n\n// Each reported path is fully compatible with `object-path` get(). Notice that\n// the path notation is \"b.0.c\", not \"b[0].c\".\nassert.deepEqual(\n  Object.fromEntries(result1.map((path) => [path, op.get(input, path)])),\n  {\n    a: \"1\",\n    b: [{ c: \"2\" }],\n    \"b.0\": { c: \"2\" },\n    \"b.0.c\": \"2\",\n  },\n);"},"delete-nodes-with-token.js":{"title":"Delete nodes with the collision-free token","code":"import { strict as assert } from \"node:assert\";\n\nimport { DELETE, traverse } from \"ast-monkey-traverse\";\n\nconst result = traverse(\n  { visible: \"keep\", private: \"remove\", items: [\"keep\", \"remove\"] },\n  (key, value, inner) => {\n    const current = inner.parentType === \"object\" ? value : key;\n    return key === \"private\" || current === \"remove\" ? DELETE : current;\n  },\n);\n\nassert.deepEqual(result, { visible: \"keep\", items: [\"keep\"] });"},"does-not-mutate-input.js":{"title":"Traverse without mutating the input","code":"import { strict as assert } from \"node:assert\";\n\nimport { traverse } from \"ast-monkey-traverse\";\n\nconst input = { count: 1 };\nconst result = traverse(input, (key, value) =>\n  key === \"count\" ? value + 1 : value,\n);\n\nassert.deepEqual(input, { count: 1 });\nassert.equal(result.count, 2);"},"inspect-parent-metadata.js":{"title":"Inspect each node's parent metadata","code":"import { strict as assert } from \"node:assert\";\n\nimport { traverse } from \"ast-monkey-traverse\";\n\nconst metadata = [];\n\ntraverse({ users: [{ name: \"Ada\" }] }, (key, value, inner) => {\n  const current = inner.parentType === \"object\" ? value : key;\n  metadata.push([inner.path, inner.depth, inner.parentType, inner.topmostKey]);\n  return current;\n});\n\nassert.deepEqual(metadata, [\n  [\"users\", 0, \"object\", \"users\"],\n  [\"users.0\", 1, \"array\", \"users\"],\n  [\"users.0.name\", 2, \"object\", \"users\"],\n]);"},"stopping.js":{"title":"Stop","code":"import { strict as assert } from \"node:assert\";\n\nimport { traverse } from \"ast-monkey-traverse\";\n\nconst input = { a: \"1\", b: { c: \"2\" } };\nconst result2 = [];\ntraverse(input, (key1, val1, innerObj, stop) => {\n  let current = innerObj.parentType === \"object\" ? val1 : key1;\n  result2.push(innerObj.path);\n  if (innerObj.path === \"b\") {\n    stop.now = true; // <---------------- !!!!!!!!!!\n  }\n  return current;\n});\nassert.deepEqual(result2, [\"a\", \"b\"]);"},"transform-values.js":{"title":"Transform values while traversing","code":"import { strict as assert } from \"node:assert\";\n\nimport { traverse } from \"ast-monkey-traverse\";\n\nconst result = traverse(\n  { price: 10, nested: { price: 20 } },\n  (key, value, inner) => {\n    const current = inner.parentType === \"object\" ? value : key;\n    return key === \"price\" ? current * 1.2 : current;\n  },\n);\n\nassert.deepEqual(result, { price: 12, nested: { price: 24 } });"}},"ast-monkey-traverse-with-lookahead":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { traverse } from \"ast-monkey-traverse-with-lookahead\";\n\nconst input = [{ a: \"b\" }, { c: \"d\" }];\nconst currentAndNextPaths = [];\n\ntraverse(\n  input,\n  (_key, _value, inner) => {\n    currentAndNextPaths.push([inner.path, inner.next[0]?.[2].path ?? null]);\n  },\n  1,\n);\n\nassert.deepEqual(currentAndNextPaths, [\n  [\"0\", \"0.a\"],\n  [\"0.a\", \"1\"],\n  [\"1\", \"1.c\"],\n  [\"1.c\", null],\n]);"},"default-zero-lookahead.js":{"title":"Look ahead by zero nodes by default","code":"import { strict as assert } from \"node:assert\";\n\nimport { traverse } from \"ast-monkey-traverse-with-lookahead\";\n\nconst nextLengths = [];\n\ntraverse({ first: 1, second: 2 }, (_key, _value, inner) => {\n  nextLengths.push(inner.next.length);\n});\n\nassert.deepEqual(nextLengths, [0, 0]);"},"inspect-node-metadata.js":{"title":"Inspect a node's metadata and its lookahead","code":"import { strict as assert } from \"node:assert\";\n\nimport { traverse } from \"ast-monkey-traverse-with-lookahead\";\n\nlet firstMetadata;\n\ntraverse(\n  [{ a: \"b\" }, { c: \"d\" }],\n  (_key, _value, inner, stop) => {\n    if (!firstMetadata) {\n      firstMetadata = inner;\n      stop.now = true;\n    }\n  },\n  1,\n);\n\nassert.deepEqual(firstMetadata, {\n  depth: 0,\n  path: \"0\",\n  parent: [{ a: \"b\" }, { c: \"d\" }],\n  parentType: \"array\",\n  next: [\n    [\n      \"a\",\n      \"b\",\n      {\n        depth: 1,\n        path: \"0.a\",\n        parent: { a: \"b\" },\n        parentType: \"object\",\n      },\n    ],\n  ],\n});"},"look-ahead-two-nodes.js":{"title":"Look ahead two nodes at a time","code":"import { strict as assert } from \"node:assert\";\n\nimport { traverse } from \"ast-monkey-traverse-with-lookahead\";\n\nconst upcomingPaths = [];\n\ntraverse(\n  { first: 1, second: 2, third: 3 },\n  (_key, _value, inner) => {\n    upcomingPaths.push(inner.next.map(([, , nextInner]) => nextInner.path));\n  },\n  2,\n);\n\nassert.deepEqual(upcomingPaths, [[\"second\", \"third\"], [\"third\"], []]);"},"stop-traversal.js":{"title":"Signal a stop from the traversal callback","code":"import { strict as assert } from \"node:assert\";\n\nimport { traverse } from \"ast-monkey-traverse-with-lookahead\";\n\nconst visited = [];\n\ntraverse(\n  { first: 1, second: 2, third: 3 },\n  (key, _value, _inner, stop) => {\n    visited.push(key);\n    if (key === \"second\") stop.now = true;\n  },\n  1,\n);\n\nassert.deepEqual(visited, [\"first\", \"second\", \"third\"]);"}},"ast-monkey-util":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { pathNext } from \"ast-monkey-util\";\n\nassert.equal(pathNext(\"9.children.3\"), \"9.children.4\");"},"parent-segment.js":{"title":"Find the parent segment","code":"import { strict as assert } from \"node:assert\";\n\nimport { parent } from \"ast-monkey-util\";\n\nassert.equal(parent(\"article.children.2.type\"), \"2\");\nassert.equal(parent(\"article\"), null);"},"path-next.js":{"title":"Move to the next sibling path","code":"import { strict as assert } from \"node:assert\";\n\nimport { pathNext } from \"ast-monkey-util\";\n\nassert.equal(pathNext(\"article.children.2\"), \"article.children.3\");\n\n// A path without a numeric final segment is left unchanged.\nassert.equal(pathNext(\"article.children\"), \"article.children\");"},"path-previous.js":{"title":"Move to the previous sibling path","code":"import { strict as assert } from \"node:assert\";\n\nimport { pathPrev } from \"ast-monkey-util\";\n\nassert.equal(pathPrev(\"article.children.2\"), \"article.children.1\");\nassert.equal(pathPrev(\"article.children.0\"), null);"},"path-up.js":{"title":"Move up one AST level","code":"import { strict as assert } from \"node:assert\";\n\nimport { pathUp } from \"ast-monkey-util\";\n\nassert.equal(pathUp(\"article.children.2.children.0\"), \"article.children.2\");\nassert.equal(pathUp(\"article.children.2\"), \"article\");\nassert.equal(pathUp(\"article\"), \"0\");"}},"charcode-is-valid-xml-name-character":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { validFirstChar } from \"charcode-is-valid-xml-name-character\";\n\n// Spec: https://www.w3.org/TR/REC-xml/#NT-NameStartChar\n\nassert.equal(validFirstChar(\"a\"), true);\nassert.equal(validFirstChar(\"1\"), false);"},"combining-mark-after-first-character.js":{"title":"Allow a combining mark after the first character","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  isProduction4,\n  isProduction4a,\n} from \"charcode-is-valid-xml-name-character\";\n\nconst combiningAcuteAccent = \"\\u0301\";\n\nassert.equal(isProduction4(combiningAcuteAccent), false);\nassert.equal(isProduction4a(combiningAcuteAccent), true);"},"name-character-production.js":{"title":"Check characters against the XML NameChar production","code":"import { strict as assert } from \"node:assert\";\n\nimport { isProduction4a } from \"charcode-is-valid-xml-name-character\";\n\nassert.equal(isProduction4a(\"?\"), false);\nassert.equal(isProduction4a(\"-\"), true);"},"name-start-production.js":{"title":"Check characters against the XML NameStartChar production","code":"import { strict as assert } from \"node:assert\";\n\nimport { isProduction4 } from \"charcode-is-valid-xml-name-character\";\n\nassert.equal(isProduction4(\"Z\"), true);\nassert.equal(isProduction4(\"?\"), false);"},"subsequent-name-character.js":{"title":"Validate a character after the first character in an XML name","code":"import { strict as assert } from \"node:assert\";\n\nimport { validSecondCharOnwards } from \"charcode-is-valid-xml-name-character\";\n\nassert.equal(validSecondCharOnwards(\"a\"), true);\nassert.equal(validSecondCharOnwards(\"?\"), false);"},"validate-an-xml-name.js":{"title":"Validate a whole XML name","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  validFirstChar,\n  validSecondCharOnwards,\n} from \"charcode-is-valid-xml-name-character\";\n\nfunction isValidXmlName(name) {\n  const [first, ...rest] = Array.from(name);\n  return (\n    Boolean(first) &&\n    validFirstChar(first) &&\n    rest.every(validSecondCharOnwards)\n  );\n}\n\nassert.equal(isValidXmlName(\"article-1\"), true);\nassert.equal(isValidXmlName(\"1-article\"), false);"}},"check-types-mini":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { checkTypesMini } from \"check-types-mini\";\n\nassert.throws(\n  () => {\n    checkTypesMini(\n      {\n        // object to check\n        option1: \"setting1\",\n        option2: \"false\",\n        option3: false,\n      },\n      {\n        // reference defaults object\n        option1: \"setting1\",\n        option2: false,\n        option3: false,\n      },\n    );\n  },\n  (err) => {\n    assert(/not boolean but string/.test(err));\n    return true;\n  },\n);"},"accept-arrays-ignore.js":{"title":"Exclude selected paths from array acceptance","code":"import { strict as assert } from \"node:assert\";\n\nimport { checkTypesMini } from \"check-types-mini\";\n\nassert.throws(() => {\n  checkTypesMini(\n    { extensions: [\"js\", \"ts\"], aliases: [\"src\"] },\n    { extensions: \"js\", aliases: \"src\" },\n    {\n      acceptArrays: true,\n      acceptArraysIgnore: \"extensions\",\n    },\n  );\n}, /opts\\.extensions was customised/);"},"accept-arrays.js":{"title":"Accept arrays of the reference value's type","code":"import { strict as assert } from \"node:assert\";\n\nimport { checkTypesMini } from \"check-types-mini\";\n\nassert.doesNotThrow(() => {\n  checkTypesMini(\n    { extensions: [\"js\", \"ts\"] },\n    { extensions: \"js\" },\n    { acceptArrays: true },\n  );\n});"},"any-schema.js":{"title":"Allow any shape below a schema path","code":"import { strict as assert } from \"node:assert\";\n\nimport { checkTypesMini } from \"check-types-mini\";\n\nassert.doesNotThrow(() => {\n  checkTypesMini(\n    { metadata: { deeply: { nested: [1, true, null] } } },\n    { metadata: \"placeholder\" },\n    { schema: { metadata: \"any\" } },\n  );\n});"},"custom-error-context.js":{"title":"Customise validation error context","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  CheckTypesMiniError,\n  checkTypesMini,\n} from \"check-types-mini\";\n\nassert.throws(\n  () => {\n    checkTypesMini(\n      { enabled: \"yes\" },\n      { enabled: false },\n      { msg: \"buildConfig\", optsVarName: \"config\" },\n    );\n  },\n  (error) => {\n    assert(error instanceof CheckTypesMiniError);\n    assert.equal(error.context, \"buildConfig\");\n    assert.equal(error.path[0], \"enabled\");\n    return true;\n  },\n);"},"ignore-keys.js":{"title":"Ignore a key wherever it occurs","code":"import { strict as assert } from \"node:assert\";\n\nimport { checkTypesMini } from \"check-types-mini\";\n\nassert.doesNotThrow(() => {\n  checkTypesMini(\n    { first: { metadata: \"text\" }, second: { metadata: 123 } },\n    { first: { metadata: false }, second: { metadata: false } },\n    { ignoreKeys: \"metadata\" },\n  );\n});"},"ignore-paths.js":{"title":"Ignore only selected nested paths","code":"import { strict as assert } from \"node:assert\";\n\nimport { checkTypesMini } from \"check-types-mini\";\n\nassert.doesNotThrow(() => {\n  checkTypesMini(\n    { first: { value: \"custom\" }, second: { value: 123 } },\n    { first: { value: false }, second: { value: false } },\n    { ignorePaths: [\"first.*\", \"second.value\"] },\n  );\n});"},"literal-dotted-key.js":{"title":"Validate a property whose key contains a literal dot","code":"import { strict as assert } from \"node:assert\";\n\nimport { checkTypesMini } from \"check-types-mini\";\n\nassert.doesNotThrow(() => {\n  checkTypesMini({ \"cache.mode\": \"memory\" }, null, {\n    schema: { \"cache\\\\.mode\": \"string\" },\n  });\n});"},"nested-schema.js":{"title":"Use a nested schema object","code":"import { strict as assert } from \"node:assert\";\n\nimport { checkTypesMini } from \"check-types-mini\";\n\nassert.doesNotThrow(() => {\n  checkTypesMini({ build: { target: [\"es2022\", \"node18\"] } }, null, {\n    acceptArrays: true,\n    schema: { build: { target: \"string\" } },\n  });\n});"},"progress-and-completion.js":{"title":"Compose progress and inspect completion statistics","code":"import { strict as assert } from \"node:assert\";\n\nimport { checkTypesMini } from \"check-types-mini\";\n\nconst progress = [];\nlet completion;\ncheckTypesMini(\n  { enabled: true, output: \"dist\" },\n  { enabled: false, output: \"\" },\n  {\n    reportCompletionFunc(stats) {\n      completion = stats;\n    },\n    reportProgressFunc(percentageDone) {\n      progress.push(percentageDone);\n    },\n    reportProgressFuncFrom: 20,\n    reportProgressFuncTo: 40,\n  },\n);\n\nassert.deepEqual(progress, [20, 40]);\nassert.equal(completion.objectPropertiesVisited, 2);\nassert.equal(typeof completion.timeTakenInMilliseconds, \"number\");"},"relaxed-keyset.js":{"title":"Allow missing and additional keys","code":"import { strict as assert } from \"node:assert\";\n\nimport { checkTypesMini } from \"check-types-mini\";\n\nassert.doesNotThrow(() => {\n  checkTypesMini(\n    { known: true, additional: \"value\" },\n    { known: false, omitted: 0 },\n    { enforceStrictKeyset: false },\n  );\n});"},"schema-types.js":{"title":"Allow multiple types through a schema","code":"import { strict as assert } from \"node:assert\";\n\nimport { checkTypesMini } from \"check-types-mini\";\n\nassert.doesNotThrow(() => {\n  checkTypesMini({ cache: null, output: \"dist\" }, null, {\n    schema: {\n      cache: [\"boolean\", \"null\"],\n      output: \"string\",\n    },\n  });\n});"},"valid-options.js":{"title":"Validate an options object against defaults","code":"import { strict as assert } from \"node:assert\";\n\nimport { checkTypesMini } from \"check-types-mini\";\n\nassert.doesNotThrow(() => {\n  checkTypesMini(\n    { minify: true, output: \"dist\" },\n    { minify: false, output: \"build\" },\n  );\n});"}},"codsen-format-diagnostic-value":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { formatDiagnosticValue } from \"codsen-format-diagnostic-value\";\n\nassert.equal(\n  formatDiagnosticValue({ input: Symbol(\"marker\") }),\n  '{\"input\":Symbol(\"marker\")}',\n);"}},"codsen-glob":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { glob } from \"codsen-glob\";\n\nassert.deepEqual(await glob(\"src/**/*.ts\"), [\"src/main.ts\"]);"},"abort-signal.js":{"title":"Abort an asynchronous search","code":"import { strict as assert } from \"node:assert\";\n\nimport { glob } from \"codsen-glob\";\n\nconst controller = new AbortController();\ncontroller.abort();\n\nawait assert.rejects(\n  glob(\"**/*.ts\", { signal: controller.signal }),\n  (error) => error.name === \"AbortError\",\n);"},"absolute-paths.js":{"title":"Return absolute paths","code":"import { strict as assert } from \"node:assert\";\nimport path from \"node:path\";\n\nimport { glob } from \"codsen-glob\";\n\nassert.deepEqual(await glob(\"src/main.ts\", { absolute: true }), [\n  path.join(process.cwd(), \"src/main.ts\"),\n]);"},"brace-and-extglob-patterns.js":{"title":"Brace expansion and extglobs","code":"import { strict as assert } from \"node:assert\";\n\nimport { glob } from \"codsen-glob\";\n\nassert.deepEqual(await glob(\"{src,test}/@(main|test).@(ts|js)\"), [\n  \"src/main.ts\",\n  \"test/test.js\",\n]);"},"case-insensitive.js":{"title":"Match without case sensitivity","code":"import { strict as assert } from \"node:assert\";\n\nimport { glob } from \"codsen-glob\";\n\n// the file on disk is \"src/main.ts\", so an uppercase extension misses by default\nassert.deepEqual(await glob(\"src/*.TS\"), []);\n\n// mind you, only the matched part is case-insensitive - the static \"src/\"\n// prefix locates the search root, so the filesystem resolves it as-is\nassert.deepEqual(await glob(\"src/*.TS\", { caseSensitiveMatch: false }), [\n  \"src/main.ts\",\n]);"},"directory-expansion.js":{"title":"Configure directory expansion","code":"import { strict as assert } from \"node:assert\";\n\nimport { glob } from \"codsen-glob\";\n\nassert.deepEqual(\n  await glob(\"src\", {\n    expandDirectories: { files: [\"main.ts\"], extensions: [\"ts\"] },\n  }),\n  [\"src/main.ts\"],\n);"},"directory-results.js":{"title":"Return directories","code":"import { strict as assert } from \"node:assert\";\n\nimport { glob } from \"codsen-glob\";\n\nassert.deepEqual(await glob(\"s*\", { onlyDirectories: true }), [\"src\"]);\n\nassert.equal(\n  (await glob(\"src\", { expandDirectories: false, onlyFiles: false }))[0],\n  \"src\",\n);"},"do-not-follow-symbolic-links.js":{"title":"Disable symbolic-link traversal","code":"import { strict as assert } from \"node:assert\";\n\nimport { glob } from \"codsen-glob\";\n\nassert.deepEqual(await glob(\"src/**/*.ts\", { followSymbolicLinks: false }), [\n  \"src/main.ts\",\n]);"},"dot-files.js":{"title":"Include hidden entries","code":"import { strict as assert } from \"node:assert\";\n\nimport { glob } from \"codsen-glob\";\n\nconst withoutDot = await glob(\"*\", { onlyFiles: false });\nconst withDot = await glob(\"*\", { dot: true, onlyFiles: false });\n\nassert.equal(withoutDot.includes(\".all-contributorsrc\"), false);\nassert.equal(withDot.includes(\".all-contributorsrc\"), true);"},"ignore.js":{"title":"Veto matches with ignore patterns","code":"import { strict as assert } from \"node:assert\";\n\nimport { glob } from \"codsen-glob\";\n\nassert.deepEqual(await glob(\"src/*.ts\", { ignore: \"**/*.d.ts\" }), [\n  \"src/main.ts\",\n]);"},"multiple-patterns.js":{"title":"Combine multiple patterns","code":"import { strict as assert } from \"node:assert\";\n\nimport { glob } from \"codsen-glob\";\n\nassert.deepEqual(await glob([\"src/main.ts\", \"test/*.js\"]), [\n  \"src/main.ts\",\n  \"test/test.js\",\n]);"},"negative-pattern.js":{"title":"Exclude matches with a negative pattern","code":"import { strict as assert } from \"node:assert\";\n\nimport { glob } from \"codsen-glob\";\n\nassert.deepEqual(await glob([\"*.md\", \"!CHANGELOG.md\"]), [\"README.md\"]);"},"synchronous.js":{"title":"Synchronous globbing","code":"import { strict as assert } from \"node:assert\";\n\nimport { globSync } from \"codsen-glob\";\n\nassert.deepEqual(globSync(\"src/*.ts\"), [\"src/main.ts\"]);"},"url-working-directory.js":{"title":"Use a file URL as the working directory","code":"import { strict as assert } from \"node:assert\";\nimport { pathToFileURL } from \"node:url\";\n\nimport { glob } from \"codsen-glob\";\n\nassert.deepEqual(\n  await glob(\"src/*.ts\", { cwd: pathToFileURL(process.cwd()) }),\n  [\"src/main.ts\"],\n);"}},"codsen-utils":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { isNumberChar } from \"codsen-utils\";\n\nassert.equal(isNumberChar(\"0\"), true);"},"character-classifiers.js":{"title":"Classify individual characters","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  isCurrencyChar,\n  isCurrencySymbol,\n  isLatinLetter,\n  isLetter,\n  isLowercaseLetter,\n  isNumberChar,\n  isQuote,\n  isUppercaseLetter,\n  isWhitespaceChar,\n} from \"codsen-utils\";\n\nassert.equal(isNumberChar(\"7\"), true);\nassert.equal(isCurrencyChar(\"£\"), true);\nassert.equal(isCurrencyChar(\"CHF\"), false);\nassert.equal(isCurrencySymbol(\"CHF\"), true);\nassert.equal(isLetter(\"Ж\"), true);\nassert.equal(isLatinLetter(\"Ж\"), false);\nassert.equal(isQuote(\"”\"), true);\nassert.equal(isLowercaseLetter(\"ž\"), true);\nassert.equal(isUppercaseLetter(\"Ž\"), true);\nassert.equal(isWhitespaceChar(\"\\u00A0\"), true);"},"cli-flags.js":{"title":"Parse typed, short and repeatable CLI flags","code":"import { strict as assert } from \"node:assert\";\n\nimport { codsenCLI } from \"codsen-utils\";\n\nconst result = codsenCLI(\"\", {\n  argv: [\"input.js\", \"-v\", \"--count=2\", \"-i\", \"a\", \"-i\", \"b\"],\n  autoHelp: false,\n  autoVersion: false,\n  booleanDefault: false,\n  flags: {\n    verbose: { type: \"boolean\", shortFlag: \"v\" },\n    count: { type: \"number\", default: 1 },\n    ignore: { type: \"string\", shortFlag: \"i\", isMultiple: true },\n  },\n});\n\nassert.deepEqual(result.flags, {\n  verbose: true,\n  count: 2,\n  ignore: [\"a\", \"b\"],\n});\nassert.equal(result.input[0], \"input.js\");"},"cli-help.js":{"title":"Assemble CLI help text","code":"import { strict as assert } from \"node:assert\";\n\nimport { codsenCLI } from \"codsen-utils\";\n\nconst result = codsenCLI(\n  `\n    Usage\n      $ demo <file>\n  `,\n  {\n    argv: [],\n    autoHelp: false,\n    autoVersion: false,\n    description: \"Process a file\",\n    helpIndent: 4,\n    pkg: { name: \"demo-cli\", version: \"1.0.0\", bin: \"cli.js\" },\n    version: \"2.0.0\",\n  },\n);\n\nassert.equal(result.help.includes(\"    Process a file\"), true);\nassert.equal(result.help.includes(\"    Usage\"), true);\nassert.equal(result.pkg.name, \"demo-cli\");"},"deep-clone.js":{"title":"Deeply clone a cyclic object graph","code":"import { strict as assert } from \"node:assert\";\n\nimport { deepClone } from \"codsen-utils\";\n\nconst source = { nested: { value: 1 } };\nsource.self = source;\nsource.map = new Map([[source.nested, source]]);\n\nconst cloned = deepClone(source);\n\nassert.notEqual(cloned, source);\nassert.notEqual(cloned.nested, source.nested);\nassert.equal(cloned.self, cloned);\nassert.equal([...cloned.map.values()][0], cloned);"},"eol-detection.js":{"title":"Detect and resolve line endings","code":"import { strict as assert } from \"node:assert\";\n\nimport { detectEol, resolveEolSetting } from \"codsen-utils\";\n\nassert.equal(detectEol(\"first\\r\\nsecond\"), \"\\r\\n\");\nassert.equal(resolveEolSetting(\"first\\rsecond\", undefined), \"\\r\");\nassert.equal(resolveEolSetting(\"first\\rsecond\", \"lf\"), \"\\n\");\nassert.equal(resolveEolSetting(\"no breaks\", undefined, \"\\r\\n\"), \"\\r\\n\");"},"existy.js":{"title":"Test whether a value exists","code":"import { strict as assert } from \"node:assert\";\n\nimport { existy } from \"codsen-utils\";\n\nassert.equal(existy(null), false);\nassert.equal(existy(undefined), false);\nassert.equal(existy(false), true);\nassert.equal(existy(0), true);\nassert.equal(existy(\"\"), true);"},"find-all-indexes.js":{"title":"Find overlapping substring occurrences","code":"import { strict as assert } from \"node:assert\";\n\nimport { findAllIdx } from \"codsen-utils\";\n\nassert.deepEqual(findAllIdx(\"bananana\", \"ana\"), [1, 3, 5]);"},"includes-string-or-regexp.js":{"title":"Match a string against literal and regular-expression choices","code":"import { strict as assert } from \"node:assert\";\n\nimport { includes } from \"codsen-utils\";\n\nconst choices = [\"README.md\", /\\.test\\.js$/];\n\nassert.equal(includes(choices, \"README.md\"), true);\nassert.equal(includes(choices, \"main.test.js\"), true);\nassert.equal(includes(choices, \"main.js\"), false);"},"intersection.js":{"title":"Intersect arrays in the first array's order","code":"import { strict as assert } from \"node:assert\";\n\nimport { intersection } from \"codsen-utils\";\n\nassert.deepEqual(intersection([3, 1, 2, 1], [1, 3]), [3, 1]);"},"non-number-character.js":{"title":"Reject a character that is not a digit","code":"import { strict as assert } from \"node:assert\";\n\nimport { isNumberChar } from \"codsen-utils\";\n\nassert.equal(isNumberChar(\"z\"), false);"},"omit.js":{"title":"Omit keys and clone retained values","code":"import { strict as assert } from \"node:assert\";\n\nimport { omit } from \"codsen-utils\";\n\nconst source = { password: \"secret\", profile: { name: \"Ada\" } };\nconst result = omit(source, [\"password\"]);\n\nassert.deepEqual(result, { profile: { name: \"Ada\" } });\nassert.notEqual(result.profile, source.profile);"},"own-properties.js":{"title":"Check own properties safely","code":"import { strict as assert } from \"node:assert\";\n\nimport { hasOwnProp } from \"codsen-utils\";\n\nconst value = { own: true };\n\nassert.equal(hasOwnProp(value, \"own\"), true);\nassert.equal(hasOwnProp(value, \"toString\"), false);"},"plain-objects.js":{"title":"Distinguish plain objects from other object values","code":"import { strict as assert } from \"node:assert\";\n\nimport { isPlainObject } from \"codsen-utils\";\n\nassert.equal(isPlainObject({ key: \"value\" }), true);\nassert.equal(isPlainObject(Object.create(null)), true);\nassert.equal(isPlainObject([]), false);\nassert.equal(isPlainObject(new Date()), false);"},"pull-all.js":{"title":"Remove selected array values without mutating the input","code":"import { strict as assert } from \"node:assert\";\n\nimport { pullAll } from \"codsen-utils\";\n\nconst source = [1, 2, 3, 2];\n\nassert.deepEqual(pullAll(source, [2]), [1, 3]);\nassert.equal(source.length, 4);"},"remove-trailing-slash.js":{"title":"Remove one trailing slash","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeTrailingSlash } from \"codsen-utils\";\n\nassert.equal(\n  removeTrailingSlash(\"https://example.com/\"),\n  \"https://example.com\",\n);\nassert.equal(removeTrailingSlash(\"path//\"), \"path/\");\nassert.equal(removeTrailingSlash(42), 42);"},"sort-strings.js":{"title":"Sort strings with the shared comparator","code":"import { strict as assert } from \"node:assert\";\n\nimport { compareFn } from \"codsen-utils\";\n\nassert.deepEqual([\"pear\", \"apple\", \"orange\"].sort(compareFn), [\n  \"apple\",\n  \"orange\",\n  \"pear\",\n]);"},"string-splice.js":{"title":"Replace part of a string","code":"import { strict as assert } from \"node:assert\";\n\nimport { stringSplice } from \"codsen-utils\";\n\nassert.equal(stringSplice(\"abcdef\", 2, 2, \"XY\"), \"abXYef\");\n\n// Negative indexes count from the end.\nassert.equal(stringSplice(\"abcdef\", -2, 1, \"X\"), \"abcdXf\");"},"text-symbols-and-tags.js":{"title":"Reuse shared text symbols and HTML tag sets","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  ellipsis,\n  inlineTags,\n  multiplicationSign,\n  punctuationChars,\n  rightSingleQuote,\n  voidTags,\n} from \"codsen-utils\";\n\nassert.equal(`that${rightSingleQuote}s`, \"that’s\");\nassert.equal(`Wait${ellipsis}`, \"Wait…\");\nassert.equal(`3 ${multiplicationSign} 4`, \"3 × 4\");\nassert.equal(punctuationChars.includes(\"?\"), true);\nassert.equal(voidTags.includes(\"img\"), true);\nassert.equal(inlineTags.has(\"span\"), true);"},"trim-characters.js":{"title":"Trim selected characters from both string edges","code":"import { strict as assert } from \"node:assert\";\n\nimport { trimChars } from \"codsen-utils\";\n\nassert.equal(trimChars(\"//article/>\", \"/>\"), \"article\");"},"type-predicates.js":{"title":"Check common JavaScript value types","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  isBool,\n  isDate,\n  isInt,\n  isNull,\n  isNum,\n  isRegExp,\n  isStr,\n} from \"codsen-utils\";\n\nassert.equal(isStr(\"value\"), true);\nassert.equal(isNum(1.5), true);\nassert.equal(isNum(Number.NaN), false);\nassert.equal(isInt(3), true);\nassert.equal(isInt(-1), false);\nassert.equal(isBool(false), true);\nassert.equal(isDate(new Date()), true);\nassert.equal(isNull(null), true);\nassert.equal(isRegExp(/value/), true);"},"unique-values.js":{"title":"Deduplicate values while preserving order","code":"import { strict as assert } from \"node:assert\";\n\nimport { uniq } from \"codsen-utils\";\n\nassert.deepEqual(uniq([\"b\", \"a\", \"b\", \"c\", \"a\"]), [\"b\", \"a\", \"c\"]);"},"wildcard-match.js":{"title":"Match wildcard allow-lists and deny-lists","code":"import { strict as assert } from \"node:assert\";\n\nimport { match } from \"codsen-utils\";\n\nconst patterns = [\"src/*.js\", \"!src/*.test.js\"];\n\nassert.equal(match(\"src/main.js\", patterns), true);\nassert.equal(match(\"src/main.test.js\", patterns), false);\nassert.equal(match(\"SRC/MAIN.JS\", patterns), true);\nassert.equal(\n  match(\"SRC/MAIN.JS\", patterns, { caseSensitiveMatch: true }),\n  false,\n);"}},"color-shorthand-hex-to-six-digit":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { conv } from \"color-shorthand-hex-to-six-digit\";\n\n// converts shorthand hex color codes within strings (imagine that could be\n// email template source code):\nassert.equal(\n  conv(\"aaaa #f0c zzzz\\n\\t\\t\\t#fc0\"),\n  \"aaaa #ff00cc zzzz\\n\\t\\t\\t#ffcc00\",\n);"},"css-references.js":{"title":"Preserve CSS references and selectors","code":"import { strict as assert } from \"node:assert\";\n\nimport { conv } from \"color-shorthand-hex-to-six-digit\";\n\nassert.equal(\n  conv(\n    'a[href=\"icons.svg#abc\"] { color: #abc; background: url(/* icon */ \"sprite.svg#fff\") }',\n  ),\n  'a[href=\"icons.svg#abc\"] { color: #aabbcc; background: url(/* icon */ \"sprite.svg#fff\") }',\n);"},"nested-data.js":{"title":"Nested arrays and objects","code":"import { strict as assert } from \"node:assert\";\n\nimport { conv } from \"color-shorthand-hex-to-six-digit\";\n\nassert.deepEqual(conv([\"#abc\", { accent: \"#f0c\" }, 42]), [\n  \"#aabbcc\",\n  { accent: \"#ff00cc\" },\n  42,\n]);"},"passthrough-values.js":{"title":"Pass through unsupported input values","code":"import { strict as assert } from \"node:assert\";\n\nimport { conv } from \"color-shorthand-hex-to-six-digit\";\n\nassert.equal(conv(42), 42);\nassert.equal(conv(null), null);\nassert.equal(conv(true), true);"}},"csv-sort":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { sort } from \"csv-sort\";\n\n// Sorts double-entry bookkeeping CSV's - bank statements for example\n// see https://en.wikipedia.org/wiki/Double-entry_bookkeeping\n\nassert.deepEqual(\n  sort(`Acc Number,Description,Debit Amount,Credit Amount,Balance,\n123456,Client #1 payment,,1000,1940\n123456,Bought carpet,30,,950\n123456,Bought table,10,,940\n123456,Bought pens,10,,1000\n123456,Bought chairs,20,,980\n`),\n  {\n    res: [\n      [\"Acc Number\", \"Description\", \"Debit Amount\", \"Credit Amount\", \"Balance\"],\n      [\"123456\", \"Client #1 payment\", \"\", \"1000\", \"1940\"],\n      [\"123456\", \"Bought table\", \"10\", \"\", \"940\"],\n      [\"123456\", \"Bought carpet\", \"30\", \"\", \"950\"],\n      [\"123456\", \"Bought chairs\", \"20\", \"\", \"980\"],\n      [\"123456\", \"Bought pens\", \"10\", \"\", \"1000\"],\n    ],\n    msgContent: null,\n    msgType: null,\n  },\n);\n// you'll have to join elements and lines from the array yourself"},"check-numeric-cell.js":{"title":"Check whether a CSV cell is numeric","code":"import { strict as assert } from \"node:assert\";\n\nimport { isNumeric } from \"csv-sort\";\n\nassert.equal(isNumeric(\"99.00\"), true);\nassert.equal(isNumeric(\"99 EUR\"), false);"},"empty-input.js":{"title":"Handle an empty CSV string","code":"import { strict as assert } from \"node:assert\";\n\nimport { sort } from \"csv-sort\";\n\nassert.deepEqual(sort(\"\"), {\n  res: [[\"\"]],\n  msgContent: null,\n  msgType: null,\n});"},"find-cell-type.js":{"title":"Classify CSV cells before sorting","code":"import { strict as assert } from \"node:assert\";\n\nimport { findType } from \"csv-sort\";\n\nassert.equal(findType(\"£ 100.01\"), \"numeric\");\nassert.equal(findType(\"Invoice payment\"), \"text\");\nassert.equal(findType(\" \\t \"), \"empty\");"},"sort-without-header.js":{"title":"Sort a bank statement that has no header row","code":"import { strict as assert } from \"node:assert\";\n\nimport { sort } from \"csv-sort\";\n\nassert.deepEqual(\n  sort(`123456,Payment,,1000,1940\n123456,Carpet,30,,950\n123456,Table,10,,940\n123456,Pens,10,,1000\n123456,Chairs,20,,980`),\n  {\n    res: [\n      [\"123456\", \"Payment\", \"\", \"1000\", \"1940\"],\n      [\"123456\", \"Table\", \"10\", \"\", \"940\"],\n      [\"123456\", \"Carpet\", \"30\", \"\", \"950\"],\n      [\"123456\", \"Chairs\", \"20\", \"\", \"980\"],\n      [\"123456\", \"Pens\", \"10\", \"\", \"1000\"],\n    ],\n    msgContent: null,\n    msgType: null,\n  },\n);"}},"csv-split-easy":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { splitEasy } from \"csv-split-easy\";\n\nassert.deepEqual(\n  splitEasy(\n    'Product Name,Main Price,Discounted Price\\nTestarossa (Type F110),\"100,000\",\"90,000\"\\nF50,\"2,500,000\",\"1,800,000\"',\n  ),\n  [\n    [\"Product Name\", \"Main Price\", \"Discounted Price\"],\n    [\"Testarossa (Type F110)\", \"100000\", \"90000\"],\n    [\"F50\", \"2500000\", \"1800000\"],\n  ],\n);"},"do-not-pad-decimals.js":{"title":"Leave single decimal place numbers unpadded","code":"import { strict as assert } from \"node:assert\";\n\nimport { splitEasy } from \"csv-split-easy\";\n\nassert.deepEqual(\n  splitEasy(\"item,price\\nWidget,1.5\", {\n    padSingleDecimalPlaceNumbers: false,\n  }),\n  [\n    [\"item\", \"price\"],\n    [\"Widget\", \"1.5\"],\n  ],\n);"},"escaped-double-quotes.js":{"title":"Unescape doubled-up double quotes","code":"import { strict as assert } from \"node:assert\";\n\nimport { splitEasy } from \"csv-split-easy\";\n\nassert.deepEqual(splitEasy('name,note\\nAda,\"She said \"\"hello\"\"\"'), [\n  [\"name\", \"note\"],\n  [\"Ada\", 'She said \"hello\"'],\n]);"},"keep-thousand-separators.js":{"title":"Keep the thousand separators in numbers","code":"import { strict as assert } from \"node:assert\";\n\nimport { splitEasy } from \"csv-split-easy\";\n\nassert.deepEqual(\n  splitEasy('item,price\\nWidget,\"1,250\"', {\n    removeThousandSeparatorsFromNumbers: false,\n  }),\n  [\n    [\"item\", \"price\"],\n    [\"Widget\", \"1,250\"],\n  ],\n);"},"opts-delimiter.js":{"title":"`opts.delimiter`","code":"import { strict as assert } from \"node:assert\";\n\nimport { splitEasy } from \"csv-split-easy\";\n\nassert.deepEqual(splitEasy(\"name;amount\\nJane;1000\", { delimiter: \";\" }), [\n  [\"name\", \"amount\"],\n  [\"Jane\", \"1000\"],\n]);"},"skip-blank-rows.js":{"title":"Skip blank rows","code":"import { strict as assert } from \"node:assert\";\n\nimport { splitEasy } from \"csv-split-easy\";\n\nassert.deepEqual(splitEasy(\"name,amount\\n\\n   \\nAda,2\\n\\nGrace,3\"), [\n  [\"name\", \"amount\"],\n  [\"Ada\", \"2\"],\n  [\"Grace\", \"3\"],\n]);"},"uk-number-style.js":{"title":"Convert continental number style into UK style","code":"import { strict as assert } from \"node:assert\";\n\nimport { splitEasy } from \"csv-split-easy\";\n\nassert.deepEqual(\n  splitEasy('item;price\\nWidget;\"1.234,5\"', {\n    delimiter: \";\",\n    forceUKStyle: true,\n  }),\n  [\n    [\"item\", \"price\"],\n    [\"Widget\", \"1234.50\"],\n  ],\n);"}},"detect-is-it-html-or-xhtml":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { detectIsItHTMLOrXhtml } from \"detect-is-it-html-or-xhtml\";\n\nassert.equal(\n  detectIsItHTMLOrXhtml(\n    '<img src=\"some.jpg\" width=\"zzz\" height=\"zzz\" border=\"0\" style=\"display:block;\" alt=\"zzz\"/>',\n  ),\n  \"xhtml\",\n);"},"html-doctype.js":{"title":"Detect HTML from its doctype","code":"import { strict as assert } from \"node:assert\";\n\nimport { detectIsItHTMLOrXhtml } from \"detect-is-it-html-or-xhtml\";\n\nassert.equal(detectIsItHTMLOrXhtml(\"<!doctype html><html></html>\"), \"html\");"},"html-on-tied-tag-styles.js":{"title":"Prefer HTML when self-closing and open single tags are tied","code":"import { strict as assert } from \"node:assert\";\n\nimport { detectIsItHTMLOrXhtml } from \"detect-is-it-html-or-xhtml\";\n\nassert.equal(detectIsItHTMLOrXhtml(\"<br/><hr>\"), \"html\");"},"undecided.js":{"title":"Return null when the source contains no decisive markup","code":"import { strict as assert } from \"node:assert\";\n\nimport { detectIsItHTMLOrXhtml } from \"detect-is-it-html-or-xhtml\";\n\nassert.equal(detectIsItHTMLOrXhtml(\"A plain text message\"), null);"},"xhtml-by-self-closing-tags.js":{"title":"Infer XHTML when most single tags are self-closing","code":"import { strict as assert } from \"node:assert\";\n\nimport { detectIsItHTMLOrXhtml } from \"detect-is-it-html-or-xhtml\";\n\nassert.equal(detectIsItHTMLOrXhtml(\"<br/><hr /><img src=x>\"), \"xhtml\");"},"xhtml-doctype.js":{"title":"Detect XHTML from its doctype","code":"import { strict as assert } from \"node:assert\";\n\nimport { detectIsItHTMLOrXhtml } from \"detect-is-it-html-or-xhtml\";\n\nassert.equal(\n  detectIsItHTMLOrXhtml(\n    '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Strict//EN\">',\n  ),\n  \"xhtml\",\n);"}},"detect-templating-language":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { detectLang } from \"detect-templating-language\";\n\n// detects Nunjucks\nassert.deepEqual(\n  detectLang(\"<div>{% if something %}x{% else %}y{% endif %}</div>\"),\n  { name: \"Nunjucks\" },\n);"},"jinja-inline-condition.js":{"title":"Detect a Jinja inline conditional expression","code":"import { strict as assert } from \"node:assert\";\n\nimport { detectLang } from \"detect-templating-language\";\n\nassert.deepEqual(detectLang(\"{{'open' if enabled else 'closed'}}\"), {\n  name: \"Jinja\",\n});"},"jinja-namespace.js":{"title":"Detect Jinja namespace syntax","code":"import { strict as assert } from \"node:assert\";\n\nimport { detectLang } from \"detect-templating-language\";\n\nassert.deepEqual(detectLang(\"{% set ns = namespace(total=0) %}\"), {\n  name: \"Jinja\",\n});"},"jsp-standard-tag-library.js":{"title":"Detect Java Server Pages using a JSP Standard Tag Library element","code":"/** biome-ignore-all lint/suspicious/noTemplateCurlyInString: fixture contains literal JSP expression syntax */\n\nimport { strict as assert } from \"node:assert\";\n\nimport { detectLang } from \"detect-templating-language\";\n\nassert.deepEqual(\n  detectLang('<div><c:set var=\"someList\" value=\"${jspProp.someList}\" /></div>'),\n  { name: \"JSP\" },\n);"},"no-template-language.js":{"title":"Report when no supported template language is present","code":"import { strict as assert } from \"node:assert\";\n\nimport { detectLang } from \"detect-templating-language\";\n\nassert.deepEqual(detectLang(\"<p>Static HTML</p>\"), { name: null });"}},"detergent":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { det, opts, version } from \"detergent\";\n\n// on default setting, widow removal and encoding are enabled:\nassert.equal(det(\"clean this text £\").res, \"clean this text&nbsp;&pound;\");"},"add-line-break-after-tag.js":{"title":"Insert a line break where a selected HTML tag is stripped","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"one<br>two\", {\n    stripHtml: true,\n    stripHtmlButIgnoreTags: [],\n    stripHtmlAddNewLine: [\"br\"],\n    replaceLineBreaks: false,\n    removeWidows: false,\n  }).res,\n  \"one\\ntwo\",\n);"},"add-missing-spaces.js":{"title":"Add missing spaces after sentence punctuation","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"Hello.World\", { addMissingSpaces: true, removeWidows: false }).res,\n  \"Hello. World\",\n);\nassert.equal(\n  det(\"Hello.World\", { addMissingSpaces: false, removeWidows: false }).res,\n  \"Hello.World\",\n);"},"applicable-options.js":{"title":"Discover which cleanup rules apply to an input","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nconst { applicableOpts } = det(\"Cost £5\");\n\nassert.equal(applicableOpts.convertEntities, true);\nassert.equal(applicableOpts.stripHtml, false);\nassert.equal(applicableOpts.convertDashes, false);"},"callback.js":{"title":"Transform text outside HTML tags with a callback","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"before <b>inside</b> after\", {\n    cb: (text) => text.toUpperCase(),\n    removeWidows: false,\n  }).res,\n  \"BEFORE <b>INSIDE</b> AFTER\",\n);"},"convert-apostrophes.js":{"title":"Normalise typographic apostrophes","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"It’s fine\", {\n    convertApostrophes: true,\n    convertEntities: true,\n    removeWidows: false,\n  }).res,\n  \"It&rsquo;s fine\",\n);\nassert.equal(\n  det(\"It’s fine\", {\n    convertApostrophes: false,\n    convertEntities: true,\n    removeWidows: false,\n  }).res,\n  \"It's fine\",\n);"},"convert-dashes.js":{"title":"Normalise a dash according to the conversion setting","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"one — two\", { convertDashes: true, removeWidows: false }).res,\n  \"one &mdash; two\",\n);\nassert.equal(\n  det(\"one — two\", { convertDashes: false, removeWidows: false }).res,\n  \"one - two\",\n);"},"convert-ellipsis.js":{"title":"Convert three dots to an ellipsis entity","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"Wait... now\", {\n    convertDotsToEllipsis: true,\n    removeWidows: false,\n  }).res,\n  \"Wait&hellip; now\",\n);\nassert.equal(\n  det(\"Wait... now\", {\n    convertDotsToEllipsis: false,\n    removeWidows: false,\n  }).res,\n  \"Wait... now\",\n);"},"convert-entities.js":{"title":"Choose whether to encode HTML entities","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"Cost £5\", { convertEntities: true, removeWidows: false }).res,\n  \"Cost &pound;5\",\n);\nassert.equal(\n  det(\"Cost £5\", { convertEntities: false, removeWidows: false }).res,\n  \"Cost £5\",\n);"},"default-options.js":{"title":"Inspect the exported default options","code":"import { strict as assert } from \"node:assert\";\n\nimport { opts } from \"detergent\";\n\nassert.equal(opts.stripHtml, true);\nassert.equal(opts.convertEntities, true);\nassert.equal(opts.removeWidows, true);\nassert.equal(opts.eol, \"lf\");"},"end-of-line-style.js":{"title":"Set the end-of-line sequence inserted after HTML break tags","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nconst common = { replaceLineBreaks: true, removeWidows: false };\n\nassert.equal(det(\"one\\ntwo\", { ...common, eol: \"lf\" }).res, \"one<br/>\\ntwo\");\nassert.equal(\n  det(\"one\\ntwo\", { ...common, eol: \"crlf\" }).res,\n  \"one<br/>\\r\\ntwo\",\n);\nassert.equal(det(\"one\\ntwo\", { ...common, eol: \"cr\" }).res, \"one<br/>\\rtwo\");"},"fix-broken-entities.js":{"title":"Fix misspelled named HTML entities","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"one &nsp; two\", {\n    fixBrokenEntities: true,\n    removeWidows: false,\n  }).res,\n  \"one &nbsp; two\",\n);\nassert.equal(\n  det(\"one &nsp; two\", {\n    fixBrokenEntities: false,\n    removeWidows: false,\n  }).res,\n  \"one &amp;nsp; two\",\n);"},"html-or-xhtml.js":{"title":"Choose HTML or XHTML break-tag syntax","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"one\\ntwo\", {\n    replaceLineBreaks: true,\n    useXHTML: true,\n    removeWidows: false,\n  }).res,\n  \"one<br/>\\ntwo\",\n);\nassert.equal(\n  det(\"one\\ntwo\", {\n    replaceLineBreaks: true,\n    useXHTML: false,\n    removeWidows: false,\n  }).res,\n  \"one<br>\\ntwo\",\n);"},"keep-selected-html-tags.js":{"title":"Keep selected tags while stripping the rest","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"Before <div><mark>inside</mark></div> after\", {\n    stripHtml: true,\n    stripHtmlButIgnoreTags: [\"mark\"],\n    removeWidows: false,\n  }).res,\n  \"Before <mark>inside</mark> after\",\n);"},"non-latin-characters.js":{"title":"Preserve or encode non-Latin characters","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(det(\"Привет\", { dontEncodeNonLatin: true }).res, \"Привет\");\nassert.equal(\n  det(\"Привет\", { dontEncodeNonLatin: false }).res,\n  \"&#x41F;&#x440;&#x438;&#x432;&#x435;&#x442;\",\n);"},"remove-line-breaks.js":{"title":"Collapse line breaks to spaces","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"one\\ntwo\", {\n    removeLineBreaks: true,\n    replaceLineBreaks: false,\n    removeWidows: false,\n  }).res,\n  \"one two\",\n);"},"remove-widows.js":{"title":"Keep the last two words together","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"clean this text now\", { removeWidows: true }).res,\n  \"clean this text&nbsp;now\",\n);\nassert.equal(\n  det(\"clean this text now\", { removeWidows: false }).res,\n  \"clean this text now\",\n);"},"replace-line-breaks.js":{"title":"Replace line breaks with HTML break tags","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nassert.equal(\n  det(\"one\\ntwo\", { replaceLineBreaks: true, removeWidows: false }).res,\n  \"one<br/>\\ntwo\",\n);\nassert.equal(\n  det(\"one\\ntwo\", { replaceLineBreaks: false, removeWidows: false }).res,\n  \"one\\ntwo\",\n);"},"strip-html.js":{"title":"Choose whether to strip HTML tags","code":"import { strict as assert } from \"node:assert\";\n\nimport { det } from \"detergent\";\n\nconst source = \"Before <p>inside</p> after\";\n\nassert.equal(\n  det(source, { stripHtml: true, removeWidows: false }).res,\n  \"Before inside after\",\n);\nassert.equal(\n  det(source, { stripHtml: false, removeWidows: false }).res,\n  source,\n);"}},"edit-package-json":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { set } from \"edit-package-json\";\n\n// edit JSON as string\nassert.equal(\n  set(\n    `{\n  \"name\": \"test\",\n  \"dependencies\": {\n    \"ranges-apply\": \"^2.0.0\",\n    \"string-left-right\": \"^2.3.30\"\n  },\n  \"devDependencies\": {}\n}`,\n    \"dependencies.ranges-apply\", // path to amend\n    \"^3.2.2\", // new value\n  ),\n  `{\n  \"name\": \"test\",\n  \"dependencies\": {\n    \"ranges-apply\": \"^3.2.2\",\n    \"string-left-right\": \"^2.3.30\"\n  },\n  \"devDependencies\": {}\n}`,\n);"},"add-new-key.js":{"title":"Add a key that is not there yet, at the indentation the file already uses","code":"import { strict as assert } from \"node:assert\";\n\nimport { set } from \"edit-package-json\";\n\nconst pkg = `{\n  \"name\": \"demo\",\n  \"scripts\": {\n    \"build\": \"tsc\"\n  }\n}`;\n\n// a new key in a nested object goes in after the last one, separated the same\n// way the members already there are\nassert.equal(\n  set(pkg, \"scripts.test\", \"uvu\"),\n  `{\n  \"name\": \"demo\",\n  \"scripts\": {\n    \"build\": \"tsc\",\n    \"test\": \"uvu\"\n  }\n}`,\n);\n\n// a path whose middle is missing gets it built, indented to match\nassert.equal(\n  set(pkg, \"dependencies.uvu\", \"^0.5.0\"),\n  `{\n  \"name\": \"demo\",\n  \"scripts\": {\n    \"build\": \"tsc\"\n  },\n  \"dependencies\": {\n    \"uvu\": \"^0.5.0\"\n  }\n}`,\n);\n\n// an all-digits segment asks for an array rather than an object\nassert.equal(\n  set(pkg, \"files.0\", \"dist\"),\n  `{\n  \"name\": \"demo\",\n  \"scripts\": {\n    \"build\": \"tsc\"\n  },\n  \"files\": [\n    \"dist\"\n  ]\n}`,\n);\n\n// minified input stays minified - the formatting is read off the input, never\n// imposed on it\nassert.equal(set('{\"a\":\"b\"}', \"c.d\", \"e\"), '{\"a\":\"b\",\"c\":{\"d\":\"e\"}}');"},"delete-array-item.js":{"title":"Delete an array item by its dot-path index","code":"import { strict as assert } from \"node:assert\";\n\nimport { del } from \"edit-package-json\";\n\nassert.equal(\n  del('{\"files\":[\"dist\",\"types\",\"src\"]}', \"files.1\"),\n  '{\"files\":[\"dist\",\"src\"]}',\n);"},"delete-nested-key.js":{"title":"Delete a nested object key","code":"import { strict as assert } from \"node:assert\";\n\nimport { del } from \"edit-package-json\";\n\nassert.equal(\n  del('{\"scripts\":{\"test\":\"uvu\",\"lint\":\"biome check .\"}}', \"scripts.lint\"),\n  '{\"scripts\":{\"test\":\"uvu\"}}',\n);"},"mini-del.js":{"title":"Minimal example, `del()`","code":"import { strict as assert } from \"node:assert\";\n\nimport { del } from \"edit-package-json\";\n\n// edit JSON as string\nassert.equal(\n  del(\n    `{\n  \"a\": \"b\",\n  \"c\": \"d\"\n}`,\n    \"c\", // path to delete\n  ),\n  `{\n  \"a\": \"b\"\n}`,\n);"},"mini-set.js":{"title":"Minimal example, `set()`","code":"import { strict as assert } from \"node:assert\";\n\nimport { set } from \"edit-package-json\";\n\n// edit JSON as string\nassert.equal(\n  set(\n    `{\n  \"a\": \"b\",\n  \"c\": {\n    \"d\": \"e\"\n  }\n}`,\n    \"c.d\", // path\n    \"x\", // value to put\n  ),\n  `{\n  \"a\": \"b\",\n  \"c\": {\n    \"d\": \"x\"\n  }\n}`,\n);"},"set-array-item.js":{"title":"Replace an existing array item by its dot-path index","code":"import { strict as assert } from \"node:assert\";\n\nimport { set } from \"edit-package-json\";\n\nassert.equal(\n  set('{\"files\":[\"dist\",\"src\"]}', \"files.1\", \"types\"),\n  '{\"files\":[\"dist\",\"types\"]}',\n);"},"set-null.js":{"title":"Replace an existing nested value with null","code":"import { strict as assert } from \"node:assert\";\n\nimport { set } from \"edit-package-json\";\n\nassert.equal(\n  set('{\"release\":{\"channel\":\"next\"}}', \"release.channel\", null),\n  '{\"release\":{\"channel\":null}}',\n);"},"set-number.js":{"title":"Set a numeric value without changing surrounding formatting","code":"import { strict as assert } from \"node:assert\";\n\nimport { set } from \"edit-package-json\";\n\nassert.equal(\n  set('{\\n  \"name\": \"demo\",\\n  \"retries\": 1\\n}', \"retries\", 3),\n  '{\\n  \"name\": \"demo\",\\n  \"retries\": 3\\n}',\n);"},"set-object.js":{"title":"Replace an object value while preserving outer formatting","code":"import { strict as assert } from \"node:assert\";\n\nimport { set } from \"edit-package-json\";\n\nassert.equal(\n  set('{\\n  \"name\": \"demo\",\\n  \"publishConfig\": {}\\n}', \"publishConfig\", {\n    access: \"public\",\n  }),\n  '{\\n  \"name\": \"demo\",\\n  \"publishConfig\": {\"access\":\"public\"}\\n}',\n);"}},"email-all-chars-within-ascii":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { within } from \"email-all-chars-within-ascii\";\n\n// enforces all characters to be within ASCII:\nassert.deepEqual(within(\"<div>Motörhead</div>\"), [\n  {\n    type: \"character\",\n    line: 1,\n    column: 9,\n    positionIdx: 8,\n    value: \"ö\",\n    codePoint: 246,\n    UTF32Hex: \"00f6\",\n  },\n]);"},"allowed-email-control-characters.js":{"title":"Tabs and line breaks are allowed","code":"import { strict as assert } from \"node:assert\";\n\nimport { within } from \"email-all-chars-within-ascii\";\n\nassert.deepEqual(within(\"name\\tvalue\\r\\nnext line\"), []);"},"custom-line-length.js":{"title":"Set a custom maximum line length","code":"import { strict as assert } from \"node:assert\";\n\nimport { within } from \"email-all-chars-within-ascii\";\n\nassert.deepEqual(within(\"abcde\", { lineLength: 3 }), [\n  {\n    type: \"line length\",\n    line: 1,\n    column: 5,\n    positionIdx: 5,\n    value: 5,\n  },\n]);"},"disable-line-length-check.js":{"title":"Disable the line length check","code":"import { strict as assert } from \"node:assert\";\n\nimport { within } from \"email-all-chars-within-ascii\";\n\nassert.deepEqual(within(\"a\".repeat(1_000), { lineLength: 0 }), []);"},"report-multiple-non-ascii-characters.js":{"title":"Report every non-ASCII character found","code":"import { strict as assert } from \"node:assert\";\n\nimport { within } from \"email-all-chars-within-ascii\";\n\nconst findings = within(\"H\\u00e9llo\\nM\\u00fcnchen\");\n\nassert.equal(findings.length, 2);\nassert.equal(findings[0].value, \"\\u00e9\");\nassert.equal(findings[0].line, 1);\nassert.equal(findings[1].value, \"\\u00fc\");\nassert.equal(findings[1].line, 2);"}},"email-comb":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\nimport { comb, defaults, version } from \"email-comb\";\n\nconst source = `<head>\n<style type=\"text/css\">\n.unused1[z] {a:1;}\n.used[z] {a:2;}\n</style>\n</head>\n<body class=\"  used  \"><a class=\"used unused3\">z</a>\n</body>\n`;\n\nconst intended = `<head>\n<style type=\"text/css\">\n.used[z] {a:2;}\n</style>\n</head>\n<body class=\"used\"><a class=\"used\">z</a>\n</body>\n`;\n\nassert.equal(comb(source).result, intended);"},"backend-template-markers.js":{"title":"Keep classes inside backend template markers","code":"import { strict as assert } from \"node:assert\";\n\nimport { comb } from \"email-comb\";\n\nconst source = `<body class=\"{{ dynamic_class }} unused\"></body>`;\nconst result = comb(source, {\n  backend: [{ heads: \"{{\", tails: \"}}\" }],\n}).result;\n\nassert.equal(result.includes(\"{{ dynamic_class }}\"), true);\nassert.equal(result.includes(\"unused\"), false);"},"custom-comment-exclusion.js":{"title":"Keep HTML comments containing a given string","code":"import { strict as assert } from \"node:assert\";\n\nimport { comb } from \"email-comb\";\n\nconst source = \"<body><!-- keep: legal notice --><!-- remove me --></body>\";\nconst result = comb(source, {\n  doNotRemoveHTMLCommentsWhoseOpeningTagContains: \"keep:\",\n}).result;\n\nassert.equal(result.includes(\"keep: legal notice\"), true);\nassert.equal(result.includes(\"remove me\"), false);"},"keep-css-comments.js":{"title":"Keep CSS comments","code":"import { strict as assert } from \"node:assert\";\n\nimport { comb } from \"email-comb\";\n\nconst source = `<style>.used{/* reason */color:red}</style>\n<body class=\"used\"></body>`;\nconst result = comb(source, { removeCSSComments: false }).result;\n\nassert.equal(result.includes(\"/* reason */\"), true);"},"keep-html-comments.js":{"title":"Keep HTML comments","code":"import { strict as assert } from \"node:assert\";\n\nimport { comb } from \"email-comb\";\n\nconst source = \"<body><!-- editorial note --><p>Hello</p></body>\";\n\nassert.equal(comb(source, { removeHTMLComments: false }).result, source);"},"keep-ids-used-by-for-attributes.js":{"title":"Keep id's referenced by `for` attributes","code":"import { strict as assert } from \"node:assert\";\n\nimport { comb } from \"email-comb\";\n\nconst source = `<body><label for=\"email-field\">Email</label>\n<input id=\"email-field\"><input id=\"unused-field\"></body>`;\nconst result = comb(source).result;\n\nassert.equal(result.includes('id=\"email-field\"'), true);\nassert.equal(result.includes(\"unused-field\"), false);"},"minify-uglify.js":{"title":"Minifies and uglifies","code":"import { strict as assert } from \"node:assert\";\nimport { comb } from \"email-comb\";\n\nconst someHtml = `<html>\n<body id=\"used-1\">\n  <table class=\"unused-2 unused-3\">\n    <tr>\n      <td class=\"unused-4 unused-5\">text</td>\n    </tr>\n  </table>\n\n  <style>\n    #used-1 {\n      color: #ccc;\n    }\n    .unused-6 {\n      display: block;\n    }\n    #unused-7 {\n      height: auto;\n    }\n  </style>\n</body>\n</html>`;\n\nassert.equal(\n  comb(someHtml, {\n    uglify: true,\n    htmlCrushOpts: {\n      removeLineBreaks: true,\n    },\n  }).result,\n  `<html>\n<body id=\"q\">\n<table><tr><td>text\n</td></tr></table>\n<style>#q{color:#ccc;}\n</style>\n</body>\n</html>`,\n);"},"progress-range.js":{"title":"Report progress within a custom range","code":"import { strict as assert } from \"node:assert\";\n\nimport { comb } from \"email-comb\";\n\nconst reported = [];\nconst source = `<style>.used{color:red}</style><body class=\"used\">${\"text \".repeat(\n  300,\n)}</body>`;\n\ncomb(source, {\n  reportProgressFunc: (percentage) => reported.push(percentage),\n  reportProgressFuncFrom: 20,\n  reportProgressFuncTo: 40,\n});\n\nassert.equal(reported.length > 0, true);\nassert.equal(\n  reported.every((value) => value >= 20 && value <= 40),\n  true,\n);"},"remove-empty-media-query.js":{"title":"Remove media queries left empty","code":"import { strict as assert } from \"node:assert\";\n\nimport { comb } from \"email-comb\";\n\nconst source = `<style>@media screen {.unused{display:none}}</style>\n<body></body>`;\n\nassert.equal(comb(source).result.includes(\"@media\"), false);"},"reports-extracted.js":{"title":"Returns all extracted and deleted classes and id's","code":"import { strict as assert } from \"node:assert\";\nimport { comb } from \"email-comb\";\n\nconst { allInHead, allInBody, deletedFromHead, deletedFromBody } = comb(\n  `<!DOCTYPE html>\n<html>\n<head>\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\">\n<title>Tile</title>\n<style type=\"text/css\">\ndiv.non-existent-class{display: block;}\ntable#other div#non-existent-id{width:100%; display: inline-block;}\n</style>\n</head>\n<body>\n<table>\n<td>\n  <img class=\"unused1 unused2\" src=\"image.jpg\" width=\"zzz\" height=\"zzz\" border=\"0\" style=\"display:block;\" alt=\"zzz\">\n  <br><br>\n  <hr class=\"unused3\">\n  <br><br id=\"unused4\">\n</td>\n</tr>\n</table>\n</body>\n</html>\n`,\n);\n\nassert.deepEqual(\n  { allInHead, allInBody, deletedFromHead, deletedFromBody },\n  {\n    allInHead: [\".non-existent-class\", \"#non-existent-id\", \"#other\"],\n    allInBody: [\".unused1\", \".unused2\", \".unused3\", \"#unused4\"],\n    deletedFromHead: [\".non-existent-class\", \"#non-existent-id\", \"#other\"],\n    deletedFromBody: [\".unused1\", \".unused2\", \".unused3\", \"#unused4\"],\n  },\n);"},"style-within-body.js":{"title":"Works even if `<style>` is within `<body>` and there's no `<head>`","code":"import { strict as assert } from \"node:assert\";\nimport { comb } from \"email-comb\";\n\nconst someHtml = `<html>\n<body id=\"unused-1\">\n  <table class=\"unused-2 unused-3\">\n    <tr>\n      <td class=\"unused-4 unused-5\">text</td>\n    </tr>\n  </table>\n\n  <style>\n    .unused-6 {\n      display: block;\n    }\n    #unused-7 {\n      height: auto;\n    }\n  </style>\n</body>\n</html>`;\n\nassert.equal(\n  comb(someHtml).result,\n  `<html>\n<body>\n  <table>\n    <tr>\n      <td>text</td>\n    </tr>\n  </table>\n</body>\n</html>`,\n);"},"whitelist-one-selector.js":{"title":"Whitelist a selector from removal","code":"import { strict as assert } from \"node:assert\";\n\nimport { comb } from \"email-comb\";\n\nconst source = `<style>.dynamic{color:red}.unused{color:blue}</style>\n<body></body>`;\nconst result = comb(source, { whitelist: \".dynamic\" }).result;\n\nassert.equal(result.includes(\".dynamic{color:red}\"), true);\nassert.equal(result.includes(\".unused\"), false);"},"whitelist-wildcards.js":{"title":"Whitelist using wildcards","code":"import { strict as assert } from \"node:assert\";\nimport { comb } from \"email-comb\";\n\nconst someHtml = `<html>\n<head>\n<style type=\"text/css\">\n  .module-1{display: none !important;}\n  .module-2{display: none !important;}\n  .module-3{display: none !important;}\n  .module-zzzzkldfjglfjhlfjlhfglj{display: none !important;}\n  .head-only-class-1 a.module-94:hover{width: 100% !important;}\n  #head-only-id-1[lang|en]{width: 100% !important;}\n</style>\n</head>\n<body>\n<table class=\"module-92\" width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\n<tr class=\"module-93 body-only-class-1\">\n  <td id=\"body-only-id-1\" class=\"module-94 module-lkfjgldhglktjja\">\n    <img class=\"module-91\" src=\"image.jpg\" />\n  </td>\n</tr>\n</table>\n</body>\n</html>\n`;\n\nlet intended = `<html>\n<head>\n<style type=\"text/css\">\n  .module-1{display: none !important;}\n  .module-2{display: none !important;}\n  .module-3{display: none !important;}\n  .module-zzzzkldfjglfjhlfjlhfglj{display: none !important;}\n</style>\n</head>\n<body>\n<table class=\"module-92\" width=\"100%\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\n<tr class=\"module-93\">\n  <td class=\"module-94 module-lkfjgldhglktjja\">\n    <img class=\"module-91\" src=\"image.jpg\" />\n  </td>\n</tr>\n</table>\n</body>\n</html>\n`;\n\nassert.equal(\n  comb(someHtml, {\n    whitelist: [\".module-*\", \".particular\"],\n  }).result,\n  intended,\n);"}},"extract-search-index":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"extract-search-index\";\n\nassert.equal(\n  extract(\"The quick brown fox jumps over the lazy dog.\"),\n  \"quick brown fox jumps over lazy dog\",\n);"},"deduplicate-words.js":{"title":"Keep the first occurrence of each case-insensitive word","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"extract-search-index\";\n\nassert.equal(extract(\"Alpha alpha ALPHA beta\"), \"alpha beta\");"},"html-input.js":{"title":"Strip HTML tags and decode entities","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"extract-search-index\";\n\nassert.equal(extract(\"<tralala><div>some&nbsp;text</div>\"), \"some text\");"},"normalise-punctuation.js":{"title":"Normalise fancy punctuation and omit digits and emoji","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"extract-search-index\";\n\nassert.equal(extract(\"Fancy “quotes” — and café 123 😊\"), \"fancy quotes café\");"},"remove-code-and-styles.js":{"title":"Exclude code, preformatted text, and CSS from the index","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"extract-search-index\";\n\nassert.equal(\n  extract(\n    \"Before <code>const secret = true</code> after <style>.hidden{}</style>\",\n  ),\n  \"before after\",\n);"},"remove-urls.js":{"title":"Remove URLs and stop words from search-index text","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"extract-search-index\";\n\nassert.equal(\n  extract(\"Read docs at https://example.com/guide and save the docs\"),\n  \"read docs save\",\n);"}},"generate-atomic-css":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  extractFromToSource,\n  genAtomic,\n  headsAndTails,\n  version,\n} from \"generate-atomic-css\";\n\nassert.deepEqual(\n  genAtomic(\n    `a\n\n/* GENERATE-ATOMIC-CSS-CONFIG-STARTS\n.pb$$$ { padding-bottom: $$$px !important; } | 5 | 10\n\n.mt$$$ { margin-top: $$$px !important; } | 1\nGENERATE-ATOMIC-CSS-CONFIG-ENDS\nGENERATE-ATOMIC-CSS-CONTENT-STARTS */\n\ntralala\n\n/* GENERATE-ATOMIC-CSS-CONTENT-ENDS */\n\nz`,\n    {\n      includeConfig: false,\n      includeHeadsAndTails: false,\n    },\n  ),\n  {\n    log: { count: 8 },\n    result: `a\n\n.pb5  { padding-bottom:  5px !important; }\n.pb6  { padding-bottom:  6px !important; }\n.pb7  { padding-bottom:  7px !important; }\n.pb8  { padding-bottom:  8px !important; }\n.pb9  { padding-bottom:  9px !important; }\n.pb10 { padding-bottom: 10px !important; }\n\n.mt0 { margin-top:   0 !important; }\n.mt1 { margin-top: 1px !important; }\n\nz\n`,\n  },\n);"},"config-override.js":{"title":"Generate from a separate configuration string","code":"import { strict as assert } from \"node:assert\";\n\nimport { genAtomic } from \"generate-atomic-css\";\n\nassert.equal(\n  genAtomic(\"body { color: red; }\", {\n    includeConfig: false,\n    includeHeadsAndTails: false,\n    pad: false,\n    configOverride: \".m$$$ { margin: $$$px; } | 1 | 2\",\n  }).result,\n  \".m1 { margin: 1px; }\\n.m2 { margin: 2px; }\\n\",\n);"},"content-heads-and-tails.js":{"title":"Wrap generated content in marker comments","code":"import { strict as assert } from \"node:assert\";\n\nimport { genAtomic } from \"generate-atomic-css\";\n\nassert.equal(\n  genAtomic(\".m$$$ { margin: $$$px; } | 1 | 2\", {\n    includeConfig: false,\n    includeHeadsAndTails: true,\n    pad: false,\n  }).result,\n  `/* GENERATE-ATOMIC-CSS-CONTENT-STARTS */\n.m1 { margin: 1px; }\n.m2 { margin: 2px; }\n/* GENERATE-ATOMIC-CSS-CONTENT-ENDS */\n`,\n);"},"extract-range.js":{"title":"Extract a configured generation range","code":"import { strict as assert } from \"node:assert\";\n\nimport { extractFromToSource } from \"generate-atomic-css\";\n\nassert.deepEqual(\n  extractFromToSource(\".m$$$[lang|=en] { margin: $$$px; } | 2 | 4\"),\n  [2, 4, \".m$$$[lang|=en] { margin: $$$px; }\"],\n);"},"include-config.js":{"title":"Retain the generator configuration","code":"import { strict as assert } from \"node:assert\";\n\nimport { genAtomic } from \"generate-atomic-css\";\n\nconst result = genAtomic(\".m$$$ { margin: $$$px; } | 1 | 2\", {\n  includeConfig: true,\n  includeHeadsAndTails: true,\n  pad: false,\n}).result;\n\nassert.equal(result.includes(\"GENERATE-ATOMIC-CSS-CONFIG-STARTS\"), true);\nassert.equal(result.includes(\".m$$$ { margin: $$$px; } | 1 | 2\"), true);\nassert.equal(result.includes(\".m2 { margin: 2px; }\"), true);"},"marker-names.js":{"title":"Access canonical marker names","code":"import { strict as assert } from \"node:assert\";\n\nimport { headsAndTails } from \"generate-atomic-css\";\n\nassert.equal(headsAndTails.CONFIGHEAD, \"GENERATE-ATOMIC-CSS-CONFIG-STARTS\");\nassert.equal(headsAndTails.CONTENTTAIL, \"GENERATE-ATOMIC-CSS-CONTENT-ENDS\");"},"no-placeholders.js":{"title":"Leave CSS without generator placeholders unchanged","code":"import { strict as assert } from \"node:assert\";\n\nimport { genAtomic } from \"generate-atomic-css\";\n\nassert.deepEqual(genAtomic(\"body { color: red; }\"), {\n  log: { count: 0 },\n  result: \"body { color: red; }\",\n});"},"padding.js":{"title":"Align generated declarations","code":"import { strict as assert } from \"node:assert\";\n\nimport { genAtomic } from \"generate-atomic-css\";\n\nconst source = \".m$$$ { margin: $$$px; } | 9 | 10\";\n\nassert.equal(\n  genAtomic(source, {\n    includeConfig: false,\n    includeHeadsAndTails: false,\n    pad: true,\n  }).result,\n  \".m9  { margin:  9px; }\\n.m10 { margin: 10px; }\\n\",\n);\n\nassert.equal(\n  genAtomic(source, {\n    includeConfig: false,\n    includeHeadsAndTails: false,\n    pad: false,\n  }).result,\n  \".m9 { margin: 9px; }\\n.m10 { margin: 10px; }\\n\",\n);"},"progress.js":{"title":"Observe generation progress in a custom interval","code":"import { strict as assert } from \"node:assert\";\n\nimport { genAtomic } from \"generate-atomic-css\";\n\nconst progress = [];\nconst { log } = genAtomic(\".m$$$ { margin: $$$px; } | 1 | 2\", {\n  includeConfig: false,\n  includeHeadsAndTails: false,\n  reportProgressFunc: (percentage) => progress.push(percentage),\n  reportProgressFuncFrom: 20,\n  reportProgressFuncTo: 40,\n});\n\nassert.equal(log.count, 2);\nassert.equal(progress.length, 2);\nassert.equal(progress.every(Number.isFinite), true);"}},"html-all-known-attributes":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { allHtmlAttribs } from \"html-all-known-attributes\";\n\nassert.equal(allHtmlAttribs.has(\"href\"), true);"},"check-email-attributes.js":{"title":"Check email-client-specific HTML attributes","code":"import { strict as assert } from \"node:assert\";\n\nimport { allHtmlAttribs } from \"html-all-known-attributes\";\n\nassert.equal(allHtmlAttribs.has(\"mso-line-height-rule\"), true);\nassert.equal(allHtmlAttribs.has(\"vnd.ms-excel.numberformat\"), true);"},"collection-size.js":{"title":"Inspect the number of known attributes","code":"import { strict as assert } from \"node:assert\";\n\nimport { allHtmlAttribs } from \"html-all-known-attributes\";\n\nassert.equal(allHtmlAttribs.size, 702);"},"iterate-attributes.js":{"title":"Iterate through the known attributes","code":"import { strict as assert } from \"node:assert\";\n\nimport { allHtmlAttribs } from \"html-all-known-attributes\";\n\nconst gathered = [];\n\nfor (const attribute of allHtmlAttribs) {\n  if (gathered.length === 3) {\n    break;\n  }\n  gathered.push(attribute);\n}\n\nassert.deepEqual(gathered, [\"abbr\", \"accept\", \"accept-charset\"]);"},"reject-unknown-attributes.js":{"title":"Distinguish known attributes from application-specific ones","code":"import { strict as assert } from \"node:assert\";\n\nimport { allHtmlAttribs } from \"html-all-known-attributes\";\n\nassert.equal(allHtmlAttribs.has(\"class\"), true);\nassert.equal(allHtmlAttribs.has(\"data-project-specific\"), false);"}},"html-crush":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { crush, defaults, version } from \"html-crush\";\n\nassert.equal(\n  crush(\n    `<table width=\"100\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\n  <tr>\n    <td>\n      hi\n    </td>\n  </tr>\n</table>`,\n    { removeLineBreaks: true },\n  ).result,\n  `<table width=\"100\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\"><tr><td> hi\n</td></tr></table>`,\n);"},"css-comments.js":{"title":"Configure CSS comment removal","code":"import { strict as assert } from \"node:assert\";\n\nimport { crush } from \"html-crush\";\n\nconst source = \"<style>/* note */ .a { color: red; }</style>\";\n\nassert.equal(crush(source).result, \"<style>.a { color: red; }</style>\");\nassert.equal(\n  crush(source, { removeCSSComments: false }).result,\n  \"<style>/* note */ .a { color: red; }</style>\",\n);"},"custom-breakpoints.js":{"title":"Insert line breaks before selected tokens","code":"import { strict as assert } from \"node:assert\";\n\nimport { crush } from \"html-crush\";\n\nassert.equal(\n  crush(\"<m><n><o>\", {\n    removeLineBreaks: true,\n    breakToTheLeftOf: [\"<n\", \"<o\"],\n  }).result,\n  \"<m>\\n<n>\\n<o>\",\n);"},"custom-inline-tags.js":{"title":"Treat a custom element as inline","code":"import { strict as assert } from \"node:assert\";\n\nimport { crush, defaults } from \"html-crush\";\n\nconst source = \"<i>a</i><y>b</y>\";\n\nassert.equal(\n  crush(source, { lineLengthLimit: 9, removeLineBreaks: true }).result,\n  \"<i>a</i>\\n<y>b</y>\",\n);\nassert.equal(\n  crush(source, {\n    lineLengthLimit: 9,\n    removeLineBreaks: true,\n    mindTheInlineTags: [...defaults.mindTheInlineTags, \"y\"],\n  }).result,\n  source,\n);"},"html-comment-modes.js":{"title":"Choose which HTML comments to remove","code":"import { strict as assert } from \"node:assert\";\n\nimport { crush } from \"html-crush\";\n\nconst ordinary = \"a<!-- note -->b\";\nconst conditional = \"a<!--[if mso]>outlook<![endif]-->b\";\n\nassert.equal(crush(ordinary, { removeHTMLComments: 0 }).result, ordinary);\nassert.equal(crush(ordinary, { removeHTMLComments: 1 }).result, \"ab\");\nassert.equal(crush(ordinary, { removeHTMLComments: true }).result, \"ab\");\nassert.equal(crush(conditional, { removeHTMLComments: 1 }).result, conditional);\nassert.equal(crush(conditional, { removeHTMLComments: 2 }).result, \"aoutlookb\");"},"line-length-limit.js":{"title":"Wrap minified HTML at a line-length limit","code":"import { strict as assert } from \"node:assert\";\n\nimport { crush } from \"html-crush\";\n\nassert.equal(\n  crush(\"let me tell you <a><span>something</span></a> new\", {\n    lineLengthLimit: 10,\n    removeLineBreaks: true,\n  }).result,\n  \"let me\\ntell you\\n<a><span>something</span></a>\\nnew\",\n);"},"progress.js":{"title":"Observe progress in a custom interval","code":"import { strict as assert } from \"node:assert\";\n\nimport { crush } from \"html-crush\";\n\nconst progress = [];\nconst source = `<style>${\".a { color: red; }\\n\".repeat(1000)}</style>`;\n\ncrush(source, {\n  reportProgressFunc: (percentage) => progress.push(percentage),\n  reportProgressFuncFrom: 20,\n  reportProgressFuncTo: 40,\n});\n\nassert.equal(progress.length > 0, true);\nassert.equal(\n  progress.every((value) => value >= 20 && value <= 40),\n  true,\n);"},"remove-indentations.js":{"title":"Remove line indentations","code":"import { strict as assert } from \"node:assert\";\n\nimport { crush } from \"html-crush\";\n\nconst source = \"<div>\\n    <span>text</span>\\n</div>\";\n\nassert.equal(crush(source).result, \"<div>\\n<span>text</span>\\n</div>\");\nassert.equal(\n  crush(source, { removeIndentations: false }).result,\n  \"<div>\\n    <span>text</span>\\n</div>\",\n);"},"remove-line-breaks.js":{"title":"Remove HTML line breaks","code":"import { strict as assert } from \"node:assert\";\n\nimport { crush } from \"html-crush\";\n\nassert.equal(\n  crush(\"<div>\\n  <p>one</p>\\n  <p>two</p>\\n</div>\", {\n    removeLineBreaks: true,\n  }).result,\n  \"<div><p>one</p><p>two</p></div>\",\n);"},"result-metadata-and-ranges.js":{"title":"Inspect result metadata and edit ranges","code":"import { strict as assert } from \"node:assert\";\n\nimport { crush } from \"html-crush\";\n\nconst source = \" <p> x </p> \";\nconst result = crush(source);\n\nassert.equal(result.result, \"<p> x </p>\");\nassert.equal(result.log.originalLength, source.length);\nassert.equal(result.log.cleanedLength, result.result.length);\nassert.equal(result.log.originalLengthInCodeUnits, 12);\nassert.equal(result.log.cleanedLengthInCodeUnits, 10);\nassert.equal(result.log.codeUnitsSaved, 2);\nassert.equal(result.log.originalLengthInUtf8Bytes, 12);\nassert.equal(result.log.cleanedLengthInUtf8Bytes, 10);\nassert.equal(result.log.utf8BytesSaved, 2);\nassert.deepEqual(result.ranges, [\n  [0, 1],\n  [11, 12],\n]);"}},"html-entities-not-email-friendly":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { notEmailFriendlySetOnly } from \"html-entities-not-email-friendly\";\n\nassert.equal(notEmailFriendlySetOnly.has(\"GreaterTilde\"), true);\nassert.equal(notEmailFriendlySetOnly.has(\"nbsp\"), false);"},"collection-size.js":{"title":"Inspect the number of known unsafe named entities","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  notEmailFriendly,\n  notEmailFriendlySetOnly,\n} from \"html-entities-not-email-friendly\";\n\nassert.equal(Object.keys(notEmailFriendly).length, 1841);\nassert.equal(notEmailFriendlySetOnly.size, 1841);"},"entity-name-length-bounds.js":{"title":"Skip impossible entity-name lengths before consulting the sets","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  notEmailFriendlyMaxLength,\n  notEmailFriendlyMinLength,\n} from \"html-entities-not-email-friendly\";\n\nassert.equal(notEmailFriendlyMinLength, 2);\nassert.equal(notEmailFriendlyMaxLength, 31);"},"lowercase-membership.js":{"title":"Check entity names case-insensitively with the lowercase set","code":"import { strict as assert } from \"node:assert\";\n\nimport { notEmailFriendlyLowercaseSetOnly } from \"html-entities-not-email-friendly\";\n\nassert.equal(notEmailFriendlyLowercaseSetOnly.has(\"greatertilde\"), true);"},"replacement-lookup.js":{"title":"Look up a safer replacement for a named entity","code":"import { strict as assert } from \"node:assert\";\n\nimport { notEmailFriendly } from \"html-entities-not-email-friendly\";\n\nassert.equal(notEmailFriendly.GreaterTilde, \"#x2273\");"}},"html-img-alt":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { alts } from \"html-img-alt\";\n\n// string-in, string-out:\nassert.equal(\n  alts('zzz<img src=\"spacer.gif\" >zzz'),\n  'zzz<img src=\"spacer.gif\" alt=\"\" >zzz',\n);"},"preserve-alt-typography.js":{"title":"Preserve original typography in alt text","code":"import { strict as assert } from \"node:assert\";\n\nimport { alts } from \"html-img-alt\";\n\nassert.equal(\n  alts('<img alt=\" The new offer — 50% discount \" >', {\n    unfancyTheAltContents: false,\n  }),\n  '<img alt=\" The new offer — 50% discount \" >',\n);"},"repair-incomplete-alt.js":{"title":"Repair an alt attribute that has no value","code":"import { strict as assert } from \"node:assert\";\n\nimport { alts } from \"html-img-alt\";\n\nassert.equal(alts(\"<img alt=>\"), '<img alt=\"\" >');"},"unfancy-alt-text.js":{"title":"Normalize typography and surrounding spaces in alt text","code":"import { strict as assert } from \"node:assert\";\n\nimport { alts } from \"html-img-alt\";\n\nassert.equal(\n  alts('<img alt=\" The new offer — 50% discount \" >'),\n  '<img alt=\"The new offer - 50% discount\" >',\n);"},"xhtml-image.js":{"title":"Add an alt attribute while preserving XHTML closing syntax","code":"import { strict as assert } from \"node:assert\";\n\nimport { alts } from \"html-img-alt\";\n\nassert.equal(\n  alts('<img src=\"spacer.gif\"/>'),\n  '<img src=\"spacer.gif\" alt=\"\" />',\n);"}},"html-table-patcher":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { patcher } from \"html-table-patcher\";\n\nassert.equal(\n  patcher(\n    `<table>\n{% if customer.details.hasAccount %}\n<tr>\n  <td>\n    variation #1\n  </td>\n</tr>\n{% else %}\n<tr>\n  <td>\n    variation #2\n  </td>\n</tr>\n{% endif %}\n</table>`,\n  ).result,\n  `<table>\n\n<tr>\n  <td>\n    {% if customer.details.hasAccount %}\n  </td>\n</tr>\n\n<tr>\n  <td>\n    variation #1\n  </td>\n</tr>\n\n<tr>\n  <td>\n    {% else %}\n  </td>\n</tr>\n\n<tr>\n  <td>\n    variation #2\n  </td>\n</tr>\n\n<tr>\n  <td>\n    {% endif %}\n  </td>\n</tr>\n\n</table>`,\n);"},"add-cell-styles.js":{"title":"Add inline CSS to inserted table cells","code":"import { strict as assert } from \"node:assert\";\n\nimport { patcher } from \"html-table-patcher\";\n\nassert.equal(\n  patcher(\"<table>Message<tr><td>A</td><td>B</td></tr></table>\", {\n    cssStylesContent: \"font-weight: bold;\",\n  }).result,\n  `<table>\n<tr>\n  <td colspan=\"2\" style=\"font-weight: bold;\">\n    Message\n  </td>\n</tr>\n<tr><td>A</td><td>B</td></tr></table>`,\n);"},"always-center.js":{"title":"Center every inserted table cell","code":"import { strict as assert } from \"node:assert\";\n\nimport { patcher } from \"html-table-patcher\";\n\nassert.equal(\n  patcher(\"<table>Message<tr><td>A</td><td>B</td></tr></table>\", {\n    alwaysCenter: true,\n  }).result,\n  `<table>\n<tr>\n  <td colspan=\"2\" align=\"center\">\n    Message\n  </td>\n</tr>\n<tr><td>A</td><td>B</td></tr></table>`,\n);"},"ignore-commented-table.js":{"title":"Leave table-like markup inside an HTML comment untouched","code":"import { strict as assert } from \"node:assert\";\n\nimport { patcher } from \"html-table-patcher\";\n\nconst source = \"<!-- <table>Message<tr><td>A</td></tr></table> -->\";\n\nassert.equal(patcher(source).result, source);"},"infer-colspan.js":{"title":"Span inserted table cells across the existing columns","code":"import { strict as assert } from \"node:assert\";\n\nimport { patcher } from \"html-table-patcher\";\n\nassert.equal(\n  patcher(\"<table>Message<tr><td>A</td><td>B</td></tr></table>\").result,\n  `<table>\n<tr>\n  <td colspan=\"2\">\n    Message\n  </td>\n</tr>\n<tr><td>A</td><td>B</td></tr></table>`,\n);"},"patch-text-inside-row.js":{"title":"Move loose row text into its own cell and row","code":"import { strict as assert } from \"node:assert\";\n\nimport { patcher } from \"html-table-patcher\";\n\nassert.equal(\n  patcher(`<table>\n  <tr>\n    Condition\n    <td>Content</td>\n  </tr>\n</table>`).result,\n  `<table>\n  <tr>\n  <td>\n    Condition\n  </td>\n</tr>\n<tr>\n<td>Content</td>\n  </tr>\n</table>`,\n);"}},"is-char-suitable-for-html-attr-name":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrNameChar } from \"is-char-suitable-for-html-attr-name\";\n\n// Follows the spec:\n// https://html.spec.whatwg.org/multipage/syntax.html#attributes-2\n\nassert.equal(isAttrNameChar(\"a\"), true);"},"checks-the-first-character.js":{"title":"Only the first character is checked","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrNameChar } from \"is-char-suitable-for-html-attr-name\";\n\nassert.equal(isAttrNameChar(\"data-id\"), true);\nassert.equal(isAttrNameChar(\" data-id\"), false);"},"rejected-attribute-name-characters.js":{"title":"Characters rejected in attribute names","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrNameChar } from \"is-char-suitable-for-html-attr-name\";\n\nfor (const value of [\"_\", \"!\", \"?\", \" \", \"\", 1, undefined]) {\n  assert.equal(isAttrNameChar(value), false);\n}"},"supported-attribute-name-characters.js":{"title":"Characters allowed in attribute names","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrNameChar } from \"is-char-suitable-for-html-attr-name\";\n\nfor (const char of [\"a\", \"Z\", \"0\", \"-\", \":\"]) {\n  assert.equal(isAttrNameChar(char), true);\n}"}},"is-html-attribute-closing":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrClosing } from \"is-html-attribute-closing\";\n\nconst str = '<a href=\"zzz\" target=\"_blank\" style=\"color: black;\">';\n\n// <a href=\"zzz\" target=\"_blank\" ...\n//                      ^\n//                  index 21\n\n// <a href=\"zzz\" target=\"_blank\" ...\n//                             ^\n//                         index 28\n\nassert.equal(\n  isAttrClosing(\n    str, // reference string\n    21, // known opening (or in absence of a quote, a start of a value)\n    28, // we ask, is this a closing on the attribute?\n  ),\n  true, // the answer\n);"},"broken-1.js":{"title":"Broken #1","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrClosing } from \"is-html-attribute-closing\";\n\nassert.equal(\n  isAttrClosing(\n    \"<a href=\\\"z' click here</a>\",\n    //       ^ ^\n    //       | \\\n    //       |  \\_________________________________\n    //       |                                   |\n    8, // known opening                          |\n    10, // is this an attribute closing at index 10?\n  ),\n  true,\n);\n// => yes, indeed a closing of an attribute (not counting\n// the code is broken)"},"broken-2.js":{"title":"Broken #2","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrClosing } from \"is-html-attribute-closing\";\n\nassert.equal(\n  isAttrClosing(\n    \"<a b = = = \\\"c\\\" d = = = 'e'>\",\n    //          ^ ^\n    //          | |\n    //          | L_______________________________\n    //          |                                |\n    11, // known opening                         |\n    13, // is this an attribute closing at index 13?\n  ),\n  true,\n);\n// => true - indeed a closing of an attribute (not counting\n// the code is broken)"},"broken-3.js":{"title":"Broken #3","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrClosing } from \"is-html-attribute-closing\";\n\n// Correct code:\n// <img class=\"so-called\" alt=\"!\" border='10'/>\n\n// Broken code:\nconst str = \"<img class=\\\"so-called \\\"alt !' border 10'/>\";\n//                      ^\n//                known opening at idx 11\n\nassert.equal(isAttrClosing(str, 11, 22), true);\n// => true - indeed a closing of an attribute\n\nassert.equal(isAttrClosing(str, 11, 28), false);\n// => not a closing of an attribute\n\nassert.equal(isAttrClosing(str, 11, 39), false);\n// => not a closing of an attribute"},"invalid-indexes.js":{"title":"Return false for unusable source indexes","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrClosing } from \"is-html-attribute-closing\";\n\nassert.equal(isAttrClosing('<a href=\"x\">', 8, 8), false);\nassert.equal(isAttrClosing('<a href=\"x\">', 8, 99), false);\nassert.equal(isAttrClosing(\"\", 0, 1), false);"},"missing-equals-sign.js":{"title":"Recover when spaces replace attribute equals signs","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrClosing } from \"is-html-attribute-closing\";\n\nconst source = \"<a class \\\"button\\\" id 'example'>\";\n\nassert.equal(isAttrClosing(source, 9, 16), true);\nassert.equal(isAttrClosing(source, 21, 29), true);"},"missing-opening-quote.js":{"title":"Recover when an attribute value has no opening quote","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrClosing } from \"is-html-attribute-closing\";\n\nconst source = '<a href=example.com\" class=\"button\">Example</a>';\n\nassert.equal(isAttrClosing(source, 8, 19), true);\nassert.equal(isAttrClosing(source, 8, 27), false);"},"quotes-inside-value.js":{"title":"Distinguish quotes inside a value from its closing quote","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrClosing } from \"is-html-attribute-closing\";\n\nconst source = `<td style=\"font-family:'AbCd-Ef', 'AbCd', sans-serif;\">`;\n\nassert.equal(isAttrClosing(source, 10, 23), false);\nassert.equal(isAttrClosing(source, 10, 31), false);\nassert.equal(isAttrClosing(source, 10, 53), true);"},"single-quoted-value.js":{"title":"Detect the end of a single-quoted attribute value","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrClosing } from \"is-html-attribute-closing\";\n\nconst source = \"<a href='https://example.com'>Example</a>\";\n\nassert.equal(isAttrClosing(source, 8, 28), true);"},"templating-inside-value.js":{"title":"Ignore quotes that belong to templating code inside a value","code":"import { strict as assert } from \"node:assert\";\n\nimport { isAttrClosing } from \"is-html-attribute-closing\";\n\nconst source = '<a href=\"https://example.com?p=<%= @param %>\">';\n\nassert.equal(isAttrClosing(source, 8, 44), true);"}},"is-html-tag-opening":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { isOpening } from \"is-html-tag-opening\";\n\nconst html = \"<span>Text</span>\";\n\nassert.equal(isOpening(html, 0), true);"},"closing-tag.js":{"title":"Recognise a closing tag","code":"import { strict as assert } from \"node:assert\";\n\nimport { isOpening } from \"is-html-tag-opening\";\n\nconst html = \"<p>Text</p>\";\n\nassert.equal(isOpening(html, html.indexOf(\"</\")), true);"},"ignore-comparison-operators.js":{"title":"Ignore a less-than sign used for comparison","code":"import { strict as assert } from \"node:assert\";\n\nimport { isOpening } from \"is-html-tag-opening\";\n\nconst text = \"When a < b, keep comparing; then render <strong>done</strong>.\";\n\nassert.equal(isOpening(text, text.indexOf(\"<\")), false);\nassert.equal(isOpening(text, text.indexOf(\"<strong>\")), true);"},"opts.allowCustomTagNames.js":{"title":"`opts.allowCustomTagNames`","code":"import { strict as assert } from \"node:assert\";\n\nimport { isOpening } from \"is-html-tag-opening\";\n\n// recognised tag\nassert.equal(isOpening(\"abc <div>\", 4), true);\n//                          ^\n\n// unrecognised tag\nassert.equal(isOpening(\"abc <zzz>\", 4), false);\n//                          ^\n\n// but with opts.allowCustomTagNames result is \"true\"\nassert.equal(\n  isOpening(\"abc <zzz>\", 4, {\n    allowCustomTagNames: true,\n  }),\n  true,\n);"},"opts.skipOpeningBracket.js":{"title":"`opts.skipOpeningBracket`","code":"import { strict as assert } from \"node:assert\";\n\nimport { isOpening } from \"is-html-tag-opening\";\n\n// missing opening bracket:\nassert.equal(isOpening('<a>div class=\"w-64 h-3\">', 3), false);\n//                         ^\n// result is instant \"false\" because `idx` has to be\n// on an opening bracket (besides checking for tag name\n// being present and recognised and attributes being present)\n\n// but with opts.skipOpeningBracket we remove the requirement\n// that \"idx\" has to be on a bracket - algorithm detects valid\n// tag name and the attribute that follows and recognise it's a\n// tag starting:\nassert.equal(\n  isOpening('<a>div class=\"w-64 h-3\">', 3, {\n    skipOpeningBracket: true,\n  }),\n  true,\n);"},"self-closing-tag-with-attributes.js":{"title":"Recognise a self-closing tag with attributes","code":"import { strict as assert } from \"node:assert\";\n\nimport { isOpening } from \"is-html-tag-opening\";\n\nconst html = 'before <img src=\"image.jpg\" alt=\"Example\" /> after';\n\nassert.equal(isOpening(html, html.indexOf(\"<\")), true);"}},"is-language-code":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.deepEqual(isLangCode(\"sr-Latn\"), {\n  res: true,\n  message: null,\n});"},"case-insensitive.js":{"title":"Match registered tags without regard to letter case","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.equal(isLangCode(\"SR-lAtN-rS\").res, true);\nassert.equal(isLangCode(\"I-KLINGON\").res, true);"},"duplicate-region-error.js":{"title":"Explain a language tag containing two region subtags","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.deepEqual(isLangCode(\"de-419-DE\"), {\n  res: false,\n  message: 'Two region subtags, \"419\" and \"de\".',\n});"},"extended-language-prefix-error.js":{"title":"Explain an extended language subtag with the wrong prefix","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.deepEqual(isLangCode(\"en-cmn\"), {\n  res: false,\n  message: 'Extended language subtag \"cmn\" must follow \"zh\".',\n});"},"extended-language-subtag.js":{"title":"Validate an extended language subtag after its registered prefix","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.deepEqual(isLangCode(\"zh-cmn-Hans-CN\"), {\n  res: true,\n  message: null,\n});"},"extensions.js":{"title":"Validate multiple uniquely prefixed extensions","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.deepEqual(isLangCode(\"en-a-myext-b-another\"), {\n  res: true,\n  message: null,\n});"},"grandfathered-tag.js":{"title":"Accept an IANA-grandfathered language tag","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.deepEqual(isLangCode(\"i-klingon\"), {\n  res: true,\n  message: null,\n});"},"malformed-tag.js":{"title":"Reject text that does not resemble a language tag","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.deepEqual(isLangCode(\"en_US\"), {\n  res: false,\n  message: \"Does not resemble a language tag.\",\n});"},"private-use-tag.js":{"title":"Validate a private-use language tag","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.deepEqual(isLangCode(\"x-project-internal\"), {\n  res: true,\n  message: null,\n});"},"repeated-variant-error.js":{"title":"Explain why a repeated variant is invalid","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.deepEqual(isLangCode(\"sl-rozaj-rozaj\"), {\n  res: false,\n  message: 'Repeated variant subtag, \"rozaj\".',\n});"},"script-region-and-variant.js":{"title":"Validate language, script, region, and variant subtags together","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.deepEqual(isLangCode(\"hy-Latn-IT-arevela\"), {\n  res: true,\n  message: null,\n});"},"singleton-error.js":{"title":"Explain an extension singleton without extension content","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.deepEqual(isLangCode(\"en-a\"), {\n  res: false,\n  message: 'Ends with singleton, \"a\".',\n});"},"various.js":{"title":"Various examples","code":"import { strict as assert } from \"node:assert\";\n\nimport { isLangCode } from \"is-language-code\";\n\nassert.equal(isLangCode(\"de\").res, true);\n// => true because it's a German language code\n\nassert.equal(isLangCode(\"fr\").res, true);\n// => true because it's a French language code\n\nassert.equal(isLangCode(\"ja\").res, true);\n// => true because it's a Japanese language code\n\nassert.equal(isLangCode(\"zzz\").res, false);\n// => false - unrecognised. npm package \"ietf-language-tag-regex\" would fail this\n\nassert.equal(isLangCode(\"1\").res, false);\n// => false - not recognised language code\n\nassert.equal(isLangCode(\"x-klingon\").res, true);\n// => true - private use\n\nassert.equal(isLangCode(\"x-whatever\").res, true);\n// => true - private use\n\nassert.equal(isLangCode(\"zh-Hant\").res, true);\n// => true - Chinese written using the Traditional Chinese script\n\nassert.equal(isLangCode(\"zh-cmn-Hans-CN\").res, true);\n// => true - Chinese, Mandarin, Simplified script, as used in China\n\nassert.equal(isLangCode(\"zh-Hans-CN\").res, true);\n// => true - Chinese written using the Simplified script as used in mainland China\n\nassert.equal(isLangCode(\"sr-Latn-RS\").res, true);\n// => true - Serbian written using the Latin script as used in Serbia\n\nassert.equal(isLangCode(\"sl-rozaj\").res, true);\n// => true - Resian dialect of Slovenian\n\nassert.equal(isLangCode(\"sl-nedis\").res, true);\n// => true - Nadiza dialect of Slovenian\n\nassert.equal(isLangCode(\"de-CH-1901\").res, true);\n// => true - German as used in Switzerland using the 1901 variant [orthography]\n\nassert.equal(isLangCode(\"sl-IT-nedis\").res, true);\n// => true - Slovenian as used in Italy, Nadiza dialect\n\nassert.equal(isLangCode(\"hy-Latn-IT-arevela\").res, true);\n// => true - Eastern Armenian written in Latin script, as used in Italy\n\nassert.equal(isLangCode(\"en-US\").res, true);\n// => true - English as used in the United States\n\nassert.equal(isLangCode(\"de-CH-x-phonebk\").res, true);\n// => true - private use subtag (x-)\n\nassert.equal(isLangCode(\"az-Arab-x-AZE-derbend\").res, true);\n// => true - private use subtag\n\nassert.equal(isLangCode(\"x-whatever\").res, true);\n// => true - private use subtag using singleton x-\n\nassert.equal(isLangCode(\"qaa-Qaaa-QM-x-southern\").res, true);\n// => true\n\nassert.equal(isLangCode(\"de-Qaaa\").res, true);\n// => true - private use script subtag (Qaaa)\n\nassert.equal(isLangCode(\"sr-Latn-QM\").res, true);\n// => true - Serbian, Latin script, private region QM\n\nassert.equal(isLangCode(\"en-US-u-islamcal\").res, true);\n// => true - tag with extension\n\nassert.equal(isLangCode(\"zh-CN-a-myext-x-private\").res, true);\n// => true - tag with extension\n\nassert.equal(isLangCode(\"en-a-myext-b-another\").res, true);\n// => true - tag with extension\n\nassert.equal(isLangCode(\"de-419-DE\").res, false);\n// => false - two region tags\n\nassert.equal(isLangCode(\"a-DE\").res, false);\n// => false - use of a single-character subtag in primary position\n\nassert.equal(isLangCode(\"ar-a-aaa-b-bbb-a-ccc\").res, false);\n// => false - two extensions with same single-letter prefix"}},"is-media-descriptor":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { isMediaD } from \"is-media-descriptor\";\n\nassert.deepEqual(isMediaD(\"screeen\"), [\n  {\n    idxFrom: 0,\n    idxTo: 7,\n    message: 'Did you mean \"screen\"?',\n    fix: {\n      ranges: [[0, 7, \"screen\"]],\n    },\n  },\n]);"},"missing-space.js":{"title":"Report missing descriptor whitespace","code":"import { strict as assert } from \"node:assert\";\n\nimport { isMediaD } from \"is-media-descriptor\";\n\nassert.deepEqual(isMediaD(\"screen and(color)\"), [\n  {\n    idxFrom: 7,\n    idxTo: 10,\n    message: 'Space after \"and\" missing.',\n    fix: { ranges: [[10, 10, \" \"]] },\n  },\n]);"},"offset.js":{"title":"Offset reported indexes","code":"import { strict as assert } from \"node:assert\";\n\nimport { isMediaD } from \"is-media-descriptor\";\n\n// The descriptor starts at index 10 in a larger source string.\nassert.deepEqual(isMediaD(\"screeen\", { offset: 10 }), [\n  {\n    idxFrom: 10,\n    idxTo: 17,\n    message: 'Did you mean \"screen\"?',\n    fix: { ranges: [[10, 17, \"screen\"]] },\n  },\n]);"},"valid-descriptor.js":{"title":"A valid media descriptor","code":"import { strict as assert } from \"node:assert\";\n\nimport { isMediaD } from \"is-media-descriptor\";\n\nassert.deepEqual(isMediaD(\"screen and (min-width: 600px)\"), []);"},"whitespace-fix.js":{"title":"Report surrounding whitespace","code":"import { strict as assert } from \"node:assert\";\n\nimport { isMediaD } from \"is-media-descriptor\";\n\nassert.deepEqual(isMediaD(\" screen \"), [\n  {\n    idxFrom: 0,\n    idxTo: 8,\n    message: \"Remove whitespace.\",\n    fix: {\n      ranges: [\n        [0, 1],\n        [7, 8],\n      ],\n    },\n  },\n]);"}},"is-relative-uri":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { isRel } from \"is-relative-uri\";\n\nassert.deepEqual(isRel(\".../resource.txt\"), {\n  res: false,\n  message: \"Three consecutive dots.\",\n});"},"invalid-characters.js":{"title":"Invalid URI characters","code":"import { strict as assert } from \"node:assert\";\n\nimport { isRel } from \"is-relative-uri\";\n\nassert.deepEqual(isRel(\"images/my logo.svg\"), {\n  res: false,\n  message: \"Remove whitespace.\",\n});"},"scheme-detection.js":{"title":"URI scheme detection","code":"import { strict as assert } from \"node:assert\";\n\nimport { isRel } from \"is-relative-uri\";\n\nassert.deepEqual(isRel(\"mailto:user@example.com\"), {\n  res: false,\n  message: null,\n});\n\n// Scheme detection can be disabled when another layer validates schemes.\nassert.equal(\n  isRel(\"mailto:user@example.com\", { flagUpUrisWithSchemes: false }).res,\n  true,\n);"},"valid-relative-uri.js":{"title":"A valid relative URI","code":"import { strict as assert } from \"node:assert\";\n\nimport { isRel } from \"is-relative-uri\";\n\nassert.deepEqual(isRel(\"images/logo.svg\"), { res: true, message: null });"}},"js-row-num":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixRowNums } from \"js-row-num\";\n\n// sets line number to 002 because it's on row number two\nconst { result } = fixRowNums(\n  'const foo = \"bar\";\\n console.log(`0 foo = ${foo}`)',\n);\nassert.equal(result, 'const foo = \"bar\";\\n console.log(`002 foo = ${foo}`)');"},"custom-trigger.js":{"title":"Custom logging trigger","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixRowNums } from \"js-row-num\";\n\nassert.equal(\n  fixRowNums(\"logger(`1 first`)\\nconsole.log(`2 second`)\", {\n    triggerKeywords: [\"logger\"],\n  }).result,\n  \"logger(`001 first`)\\nconsole.log(`2 second`)\",\n);"},"extracted-log-content.js":{"title":"Process already-extracted log contents","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixRowNums } from \"js-row-num\";\n\nassert.equal(\n  fixRowNums(\"`9 extracted content`\", {\n    extractedLogContentsWereGiven: true,\n  }).result,\n  \"`001 extracted content`\",\n);"},"override-row-number.js":{"title":"Override every detected row number","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixRowNums } from \"js-row-num\";\n\nassert.equal(\n  fixRowNums(\"console.log(`9 first`)\\nconsole.log(`8 second`)\", {\n    overrideRowNum: 42,\n  }).result,\n  \"console.log(`042 first`)\\nconsole.log(`042 second`)\",\n);"},"padding.js":{"title":"Custom line-number padding","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixRowNums } from \"js-row-num\";\n\nassert.equal(\n  fixRowNums(\"console.log(`9 first`)\\nconsole.log(`8 second`)\", {\n    padStart: 5,\n  }).result,\n  \"console.log(`00001 first`)\\nconsole.log(`00002 second`)\",\n);"},"returned-ranges.js":{"title":"Inspect the replacement ranges","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixRowNums } from \"js-row-num\";\n\nconst { ranges } = fixRowNums(\n  'const foo = \"bar\";\\n console.log(`0 foo = $' + \"{foo}`)\",\n);\n\nassert.deepEqual(ranges, [[33, 34, \"002\"]]);"}},"json-comb-core":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { getKeysetSync } from \"json-comb-core\";\n\n// calculate the schema - superset of all possible keys used across\n// all JSON files\nconst schema = getKeysetSync([\n  {\n    // <- object #1\n    a: \"a\",\n    b: \"c\",\n    c: {\n      d: \"d\",\n      e: \"e\",\n    },\n  },\n  {\n    // <- object #2\n    a: \"a\",\n  },\n  {\n    // <- object #3\n    c: {\n      f: \"f\",\n    },\n  },\n]);\n\nassert.deepEqual(schema, {\n  a: false,\n  b: false,\n  c: {\n    d: false,\n    e: false,\n    f: false,\n  },\n});"},"async-custom-keyset-placeholder.js":{"title":"Compute a keyset from promises with a custom placeholder","code":"import { strict as assert } from \"node:assert\";\n\nimport { getKeyset } from \"json-comb-core\";\n\nconst schema = await getKeyset(\n  [Promise.resolve({ name: \"Ada\" }), Promise.resolve({ role: \"admin\" })],\n  { placeholder: \"missing\" },\n);\n\nassert.deepEqual(schema, { name: \"missing\", role: \"missing\" });"},"async-enforce-options.js":{"title":"Enforce a keyset asynchronously, with options","code":"import { strict as assert } from \"node:assert\";\n\nimport { enforceKeyset } from \"json-comb-core\";\n\nconst result = await enforceKeyset(\n  { profile: null },\n  { profile: { name: false }, active: false },\n  { useNullAsExplicitFalse: false },\n);\n\nassert.deepEqual(result, { active: false, profile: { name: false } });"},"custom-comment-key-marker.js":{"title":"Mark comment keys with a custom suffix","code":"import { strict as assert } from \"node:assert\";\n\nimport { findUnusedSync } from \"json-comb-core\";\n\nassert.deepEqual(\n  findUnusedSync(\n    [\n      { title: \"One\", title_note: false, unused: false },\n      { title: \"Two\", title_note: false, unused: false },\n    ],\n    { comments: \"_note\" },\n  ),\n  [\"unused\"],\n);"},"custom-enforcement-placeholder.js":{"title":"Enforce a keyset using a custom placeholder","code":"import { strict as assert } from \"node:assert\";\n\nimport { enforceKeysetSync } from \"json-comb-core\";\n\nassert.deepEqual(\n  enforceKeysetSync(\n    { settings: true },\n    { settings: { theme: true }, enabled: true },\n    {\n      placeholder: true,\n      doNotFillThesePathsIfTheyContainPlaceholders: [\"settings\"],\n    },\n  ),\n  { enabled: true, settings: true },\n);"},"custom-keyset-placeholder.js":{"title":"Compute a keyset using a custom placeholder","code":"import { strict as assert } from \"node:assert\";\n\nimport { getKeysetSync } from \"json-comb-core\";\n\nassert.deepEqual(\n  getKeysetSync([{ name: \"Ada\" }, { role: \"admin\" }], {\n    placeholder: null,\n  }),\n  { name: null, role: null },\n);"},"custom-unused-placeholder.js":{"title":"Find unused keys marked by a custom placeholder","code":"import { strict as assert } from \"node:assert\";\n\nimport { findUnusedSync } from \"json-comb-core\";\n\nassert.deepEqual(\n  findUnusedSync(\n    [\n      { name: \"Ada\", retired: null },\n      { name: \"Grace\", retired: null },\n    ],\n    { placeholder: null },\n  ),\n  [\"retired\"],\n);"},"do-not-expand-placeholder-path.js":{"title":"Leave the chosen placeholder paths unexpanded","code":"import { strict as assert } from \"node:assert\";\n\nimport { enforceKeysetSync } from \"json-comb-core\";\n\nconst schema = { name: false, settings: { theme: false } };\n\nassert.deepEqual(\n  enforceKeysetSync({ name: \"Ada\", settings: false }, schema, {\n    doNotFillThesePathsIfTheyContainPlaceholders: [\"settings\"],\n  }),\n  { name: \"Ada\", settings: false },\n);"},"enforce-computed-keyset.js":{"title":"Enforce a keyset computed from many objects","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  enforceKeysetSync,\n  getKeysetSync,\n} from \"json-comb-core\";\n\nconst objects = [\n  { a: \"a\", b: \"b\", c: { d: \"d\", e: \"e\" } },\n  { a: \"a\" },\n  { c: { f: \"f\" } },\n];\nconst schema = getKeysetSync(objects);\n\nassert.deepEqual(enforceKeysetSync(objects[1], schema), {\n  a: \"a\",\n  b: false,\n  c: { d: false, e: false, f: false },\n});"},"enforceKeyset.js":{"title":"Asynchronous `enforceKeyset()`","code":"import { strict as assert } from \"node:assert\";\n\nimport { enforceKeyset, getKeyset } from \"json-comb-core\";\n\n// Let's enforce the keyset using previously-calculated schema.\n\n// Let's use an async IIFE to trigger the action and let us use await:\n(async () => {\n  // let's create three plain objects, each somewhat overlapping with others:\n  let obj1 = {\n    b: [\n      {\n        c: \"ccc\",\n        d: \"ddd\",\n      },\n    ],\n    a: \"aaa\",\n  };\n  let obj2 = {\n    a: \"ccc\",\n    e: \"eee\",\n  };\n  let obj3 = {\n    a: \"zzz\",\n  };\n  // calculate the schema:\n  let schema = await getKeyset([obj1, obj2, obj3]);\n\n  const enforced = await Promise.all(\n    [obj1, obj2, obj3].map((object) => enforceKeyset(object, schema)),\n  );\n\n  assert.deepEqual(\n    { schema, enforced },\n    {\n      schema: {\n        a: false,\n        b: [{ c: false, d: false }],\n        e: false,\n      },\n      enforced: [\n        { a: \"aaa\", b: [{ c: \"ccc\", d: \"ddd\" }], e: false },\n        { a: \"ccc\", b: [{ c: false, d: false }], e: \"eee\" },\n        { a: \"zzz\", b: [{ c: false, d: false }], e: false },\n      ],\n    },\n  );\n})();"},"enforceKeysetSync.js":{"title":"Synchronous `enforceKeysetSync()`","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  enforceKeyset,\n  enforceKeysetSync,\n  findUnusedSync,\n  getKeyset,\n  getKeysetSync,\n  noNewKeysSync,\n  sortAllObjectsSync,\n} from \"json-comb-core\";\n\nconst schema = {\n  a: false,\n  b: false,\n  c: {\n    d: false,\n    e: false,\n    f: false,\n  },\n};\n\nassert.deepEqual(\n  enforceKeysetSync(\n    {\n      c: { d: \"x\" },\n    },\n    schema,\n  ),\n  {\n    a: false,\n    b: false,\n    c: {\n      d: \"x\",\n      e: false,\n      f: false,\n    },\n  },\n);"},"expand-null-into-schema.js":{"title":"Expand a `null` value into the schema","code":"import { strict as assert } from \"node:assert\";\n\nimport { enforceKeysetSync } from \"json-comb-core\";\n\nassert.deepEqual(\n  enforceKeysetSync(\n    { profile: null },\n    { profile: { name: false }, active: false },\n    { useNullAsExplicitFalse: false },\n  ),\n  { active: false, profile: { name: false } },\n);"},"findUnusedSync-2.js":{"title":"Synchronous `findUnusedSync()` - example #2","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  enforceKeyset,\n  enforceKeysetSync,\n  findUnusedSync,\n  getKeyset,\n  getKeysetSync,\n  noNewKeysSync,\n  sortAllObjectsSync,\n} from \"json-comb-core\";\n\n// This function will work on arrays of both normalised and not normalised object sets.\nassert.deepEqual(\n  findUnusedSync([\n    {\n      a: [\n        {\n          k: false,\n          l: false,\n          m: false,\n        },\n        {\n          k: \"k\",\n          l: false,\n          m: \"m\",\n        },\n      ],\n      b: \"bbb1\",\n      c: false,\n    },\n    {\n      a: [\n        {\n          k: \"k\",\n          l: false,\n          m: \"m\",\n        },\n        {\n          k: \"k\",\n          l: false,\n          m: \"m\",\n        },\n      ],\n      b: \"bbb2\",\n      c: false,\n    },\n    { b: false },\n    { c: false },\n  ]),\n  [\"c\", \"a[0].l\"],\n);"},"findUnusedSync.js":{"title":"Synchronous `findUnusedSync()` - example #1","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  enforceKeyset,\n  enforceKeysetSync,\n  findUnusedSync,\n  getKeyset,\n  getKeysetSync,\n  noNewKeysSync,\n  sortAllObjectsSync,\n} from \"json-comb-core\";\n\nassert.deepEqual(\n  findUnusedSync([\n    {\n      // <- object #1\n      a: false,\n      b: \"bbb1\",\n      c: false,\n    },\n    {\n      // <- object #2\n      a: \"aaa\",\n      b: \"bbb2\",\n      c: false,\n    },\n    {}, // <- object #3\n  ]),\n  [\"c\"],\n);"},"getKeyset.js":{"title":"Asynchronous `getKeyset()`","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  enforceKeyset,\n  enforceKeysetSync,\n  findUnusedSync,\n  getKeyset,\n  getKeysetSync,\n  noNewKeysSync,\n  sortAllObjectsSync,\n} from \"json-comb-core\";\n\n// Let's calculate the schema of the following arrays of plain objects,\n// and do it asynchronously.\n\n// Let's use an async IIFE to trigger the action and let us use await:\n(async () => {\n  // First, prepare array of promises:\n  let source = [\n    {\n      a: \"a\",\n      b: \"c\",\n      c: {\n        d: \"d\",\n        e: \"e\",\n      },\n    },\n    {\n      a: \"a\",\n    },\n    {\n      c: {\n        f: \"f\",\n      },\n    },\n  ].map((el) => Promise.resolve(el));\n\n  // use async/await to avoid using .then\n  assert.deepEqual(await getKeyset(source), {\n    a: false,\n    b: false,\n    c: {\n      d: false,\n      e: false,\n      f: false,\n    },\n  });\n})();"},"getKeysetSync.js":{"title":"Synchronous `getKeysetSync()`","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  enforceKeyset,\n  enforceKeysetSync,\n  findUnusedSync,\n  getKeyset,\n  getKeysetSync,\n  noNewKeysSync,\n  sortAllObjectsSync,\n} from \"json-comb-core\";\n\nconst schema = getKeysetSync([\n  {\n    // <- object #1\n    a: \"a\",\n    b: \"c\",\n    c: {\n      d: \"d\",\n      e: \"e\",\n    },\n  },\n  {\n    // <- object #2\n    a: \"a\",\n  },\n  {\n    // <- object #3\n    c: {\n      f: \"f\",\n    },\n  },\n]);\n\nassert.deepEqual(schema, {\n  a: false,\n  b: false,\n  c: {\n    d: false,\n    e: false,\n    f: false,\n  },\n});"},"noNewKeys-2.js":{"title":"Synchronous `noNewKeysSync()` - example #2","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  enforceKeyset,\n  enforceKeysetSync,\n  findUnusedSync,\n  getKeyset,\n  getKeysetSync,\n  noNewKeysSync,\n  sortAllObjectsSync,\n} from \"json-comb-core\";\n\nassert.deepEqual(\n  noNewKeysSync(\n    {\n      // <- input we're checking\n      z: [\n        {\n          a: \"a\",\n          b: \"b\",\n          c: \"c\",\n        },\n        {\n          a: false,\n          b: false,\n          c: \"c\",\n        },\n      ],\n    },\n    {\n      // <- reference keyset\n      z: [\n        {\n          a: \"a\",\n          b: \"b\",\n        },\n        {\n          a: false,\n          b: false,\n        },\n      ],\n    },\n  ),\n  [\"z[0].c\", \"z[1].c\"],\n);"},"noNewKeys.js":{"title":"Synchronous `noNewKeysSync()` - example #1","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  enforceKeyset,\n  enforceKeysetSync,\n  findUnusedSync,\n  getKeyset,\n  getKeysetSync,\n  noNewKeysSync,\n  sortAllObjectsSync,\n} from \"json-comb-core\";\n\n// We are going to catch the rogue key `b`:\n\nassert.deepEqual(\n  noNewKeysSync(\n    {\n      // <- input we're checking\n      a: \"a\",\n      b: \"b\",\n      c: \"c\",\n    },\n    {\n      // <- reference keyset\n      a: \"aaa\",\n      c: \"ccc\",\n    },\n  ),\n  [\"b\"], // list of rogue paths\n);"},"sort-semver-object-keys.js":{"title":"Sort object keys in semver order","code":"import { strict as assert } from \"node:assert\";\n\nimport { sortAllObjectsSync } from \"json-comb-core\";\n\nassert.deepEqual(\n  Object.keys(\n    sortAllObjectsSync({\n      \"10.0.0\": \"latest\",\n      \"2.10.0\": \"middle\",\n      \"2.9.0\": \"oldest\",\n    }),\n  ),\n  [\"2.9.0\", \"2.10.0\", \"10.0.0\"],\n);"},"sortAllObjectsSync.js":{"title":"Synchronous `getKeysetSync()`","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  enforceKeyset,\n  enforceKeysetSync,\n  findUnusedSync,\n  getKeyset,\n  getKeysetSync,\n  noNewKeysSync,\n  sortAllObjectsSync,\n} from \"json-comb-core\";\n\nassert.deepEqual(\n  sortAllObjectsSync({\n    a: \"a\",\n    c: \"c\",\n    b: \"b\",\n  }),\n  {\n    a: \"a\",\n    b: \"b\",\n    c: \"c\",\n  },\n);"}},"json-variables":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar({\n    a: \"some text %%_var1.key1.0_%% more text %%_var2.key2.key3.1_%%\",\n    b: \"something\",\n    var1: { key1: [\"value1\"] },\n    var2: { key2: { key3: [\"\", \"value2\"] } },\n  }),\n  {\n    a: \"some text value1 more text value2\",\n    b: \"something\",\n    var1: { key1: [\"value1\"] },\n    var2: { key2: { key3: [\"\", \"value2\"] } },\n  },\n);"},"allow-double-wrapping.js":{"title":"Allow a resolved value to be wrapped twice","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar(\n    { first: \"%%_second_%%\", second: \"%%_value_%%\", value: \"x\" },\n    {\n      wrapHeadsWith: \"{\",\n      wrapTailsWith: \"}\",\n      preventDoubleWrapping: false,\n    },\n  ),\n  { first: \"{{x}}\", second: \"{x}\", value: \"x\" },\n);"},"allow-unresolved-variable.js":{"title":"Allow variables that cannot be resolved","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar({ message: \"Hello %%_missing_%%\" }, { allowUnresolved: true }),\n  { message: \"Hello \" },\n);"},"boolean-resolution-policy.js":{"title":"Control how booleans resolve","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar(\n    {\n      result: \"%%_enabled_%% then %%_disabled_%%\",\n      enabled: true,\n      disabled: false,\n    },\n    { resolveToFalseIfAnyValuesContainBool: false },\n  ),\n  { result: true, enabled: true, disabled: false },\n);"},"custom-data-container-suffix.js":{"title":"Use a custom data container suffix","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar(\n    {\n      card: { title: \"%%_name_%%\" },\n      card_vars: { name: \"Ada\" },\n    },\n    { dataContainerIdentifierTails: \"_vars\" },\n  ),\n  {\n    card: { title: \"Ada\" },\n    card_vars: { name: \"Ada\" },\n  },\n);"},"custom-markers.js":{"title":"Use custom variable markers","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar(\n    { greeting: \"Hello, {{ name }}\", name: \"Ada\" },\n    { heads: \"{{\", tails: \"}}\" },\n  ),\n  { greeting: \"Hello, Ada\", name: \"Ada\" },\n);"},"custom-no-wrap-markers.js":{"title":"Configure markers that resolve variables without output wrapping","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar(\n    {\n      wrapped: \"%%_name_%%\",\n      unwrapped: \"(( name ))\",\n      name: \"Ada\",\n    },\n    {\n      headsNoWrap: \"(( \",\n      tailsNoWrap: \" ))\",\n      wrapHeadsWith: \"{{ \",\n      wrapTailsWith: \" }}\",\n    },\n  ),\n  { wrapped: \"{{ Ada }}\", unwrapped: \"Ada\", name: \"Ada\" },\n);"},"data-container.js":{"title":"Resolve variables from a data container","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar({\n    card: { title: \"%%_name_%%\" },\n    card_data: { name: \"Ada\" },\n  }),\n  {\n    card: { title: \"Ada\" },\n    card_data: { name: \"Ada\" },\n  },\n);"},"disable-all-wrapping.js":{"title":"Switch off all wrapping","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar(\n    { greeting: \"Hello %%_name_%%\", name: \"Ada\" },\n    {\n      wrapHeadsWith: \"<\",\n      wrapTailsWith: \">\",\n      wrapGlobalFlipSwitch: false,\n    },\n  ),\n  { greeting: \"Hello Ada\", name: \"Ada\" },\n);"},"disable-data-container-lookup.js":{"title":"Ignore data containers","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar(\n    {\n      name: \"Root\",\n      card: { title: \"%%_name_%%\" },\n      card_data: { name: \"Local\" },\n    },\n    { lookForDataContainers: false },\n  ),\n  {\n    name: \"Root\",\n    card: { title: \"Root\" },\n    card_data: { name: \"Local\" },\n  },\n);"},"do-not-wrap-selected-variables.js":{"title":"Leave the selected variables unwrapped","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar(\n    {\n      output: \"%%_publicName_%% / %%_internalCode_%%\",\n      publicName: \"Ada\",\n      internalCode: \"A1\",\n    },\n    {\n      wrapHeadsWith: \"<\",\n      wrapTailsWith: \">\",\n      dontWrapVars: \"internal*\",\n    },\n  ),\n  {\n    output: \"<Ada> / A1\",\n    publicName: \"Ada\",\n    internalCode: \"A1\",\n  },\n);"},"no-wrap-markers.js":{"title":"Skip wrapping using alternative markers","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar(\n    {\n      wrapped: \"%%_name_%%\",\n      unwrapped: \"%%-name-%%\",\n      name: \"Ada\",\n    },\n    { wrapHeadsWith: \"{{\", wrapTailsWith: \"}}\" },\n  ),\n  { wrapped: \"{{Ada}}\", unwrapped: \"Ada\", name: \"Ada\" },\n);"},"reject-number-inside-string.js":{"title":"Reject a number inserted into a string","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.throws(\n  () =>\n    jVar(\n      { message: \"Count: %%_count_%% items\", count: 2 },\n      { throwWhenNonStringInsertedInString: true },\n    ),\n  /THROW_ID_04/,\n);"},"reject-single-marker-values.js":{"title":"Reject values containing a lone marker","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.throws(\n  () => jVar({ value: \"%%_\" }, { noSingleMarkers: true }),\n  /THROW_ID_21/,\n);"},"treat-booleans-as-empty-text.js":{"title":"Resolve booleans to empty text","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar(\n    { message: \"before %%_flag_%% after\", flag: false },\n    { resolveToBoolIfAnyValuesContainBool: false },\n  ),\n  { message: \"before  after\", flag: false },\n);"},"unresolved-variable-fallback.js":{"title":"Replace unresolved variables with a fallback","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar({ message: \"Hello %%_missing_%%\" }, { allowUnresolved: \"unknown\" }),\n  { message: \"Hello unknown\" },\n);"},"whole-number-keeps-number-type.js":{"title":"A whole number keeps its type","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nconst result = jVar({ total: \"%%_count_%%\", count: 42 });\n\nassert.equal(result.total, 42);\nassert.equal(typeof result.total, \"number\");"},"wrap-resolved-values.js":{"title":"Wrap the resolved values","code":"import { strict as assert } from \"node:assert\";\n\nimport { jVar } from \"json-variables\";\n\nassert.deepEqual(\n  jVar(\n    { template: \"Hello %%_name_%%\", name: \"Ada\" },\n    { wrapHeadsWith: \"${\", wrapTailsWith: \"}\" },\n  ),\n  // biome-ignore lint/suspicious/noTemplateCurlyInString: the configured output intentionally uses template syntax\n  { template: \"Hello ${Ada}\", name: \"Ada\" },\n);"}},"lerna-clean-changelogs":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { cleanChangelogs } from \"lerna-clean-changelogs\";\n\n// are all values equal to null:\nassert.equal(\n  cleanChangelogs(`# Change Log\n\nAll notable changes to this project will be documented in this file.\nSee [Conventional Commits](https://conventionalcommits.org) for commit guidelines.\n\n## 2.9.2 (2018-12-27)\n\n**Note:** Version bump only for package ranges-apply\n\n## [2.9.1](https://gitlab.com/codsen/codsen/tree/master/packages/ranges-apply/compare/ranges-apply@2.9.0...ranges-apply@2.9.1) (2018-12-27)\n\n**Note:** Version bump only for package ranges-apply\n\n## 2.9.0 (2018-12-26)\n\n### Bug Fixes\n\n* aaa\n\n### Features\n\n* bbb\n\n`).res,\n  //\n  //\n  //\n  // output:\n  `# Change Log\n\nAll notable changes to this project will be documented in this file.\nSee [Conventional Commits](https://conventionalcommits.org) for commit guidelines.\n\n## 2.9.0 (2018-12-26)\n\n### Bug Fixes\n\n- aaa\n\n### Features\n\n- bbb\n`,\n);"},"fix-sourcehut-commit-links.js":{"title":"Fix SourceHut commit links","code":"import { strict as assert } from \"node:assert\";\n\nimport { cleanChangelogs } from \"lerna-clean-changelogs\";\n\nconst source = \"- Fixed in https://git.sr.ht/~user/project/commits/abc123\";\n\nassert.equal(\n  cleanChangelogs(source).res,\n  \"- Fixed in https://git.sr.ht/~user/project/commit/abc123\",\n);"},"preserve-crlf-line-endings.js":{"title":"Preserve CRLF line endings","code":"import { strict as assert } from \"node:assert\";\n\nimport { cleanChangelogs } from \"lerna-clean-changelogs\";\n\nconst result = cleanChangelogs(\"# Changelog\\r\\n\\r\\n* Fixed\\r\\n\").res;\n\nassert.equal(result, \"# Changelog\\r\\n\\r\\n- Fixed\\r\\n\");"},"remove-wip-with-extras.js":{"title":"Remove WIP entries and tidy the headings","code":"import { strict as assert } from \"node:assert\";\n\nimport { cleanChangelogs } from \"lerna-clean-changelogs\";\n\nconst source = `# Changelog\n\n## [2.0.0](https://example.com/compare/1.0.0...2.0.0)\n\n- Ready\n\n## 1.1.0\n\n- WIP: incomplete\n`;\nconst result = cleanChangelogs(source, { extras: true }).res;\n\nassert.equal(result.includes(\"## 2.0.0\"), true);\nassert.equal(result.includes(\"WIP\"), false);\nassert.equal(result.includes(\"## 1.1.0\"), false);"}},"object-all-values-equal-to":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { allEq } from \"object-all-values-equal-to\";\n\nassert.equal(allEq({ a: null, c: null }, null), true);"},"array-placeholders.js":{"title":"Arrays containing the placeholder itself","code":"import { strict as assert } from \"node:assert\";\n\nimport { allEq } from \"object-all-values-equal-to\";\n\n// By default, a placeholder directly inside an array makes the result false.\nassert.equal(allEq([false, false], false), false);\n\nassert.equal(\n  allEq([false, false], false, { arraysMustNotContainPlaceholders: false }),\n  true,\n);"},"empty-containers.js":{"title":"Empty containers","code":"import { strict as assert } from \"node:assert\";\n\nimport { allEq } from \"object-all-values-equal-to\";\n\nassert.equal(allEq({}, null), true);\nassert.equal(allEq([], null), true);"},"mismatched-value.js":{"title":"Return false when one value differs from the reference","code":"import { strict as assert } from \"node:assert\";\n\nimport { allEq } from \"object-all-values-equal-to\";\n\nassert.equal(allEq({ a: false, c: \"zzz\" }, false), false);"},"nested-values.js":{"title":"Check the values in nested objects and arrays","code":"import { strict as assert } from \"node:assert\";\n\nimport { allEq } from \"object-all-values-equal-to\";\n\nassert.equal(\n  allEq(\n    {\n      a: {\n        b: false,\n        c: [{ d: false, e: false }, { g: false }],\n      },\n      c: false,\n    },\n    false,\n  ),\n  true,\n);"}},"object-boolean-combinations":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { combinations } from \"object-boolean-combinations\";\n\nassert.deepEqual(\n  combinations({\n    a: true,\n    b: false,\n    c: true,\n  }),\n  [\n    { a: false, b: false, c: false },\n    { a: true, b: false, c: false },\n    { a: false, b: true, c: false },\n    { a: true, b: true, c: false },\n    { a: false, b: false, c: true },\n    { a: true, b: false, c: true },\n    { a: false, b: true, c: true },\n    { a: true, b: true, c: true },\n  ],\n);\n// you get 2^n plain objects in an array"},"empty-object.js":{"title":"Generate the one possible combination for an empty key set","code":"import { strict as assert } from \"node:assert\";\n\nimport { combinations } from \"object-boolean-combinations\";\n\nassert.deepEqual(combinations({}), [{}]);"},"fixed-overrides.js":{"title":"Hold selected keys constant while varying the others","code":"import { strict as assert } from \"node:assert\";\n\nimport { combinations } from \"object-boolean-combinations\";\n\nassert.deepEqual(\n  combinations(\n    { cache: false, compress: false, sourceMap: false },\n    { compress: true },\n  ),\n  [\n    { cache: false, sourceMap: false, compress: true },\n    { cache: true, sourceMap: false, compress: true },\n    { cache: false, sourceMap: true, compress: true },\n    { cache: true, sourceMap: true, compress: true },\n  ],\n);"},"shared-fixed-values.js":{"title":"Fixed nested values are shared between generated rows","code":"import { strict as assert } from \"node:assert\";\n\nimport { combinations } from \"object-boolean-combinations\";\n\nconst settings = { mode: \"safe\" };\nconst rows = combinations({ cache: false, settings: null }, { settings });\n\nassert.notEqual(rows[0].settings, settings);\nassert.equal(rows[0].settings, rows[1].settings);\n\nrows[0].settings.mode = \"strict\";\nassert.equal(rows[1].settings.mode, \"strict\");"}},"object-delete-key":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteKey } from \"object-delete-key\";\n\n// deleting key 'c', with value 'd'\nassert.deepEqual(\n  deleteKey(\n    {\n      a: \"b\",\n      c: \"d\",\n    },\n    {\n      key: \"c\",\n      val: \"d\",\n    },\n  ),\n  { a: \"b\" },\n);"},"by-key-only.js":{"title":"Deletion by the key only","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteKey } from \"object-delete-key\";\n\nassert.deepEqual(\n  deleteKey(\n    {\n      a: \"a\",\n      b: \"jlfghdjkhkdfhgdf\",\n      c: [{ b: \"weuhreorhelhgljdhflghd\" }],\n    },\n    {\n      key: \"b\",\n    },\n  ),\n  { a: \"a\" },\n);"},"by-value-only.js":{"title":"Deletion by the value only","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteKey } from \"object-delete-key\";\n\nassert.deepEqual(\n  deleteKey(\n    {\n      a: \"a\",\n      skldjfslfl: \"x\",\n      c: [{ dlfgjdlkjlfgjhfg: \"x\" }],\n    },\n    {\n      val: \"x\",\n    },\n  ),\n  { a: \"a\" },\n);"},"disable-cleanup.js":{"title":"Disable the cleanup which would otherwise happen after deletion","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteKey } from \"object-delete-key\";\n\nassert.deepEqual(\n  deleteKey(\n    {\n      a: { e: [{ b: { c: \"d\" } }] },\n      b: { c: \"d\" },\n    },\n    {\n      key: \"b\",\n      val: { c: \"d\" },\n      cleanup: false,\n    },\n  ),\n  { a: { e: [{}] } },\n);"},"key-and-value-must-match.js":{"title":"Delete only when both the key and value match","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteKey } from \"object-delete-key\";\n\nassert.deepEqual(\n  deleteKey(\n    {\n      a: \"remove\",\n      b: \"keep\",\n      nested: { a: \"keep\" },\n    },\n    {\n      key: \"a\",\n      val: \"remove\",\n    },\n  ),\n  {\n    b: \"keep\",\n    nested: { a: \"keep\" },\n  },\n);"},"only-object-keys.js":{"title":"Delete matching object keys without deleting matching array values","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteKey } from \"object-delete-key\";\n\nassert.deepEqual(\n  deleteKey(\n    {\n      a: \"a\",\n      b: \"keep\",\n      list: [\"a\"],\n    },\n    {\n      key: \"a\",\n      only: \"object\",\n    },\n  ),\n  {\n    b: \"keep\",\n    list: [\"a\"],\n  },\n);"},"wildcards.js":{"title":"Wildcards","code":"import { strict as assert } from \"node:assert\";\n\nimport { deleteKey } from \"object-delete-key\";\n\nassert.deepEqual(\n  deleteKey(\n    {\n      a: [\"beep\", \"\", \"c\", \"boop\"],\n      bap: \"bap\",\n    },\n    {\n      key: \"b*p\",\n      only: \"array\",\n    },\n  ),\n  {\n    a: [\"\", \"c\"],\n    bap: \"bap\",\n  },\n);"}},"object-fill-missing-keys":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { fillMissing } from \"object-fill-missing-keys\";\n\n// deleting key 'c', with value 'd'\nassert.deepEqual(\n  fillMissing(\n    {\n      // input object that could have came from JSON\n      b: \"b\",\n    },\n    {\n      // schema reference object\n      a: false,\n      b: false,\n      c: false,\n    },\n  ),\n  {\n    // patched result\n    a: false,\n    b: \"b\",\n    c: false,\n  },\n);"},"clone-schema-array.js":{"title":"Clone a schema array when the input array is empty","code":"import { strict as assert } from \"node:assert\";\n\nimport { fillMissing } from \"object-fill-missing-keys\";\n\nassert.deepEqual(\n  fillMissing({ sections: [] }, { sections: [{ title: \"\", body: \"\" }] }),\n  { sections: [{ title: \"\", body: \"\" }] },\n);"},"custom-placeholder.js":{"title":"Use true as the placeholder at paths that must remain unfilled","code":"import { strict as assert } from \"node:assert\";\n\nimport { fillMissing } from \"object-fill-missing-keys\";\n\nassert.deepEqual(\n  fillMissing(\n    { section: { settings: true } },\n    { section: { settings: { visible: false, featured: false } } },\n    {\n      placeholder: true,\n      doNotFillThesePathsIfTheyContainPlaceholders: [\"section.settings\"],\n    },\n  ),\n  { section: { settings: true } },\n);"},"do-not-fill.js":{"title":"An option to not fill the paths if they contain placeholders","code":"import { strict as assert } from \"node:assert\";\n\nimport { fillMissing } from \"object-fill-missing-keys\";\n\nassert.deepEqual(\n  fillMissing(\n    {\n      // input object\n      a: {\n        b: false, // <---- we don't want to automatically normalise this key\n        x: \"x\",\n      },\n      z: \"z\",\n    },\n    {\n      // reference schema object\n      a: {\n        b: {\n          c: false,\n          d: false,\n        },\n        x: false,\n      },\n      z: false,\n    },\n    {\n      doNotFillThesePathsIfTheyContainPlaceholders: [\"a.b\"],\n    },\n  ),\n  {\n    a: {\n      b: false, // <---\n      x: \"x\",\n    },\n    z: \"z\",\n  },\n);"},"fill-array-items.js":{"title":"Fill missing keys in every existing array item","code":"import { strict as assert } from \"node:assert\";\n\nimport { fillMissing } from \"object-fill-missing-keys\";\n\nassert.deepEqual(\n  fillMissing(\n    { people: [{ name: \"Ada\" }, { role: \"editor\" }] },\n    { people: [{ name: \"\", role: \"\" }] },\n  ),\n  {\n    people: [\n      { name: \"Ada\", role: \"\" },\n      { name: \"\", role: \"editor\" },\n    ],\n  },\n);"},"replace-null-values.js":{"title":"Fill null values when null is not an explicit opt-out","code":"import { strict as assert } from \"node:assert\";\n\nimport { fillMissing } from \"object-fill-missing-keys\";\n\nassert.deepEqual(\n  fillMissing({ a: null }, { a: [\"z\"] }, { useNullAsExplicitFalse: false }),\n  { a: [\"z\"] },\n);"},"truncation.js":{"title":"Truncation upon request, to minimize the object footprint","code":"import { strict as assert } from \"node:assert\";\n\nimport { fillMissing } from \"object-fill-missing-keys\";\n\nassert.deepEqual(\n  fillMissing(\n    {\n      // input object\n      a: {\n        b: {\n          // this object in \"b\"'s value will be removed and set to placeholder \"false\"\n          c: false,\n          d: false,\n        },\n        x: {\n          // this too\n          y: false,\n        },\n      },\n      z: \"z\",\n    },\n    {\n      // schema object\n      a: {\n        b: {\n          c: false,\n          d: false,\n        },\n        x: false,\n      },\n      z: false,\n    },\n    {\n      // settings\n      doNotFillThesePathsIfTheyContainPlaceholders: [\"lalala\", \"a.b\", \"a.x\"],\n    },\n  ),\n  {\n    // result\n    a: {\n      b: false,\n      x: false,\n    },\n    z: \"z\",\n  },\n);"},"useNullAsExplicitFalse.js":{"title":"`opts.useNullAsExplicitFalse`","code":"import { strict as assert } from \"node:assert\";\n\nimport { fillMissing } from \"object-fill-missing-keys\";\n\n// on\nassert.deepEqual(\n  fillMissing(\n    {\n      // object we're working on\n      a: null,\n    },\n    {\n      // reference schema\n      a: [\"z\"],\n    },\n    {\n      // options\n      useNullAsExplicitFalse: true, // <--- !\n    },\n  ),\n  {\n    // result\n    a: null,\n  },\n);"},"using-placeholder-true.js":{"title":"Using placeholder to cause the value population","code":"import { strict as assert } from \"node:assert\";\n\nimport { fillMissing } from \"object-fill-missing-keys\";\n\nassert.deepEqual(\n  fillMissing(\n    {\n      // object we work upon\n      a: {\n        b: true, // <-- not placeholder but lower in data hierarchy (boolean)\n        x: \"x\",\n      },\n      z: \"z\",\n    },\n    {\n      // reference (schema) object\n      a: {\n        b: {\n          c: false,\n          d: false,\n        },\n        x: false,\n      },\n      z: false,\n    },\n    {\n      doNotFillThesePathsIfTheyContainPlaceholders: [\"a.b\"],\n    },\n  ),\n  {\n    a: {\n      b: {\n        c: false, // <---- values added!\n        d: false, // <---- values added!\n      },\n      x: \"x\",\n    },\n    z: \"z\",\n  },\n);"}},"object-flatten-all-arrays":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenAllArrays } from \"object-flatten-all-arrays\";\n\nassert.deepEqual(\n  flattenAllArrays({\n    a: \"a\",\n    b: \"b\",\n    c: [\n      {\n        b: \"b\",\n        a: \"a\",\n      },\n      {\n        d: \"d\",\n        c: \"c\",\n      },\n    ],\n  }),\n  {\n    a: \"a\",\n    b: \"b\",\n    c: [\n      {\n        a: \"a\",\n        b: \"b\",\n        c: \"c\",\n        d: \"d\",\n      },\n    ],\n  },\n);"},"empty-arrays-containing-strings.js":{"title":"Empty arrays that contain any string value","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenAllArrays } from \"object-flatten-all-arrays\";\n\nassert.deepEqual(\n  flattenAllArrays(\n    {\n      keep: [{ a: \"a\" }, { b: \"b\" }],\n      remove: [{ a: \"a\" }, \"text\", { b: \"b\" }],\n    },\n    { flattenArraysContainingStringsToBeEmpty: true },\n  ),\n  {\n    keep: [{ a: \"a\", b: \"b\" }],\n    remove: [],\n  },\n);"},"nested-arrays.js":{"title":"Merge objects in arrays at every nesting level","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenAllArrays } from \"object-flatten-all-arrays\";\n\nassert.deepEqual(\n  flattenAllArrays({\n    groups: [\n      [{ a: 1 }, { b: 2 }],\n      [{ c: 3 }, { d: 4 }],\n    ],\n  }),\n  { groups: [[{ a: 1, b: 2 }], [{ c: 3, d: 4 }]] },\n);"},"preserve-input.js":{"title":"Return a flattened clone without changing the input","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenAllArrays } from \"object-flatten-all-arrays\";\n\nconst input = { items: [{ a: 1 }, { b: 2 }] };\n\nflattenAllArrays(input);\n\nassert.deepEqual(input, { items: [{ a: 1 }, { b: 2 }] });"}},"object-flatten-referencing":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenReferencing(\n    {\n      key1: \"val11.val12\",\n      key2: \"val21.val22\",\n    },\n    {\n      key1: \"Contact us\",\n      key2: \"Tel. 0123456789\",\n    },\n  ),\n  {\n    key1: \"%%_val11.val12_%%\",\n    key2: \"%%_val21.val22_%%\",\n  },\n);"},"allow-double-wrapping.js":{"title":"Wrap an already wrapped value when prevention is disabled","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenReferencing(\n    { title: \"%%_Example_%%\" },\n    { title: \"Reference\" },\n    { preventDoubleWrapping: false },\n  ),\n  { title: \"%%_%%_Example_%%_%%\" },\n);"},"allow-duplicate-line-break.js":{"title":"Insert a break even when the previous line already contains one","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenArr } from \"object-flatten-referencing\";\n\nassert.equal(\n  flattenArr(\n    [\"one<br />\", \"two\"],\n    { mergeWithoutTrailingBrIfLineContainsBr: false },\n    false,\n    true,\n  ),\n  \"one<br /><br />two\",\n);"},"arrayiffy.js":{"title":"Normalise a string setting to an array","code":"import { strict as assert } from \"node:assert\";\n\nimport { arrayiffy } from \"object-flatten-referencing\";\n\nassert.deepEqual(arrayiffy(\"title\"), [\"title\"]);"},"avoid-duplicate-line-break.js":{"title":"Avoid adding a break after a line that already ends with one","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenArr } from \"object-flatten-referencing\";\n\nassert.equal(\n  flattenArr(\n    [\"one<br />\", \"two\"],\n    { mergeWithoutTrailingBrIfLineContainsBr: true },\n    false,\n    true,\n  ),\n  \"one<br />two\",\n);"},"custom-wrappers.js":{"title":"Wrap flattened string values with custom markers","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenReferencing(\n    { title: \"Example\" },\n    { title: \"Reference\" },\n    { wrapHeadsWith: \"{{ \", wrapTailsWith: \" }}\" },\n  ),\n  { title: \"{{ Example }}\" },\n);"},"default-options.js":{"title":"Inspect the exported flattening defaults","code":"import { strict as assert } from \"node:assert\";\n\nimport { defaults } from \"object-flatten-referencing\";\n\nassert.equal(defaults.wrapHeadsWith, \"%%_\");\nassert.equal(defaults.wrapTailsWith, \"_%%\");\nassert.equal(defaults.xhtml, true);\nassert.equal(defaults.enforceStrictKeyset, true);"},"disable-wrapping.js":{"title":"Disable wrapping across the complete input tree","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenReferencing(\n    { title: \"Example\" },\n    { title: \"Reference\" },\n    { wrapGlobalFlipSwitch: false },\n  ),\n  { title: \"Example\" },\n);"},"dont-wrap-keys.js":{"title":"Skip wrapping for keys that match a glob","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenReferencing(\n    { title: \"Example\", rawSlug: \"example\" },\n    { title: \"Reference\", rawSlug: \"reference\" },\n    { dontWrapKeys: [\"raw*\"] },\n  ),\n  { title: \"%%_Example_%%\", rawSlug: \"example\" },\n);"},"dont-wrap-paths.js":{"title":"Skip wrapping only at an exact nested path","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenReferencing(\n    { header: { title: \"One\" }, footer: { title: \"Two\" } },\n    { header: { title: \"\" }, footer: { title: \"\" } },\n    { dontWrapPaths: [\"header.title\"] },\n  ),\n  {\n    header: { title: \"One\" },\n    footer: { title: \"%%_Two_%%\" },\n  },\n);"},"flatten-array.js":{"title":"Flatten an array with line breaks between rows","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenArr } from \"object-flatten-referencing\";\n\nassert.equal(flattenArr([\"one\", \"two\"], {}, false, true), \"one<br />two\");"},"flatten-object.js":{"title":"Flatten an object's keys and values to strings","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenObject } from \"object-flatten-referencing\";\n\nassert.deepEqual(flattenObject({ name: \"Ada\", roles: [\"author\", \"editor\"] }), [\n  \"name.Ada\",\n  \"roles.author\",\n  \"roles.editor\",\n]);"},"html-line-breaks.js":{"title":"Use HTML rather than XHTML line-break syntax","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenReferencing(\n    { lines: [\"one\", \"two\"] },\n    { lines: \"Reference\" },\n    { xhtml: false },\n  ),\n  { lines: \"%%_one_%%<br>%%_two_%%\" },\n);"},"ignore-key.js":{"title":"Leave an ignored key and its nested value unchanged","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenReferencing(\n    { raw: [\"one\", \"two\"], title: \"Example\" },\n    { raw: \"Reference\", title: \"Reference\" },\n    { ignore: [\"raw\"] },\n  ),\n  { raw: [\"one\", \"two\"], title: \"%%_Example_%%\" },\n);"},"merge-arrays-without-breaks.js":{"title":"Merge array rows without inserting line breaks","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenArr } from \"object-flatten-referencing\";\n\nassert.equal(\n  flattenArr([\"one\", \"two\"], { mergeArraysWithLineBreaks: false }, false, true),\n  \"onetwo\",\n);"},"missing-reference-flatten.js":{"title":"Flatten input keys even when the reference has no matching key","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenReferencing(\n    { title: \"Example\", extra: [\"one\", \"two\"] },\n    { title: \"Reference\" },\n    { whatToDoWhenReferenceIsMissing: 2 },\n  ),\n  { title: \"%%_Example_%%\", extra: \"%%_one_%%<br />%%_two_%%\" },\n);"},"missing-reference-leave.js":{"title":"Leave an unmatched input key unchanged","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenReferencing(\n    { title: \"Example\", extra: [\"one\", \"two\"] },\n    { title: \"Reference\" },\n    { whatToDoWhenReferenceIsMissing: 0 },\n  ),\n  { title: \"%%_Example_%%\", extra: [\"one\", \"two\"] },\n);"},"missing-reference-throw.js":{"title":"Throw when an input key is absent from the reference","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.throws(\n  () =>\n    flattenReferencing(\n      { title: \"Example\", extra: \"unexpected\" },\n      { title: \"Reference\" },\n      { whatToDoWhenReferenceIsMissing: 1 },\n    ),\n  /THROW_ID_04/u,\n);"},"object-key-value-separator.js":{"title":"Set the separator used by flattenObject","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenObject } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenObject(\n    { name: \"Ada\", roles: [\"author\", \"editor\"] },\n    { objectKeyAndValueJoinChar: \":\" },\n  ),\n  [\"name:Ada\", \"roles:author\", \"roles:editor\"],\n);"},"prevent-double-wrapping.js":{"title":"Keep values that already contain the wrapping markers","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenReferencing(\n    { title: \"%%_Example_%%\" },\n    { title: \"Reference\" },\n    { preventDoubleWrapping: true },\n  ),\n  { title: \"%%_Example_%%\" },\n);"},"prevent-wrapping-if-contains.js":{"title":"Leave templating statements unwrapped","code":"import { strict as assert } from \"node:assert\";\n\nimport { flattenReferencing } from \"object-flatten-referencing\";\n\nassert.deepEqual(\n  flattenReferencing(\n    { statement: \"{% if enabled %}\" },\n    { statement: \"Reference\" },\n    {\n      wrapHeadsWith: \"{{ \",\n      wrapTailsWith: \" }}\",\n      preventWrappingIfContains: [\"{%\"],\n    },\n  ),\n  { statement: \"{% if enabled %}\" },\n);"}},"object-merge-advanced":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced(\n    {\n      a: [\"c\"],\n      m: \"n\",\n    },\n    {\n      a: \"b\",\n      k: \"l\",\n    },\n    {\n      ignoreKeys: [\"a\"],\n    },\n  ),\n  {\n    a: [\"c\"],\n    k: \"l\",\n    m: \"n\",\n  },\n);"},"callback.js":{"title":"Override a merge result in the callback","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced(\n    { label: \"old\" },\n    { label: \"new\" },\n    {\n      cb: (left, right, result, info) =>\n        info.key === \"label\" ? `${left}/${right}` : result,\n    },\n  ),\n  { label: \"old/new\" },\n);"},"dedupe-string-arrays.js":{"title":"Deduplicate and sort merged string arrays","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced([\"b\", \"a\"], [\"b\", \"c\"], {\n    dedupeStringsInArrayValues: true,\n  }),\n  [\"a\", \"b\", \"c\"],\n);"},"empty-string-arrays.js":{"title":"Clear an array merge when either array contains strings","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced(\n    { tags: [\"stable\"] },\n    { tags: [\"esm\"] },\n    { mergeArraysContainingStringsToBeEmpty: true },\n  ),\n  { tags: [] },\n);"},"hard-array-concat.js":{"title":"Concatenate every clashing pair of arrays","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced([1, 2], [2, 3], { hardArrayConcat: true }),\n  [1, 2, 2, 3],\n);"},"hard-concat-array-key.js":{"title":"Concatenate arrays on a selected key","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced(\n    { tags: [\"stable\"] },\n    { tags: [\"stable\", \"esm\"] },\n    { hardArrayConcatKeys: [\"tags\"] },\n  ),\n  { tags: [\"stable\", \"stable\", \"esm\"] },\n);"},"hard-merge-everything.js":{"title":"Prefer incoming values for every clash","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced(\n    { list: [\"old\"], retained: true },\n    { list: [\"new\"], added: true },\n    { hardMergeEverything: true },\n  ),\n  { list: [\"new\"], retained: true, added: true },\n);"},"hard-merge-key.js":{"title":"Take the incoming value for a selected clashing key","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced(\n    { selected: [\"old\"], combined: [\"left\"] },\n    { selected: [\"new\"], combined: [\"right\"] },\n    { hardMergeKeys: [\"selected\"] },\n  ),\n  { selected: [\"new\"], combined: [\"left\", \"right\"] },\n);"},"ignore-everything.js":{"title":"Keep existing values for every clash","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced(\n    { list: [\"old\"], retained: true },\n    { list: [\"new\"], added: true },\n    { ignoreEverything: true },\n  ),\n  { list: [\"old\"], retained: true, added: true },\n);"},"merge-array-values.js":{"title":"Merge array values and omit duplicates instead of concatenating positions","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced([\"a\", \"b\"], [\"b\", \"c\"], {\n    concatInsteadOfMerging: false,\n  }),\n  [\"a\", \"b\", \"c\"],\n);"},"merge-booleans-with-and.js":{"title":"Merge Boolean clashes with AND instead of the default OR","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced(\n    { enabled: true },\n    { enabled: false },\n    { mergeBoolsUsingOrNotAnd: false },\n  ),\n  { enabled: false },\n);"},"merge-object-array-items-with-different-keys.js":{"title":"Merge positioned array objects even when their key sets differ","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced([{ name: \"Ada\" }], [{ role: \"author\" }], {\n    mergeObjectsOnlyWhenKeysetMatches: false,\n  }),\n  [{ name: \"Ada\", role: \"author\" }],\n);"},"null-as-explicit-false.js":{"title":"Let null explicitly override another value","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced(\n    { enabled: true },\n    { enabled: null },\n    { useNullAsExplicitFalse: true },\n  ),\n  { enabled: null },\n);"},"one-to-many-array-object-merge.js":{"title":"Apply one array object to every object in the other array","code":"import { strict as assert } from \"node:assert\";\n\nimport { mergeAdvanced } from \"object-merge-advanced\";\n\nassert.deepEqual(\n  mergeAdvanced([{ published: true }], [{ id: 1 }, { id: 2 }], {\n    oneToManyArrayObjectMerge: true,\n  }),\n  [\n    { published: true, id: 1 },\n    { published: true, id: 2 },\n  ],\n);"}},"object-no-new-keys":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { noNewKeys } from \"object-no-new-keys\";\n\nassert.deepEqual(\n  noNewKeys(\n    {\n      a: {\n        b: \"b\",\n        c: \"c\",\n      },\n      x: \"y\",\n    },\n    {\n      a: {\n        c: \"z\",\n      },\n    },\n  ),\n  [\"a.b\", \"x\"],\n);"},"compare-array-items-by-position.js":{"title":"Compare each input array item with the reference item at the same index","code":"import { strict as assert } from \"node:assert\";\n\nimport { noNewKeys } from \"object-no-new-keys\";\n\nassert.deepEqual(\n  noNewKeys(\n    {\n      rows: [{ name: \"Ada\" }, { name: \"Grace\", role: \"editor\" }],\n    },\n    {\n      rows: [{ name: \"\" }],\n    },\n    { mode: 1 },\n  ),\n  [\"rows[1].name\", \"rows[1].role\"],\n);"},"compare-array-items-with-first-schema.js":{"title":"Compare every input array item with the first reference item","code":"import { strict as assert } from \"node:assert\";\n\nimport { noNewKeys } from \"object-no-new-keys\";\n\nassert.deepEqual(\n  noNewKeys(\n    {\n      rows: [{ name: \"Ada\" }, { name: \"Grace\", role: \"editor\" }],\n    },\n    {\n      rows: [{ name: \"\" }],\n    },\n    { mode: 2 },\n  ),\n  [\"rows[1].role\"],\n);"},"report-container-mismatch.js":{"title":"Report each array position when the reference is not an array","code":"import { strict as assert } from \"node:assert\";\n\nimport { noNewKeys } from \"object-no-new-keys\";\n\nassert.deepEqual(noNewKeys({ rows: [\"one\", \"two\"] }, { rows: \"\" }), [\n  \"rows[0]\",\n  \"rows[1]\",\n]);"}},"object-set-all-values-to":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { setAllValuesTo } from \"object-set-all-values-to\";\n\nassert.deepEqual(\n  setAllValuesTo({\n    a: \"a\",\n    b: \"b\",\n    c: \"c\",\n    d: \"d\",\n  }),\n  {\n    a: false,\n    b: false,\n    c: false,\n    d: false,\n  },\n);"},"array-primitives-stay-unchanged.js":{"title":"Array primitives stay unchanged","code":"import { strict as assert } from \"node:assert\";\n\nimport { setAllValuesTo } from \"object-set-all-values-to\";\n\nassert.deepEqual(setAllValuesTo([\"keep\", { change: \"me\" }, 42]), [\n  \"keep\",\n  { change: false },\n  42,\n]);"},"custom-replacement.js":{"title":"Set every value to a custom replacement","code":"import { strict as assert } from \"node:assert\";\n\nimport { setAllValuesTo } from \"object-set-all-values-to\";\n\nassert.deepEqual(setAllValuesTo({ a: \"a\", b: \"b\", c: \"c\", d: \"d\" }, \"x\"), {\n  a: \"x\",\n  b: \"x\",\n  c: \"x\",\n  d: \"x\",\n});"},"explicit-undefined-replacement.js":{"title":"Set every value to `undefined`","code":"import { strict as assert } from \"node:assert\";\n\nimport { setAllValuesTo } from \"object-set-all-values-to\";\n\nconst result = setAllValuesTo({ left: 1, right: 2 }, undefined);\n\nassert.equal(Object.hasOwn(result, \"left\"), true);\nassert.equal(result.left, undefined);\nassert.equal(result.right, undefined);"},"nested-objects-and-arrays.js":{"title":"Set the values within nested objects and arrays","code":"import { strict as assert } from \"node:assert\";\n\nimport { setAllValuesTo } from \"object-set-all-values-to\";\n\nassert.deepEqual(\n  setAllValuesTo({ user: { name: \"Ada\", roles: [{ name: \"admin\" }] } }, null),\n  { user: { name: null, roles: [{ name: null }] } },\n);"},"replacement-containers-are-independent.js":{"title":"Each replacement container is a separate object","code":"import { strict as assert } from \"node:assert\";\n\nimport { setAllValuesTo } from \"object-set-all-values-to\";\n\nconst result = setAllValuesTo(\n  { first: { value: 1 }, second: { value: 2 } },\n  { selected: false },\n);\n\nresult.first.value.selected = true;\n\nassert.equal(result.first.value.selected, true);\nassert.equal(result.second.value.selected, false);"}},"ranges-apply":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { rApply } from \"ranges-apply\";\n\nconst oldString = \"The quick brown fox jumps over the lazy dog.\";\nconst ranges = [\n  [4, 19, \"bad grey wolf\"],\n  [35, 43, \"little Red Riding Hood\"],\n];\nassert.equal(\n  rApply(oldString, ranges),\n  \"The bad grey wolf jumps over the little Red Riding Hood.\",\n);"},"delete-range.js":{"title":"Delete a range by omitting its replacement value","code":"import { strict as assert } from \"node:assert\";\n\nimport { rApply } from \"ranges-apply\";\n\nassert.equal(rApply(\"abcdef\", [1, 3]), \"adef\");"},"insert-at-index.js":{"title":"Insert text with a zero-width range","code":"import { strict as assert } from \"node:assert\";\n\nimport { rApply } from \"ranges-apply\";\n\nassert.equal(rApply(\"abcdef\", [3, 3, \"-\"]), \"abc-def\");"},"numeric-replacements.js":{"title":"Apply and merge numeric replacement values","code":"import { strict as assert } from \"node:assert\";\n\nimport { rApply } from \"ranges-apply\";\n\nassert.equal(rApply(\"abc\", [0, 0, 0]), \"0abc\");\nassert.equal(\n  rApply(\"abcdef\", [\n    [1, 3, 1],\n    [2, 4, 2],\n  ]),\n  \"a3ef\",\n);"},"numeric-string-indexes.js":{"title":"Apply ranges whose indexes arrive as numeric strings","code":"import { strict as assert } from \"node:assert\";\n\nimport { rApply } from \"ranges-apply\";\n\nassert.equal(rApply(\"abcdef\", [[\"1\", \"3\", \"X\"]]), \"aXdef\");"},"progress-callback.js":{"title":"Gather progress while applying multiple ranges","code":"import { strict as assert } from \"node:assert\";\n\nimport { rApply } from \"ranges-apply\";\n\nconst percentages = [];\nconst result = rApply(\n  \"abcdef\",\n  [\n    [1, 2, \"X\"],\n    [4, 5, \"Y\"],\n  ],\n  (percentage) => percentages.push(percentage),\n);\n\nassert.equal(result, \"aXcdYf\");\nassert.deepEqual(percentages, [5, 10, 12, 19, 20, 60, 100]);"}},"ranges-crop":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { rCrop } from \"ranges-crop\";\n\nassert.deepEqual(\n  rCrop(\n    [\n      [2, 3],\n      [9, 10, \"bad grey wolf\"],\n      [1, 2],\n    ],\n    7,\n  ),\n  [[1, 3]], // sorted, merged and cropped\n);"},"crop-a-range-with-replacement.js":{"title":"Crop a range that carries a replacement","code":"import { strict as assert } from \"node:assert\";\n\nimport { rCrop } from \"ranges-crop\";\n\nassert.deepEqual(rCrop([[5, 12, \"replacement\"]], 8), [[5, 8, \"replacement\"]]);"},"discard-ranges-beyond-string.js":{"title":"Discard the ranges beyond the string's end","code":"import { strict as assert } from \"node:assert\";\n\nimport { rCrop } from \"ranges-crop\";\n\nassert.deepEqual(\n  rCrop(\n    [\n      [1, 3],\n      [7, 9],\n    ],\n    5,\n  ),\n  [[1, 3]],\n);"},"insertion-at-string-end.js":{"title":"Keep an insertion at the string's end","code":"import { strict as assert } from \"node:assert\";\n\nimport { rCrop } from \"ranges-crop\";\n\nassert.deepEqual(rCrop([[5, 9, \"!\"]], 5), [[5, 5, \"!\"]]);"},"merge-and-sort-before-cropping.js":{"title":"Merge and sort the ranges before cropping","code":"import { strict as assert } from \"node:assert\";\n\nimport { rCrop } from \"ranges-crop\";\n\nassert.deepEqual(\n  rCrop(\n    [\n      [5, 10],\n      [1, 3],\n      [2, 6],\n    ],\n    8,\n  ),\n  [[1, 8]],\n);"},"no-ranges.js":{"title":"No ranges to crop","code":"import { strict as assert } from \"node:assert\";\n\nimport { rCrop } from \"ranges-crop\";\n\nassert.equal(rCrop(null, 10), null);\nassert.deepEqual(rCrop([], 10), []);"}},"ranges-ent-decode":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { rEntDecode } from \"ranges-ent-decode\";\n\n// see codsen.com/ranges/\nassert.deepEqual(rEntDecode(\"a &#x26; b &amp; c\"), [\n  [2, 8, \"&\"], // <--- that's Ranges notation, instructing to replace\n  [11, 16, \"&\"],\n]);"},"attribute-value-context.js":{"title":"Avoid decoding an ambiguous entity inside an attribute value","code":"import { strict as assert } from \"node:assert\";\n\nimport { rEntDecode } from \"ranges-ent-decode\";\n\nassert.equal(rEntDecode(\"foo&ampbar\", { isAttributeValue: true }), null);\nassert.deepEqual(rEntDecode(\"foo&amp;bar\", { isAttributeValue: true }), [\n  [3, 8, \"&\"],\n]);"},"no-entities.js":{"title":"Return null when no replacement ranges are needed","code":"import { strict as assert } from \"node:assert\";\n\nimport { rEntDecode } from \"ranges-ent-decode\";\n\nassert.equal(rEntDecode(\"plain text\"), null);\nassert.equal(rEntDecode(\"\"), null);"},"numeric-entities.js":{"title":"Decode decimal and hexadecimal character references","code":"import { strict as assert } from \"node:assert\";\n\nimport { rEntDecode } from \"ranges-ent-decode\";\n\nassert.deepEqual(rEntDecode(\"A: &#65;, B: &#x42;\"), [\n  [3, 8, \"A\"],\n  [13, 19, \"B\"],\n]);"},"recursively-encoded-entities.js":{"title":"Decode entities that were encoded more than once","code":"import { strict as assert } from \"node:assert\";\n\nimport { rEntDecode } from \"ranges-ent-decode\";\n\nassert.deepEqual(rEntDecode(\"a &amp;amp;pound; b\"), [[2, 17, \"£\"]]);"},"strict-mode.js":{"title":"Reject a malformed entity in strict mode","code":"import { strict as assert } from \"node:assert\";\n\nimport { rEntDecode } from \"ranges-ent-decode\";\n\nassert.throws(() => rEntDecode(\"foo&ampbar\", { strict: true }), /Parse error/u);"}},"ranges-invert":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { rInvert } from \"ranges-invert\";\n\nassert.deepEqual(\n  rInvert(\n    [\n      [3, 5],\n      [5, 7],\n    ],\n    9, // string length needed to set the boundary\n  ),\n  [\n    [0, 3],\n    [7, 9],\n  ],\n);"},"merge-before-inverting.js":{"title":"Merge overlapping ranges before inverting","code":"import { strict as assert } from \"node:assert\";\n\nimport { rInvert } from \"ranges-invert\";\n\nassert.deepEqual(\n  rInvert(\n    [\n      [4, 8],\n      [1, 5],\n    ],\n    10,\n  ),\n  [\n    [0, 1],\n    [8, 10],\n  ],\n);"},"no-ranges.js":{"title":"Invert an absent ranges collection","code":"import { strict as assert } from \"node:assert\";\n\nimport { rInvert } from \"ranges-invert\";\n\nassert.deepEqual(rInvert(null, 5), [[0, 5]]);\nassert.equal(rInvert(null, 0), null);"},"prevalidated-ranges.js":{"title":"Skip validation for already sorted ranges","code":"import { strict as assert } from \"node:assert\";\n\nimport { rInvert } from \"ranges-invert\";\n\nassert.deepEqual(\n  rInvert(\n    [\n      [1, 3],\n      [5, 7],\n    ],\n    8,\n    { skipChecks: true },\n  ),\n  [\n    [0, 1],\n    [3, 5],\n    [7, 8],\n  ],\n);"},"strict-range-shape.js":{"title":"Require two-element ranges","code":"import { strict as assert } from \"node:assert\";\n\nimport { rInvert } from \"ranges-invert\";\n\nassert.throws(\n  () =>\n    rInvert([[1, 3, \"replacement\"]], 5, {\n      strictlyTwoElementsInRangeArrays: true,\n    }),\n  /THROW_ID_04/,\n);"}},"ranges-is-index-within":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { isIndexWithin } from \"ranges-is-index-within\";\n\nassert.equal(\n  isIndexWithin(8, [\n    [1, 2],\n    [5, 10],\n  ]),\n  true,\n);"},"inclusive-range-ends.js":{"title":"Include both range endpoints in the match","code":"import { strict as assert } from \"node:assert\";\n\nimport { isIndexWithin } from \"ranges-is-index-within\";\n\nassert.equal(isIndexWithin(5, [[5, 10]], { inclusiveRangeEnds: true }), true);"},"outside-ranges.js":{"title":"Return false when an index is outside every range","code":"import { strict as assert } from \"node:assert\";\n\nimport { isIndexWithin } from \"ranges-is-index-within\";\n\nassert.equal(\n  isIndexWithin(12, [\n    [1, 2],\n    [5, 10],\n  ]),\n  false,\n);"},"return-matched-range.js":{"title":"Return the matched range instead of true","code":"import { strict as assert } from \"node:assert\";\n\nimport { isIndexWithin } from \"ranges-is-index-within\";\n\nassert.deepEqual(\n  isIndexWithin(\n    8,\n    [\n      [1, 3],\n      [5, 10],\n    ],\n    { returnMatchedRangeInsteadOfTrue: true },\n  ),\n  [5, 10],\n);"}},"ranges-iterate":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { rIterate } from \"ranges-iterate\";\n\n// Ranges in the following example \"punches out\" a \"hole\" from `a` to `g`\n// (included), replacing it with `xyz`. That's what gets iterated.\n\nconst gathered = [];\n\n// a callback-based interface:\nrIterate(\"abcdefghij\", [[0, 7, \"xyz\"]], ({ i, val }) => {\n  gathered.push(`i = ${i}; val = ${val}`);\n});\n\nassert.deepEqual(gathered, [\n  \"i = 0; val = x\",\n  \"i = 1; val = y\",\n  \"i = 2; val = z\",\n  \"i = 3; val = h\",\n  \"i = 4; val = i\",\n  \"i = 5; val = j\",\n]);"},"deleted-range.js":{"title":"Skip characters covered by a deletion range","code":"import { strict as assert } from \"node:assert\";\n\nimport { rIterate } from \"ranges-iterate\";\n\nconst visited = [];\nrIterate(\"abcdef\", [[1, 3]], (entry) => visited.push(entry));\n\nassert.deepEqual(visited, [\n  { i: 0, val: \"a\" },\n  { i: 1, val: \"d\" },\n  { i: 2, val: \"e\" },\n  { i: 3, val: \"f\" },\n]);"},"insert-at-end.js":{"title":"Iterate text inserted at the end of a string","code":"import { strict as assert } from \"node:assert\";\n\nimport { rIterate } from \"ranges-iterate\";\n\nconst characters = [];\nrIterate(\"abc\", [[3, 3, \"!\"]], ({ val }) => characters.push(val));\n\nassert.equal(characters.join(\"\"), \"abc!\");"},"multiple-ranges.js":{"title":"Iterate the result of multiple replacements","code":"import { strict as assert } from \"node:assert\";\n\nimport { rIterate } from \"ranges-iterate\";\n\nconst characters = [];\nrIterate(\n  \"abcdef\",\n  [\n    [1, 2, \"X\"],\n    [4, 5, \"Y\"],\n  ],\n  ({ val }) => characters.push(val),\n);\n\nassert.equal(characters.join(\"\"), \"aXcdYf\");"},"no-ranges.js":{"title":"Iterate the original string when there are no ranges","code":"import { strict as assert } from \"node:assert\";\n\nimport { rIterate } from \"ranges-iterate\";\n\nconst characters = [];\nrIterate(\"abc\", [], ({ val }) => characters.push(val));\n\nassert.equal(characters.join(\"\"), \"abc\");"},"offset.js":{"title":"Start iteration at an existing output offset","code":"import { strict as assert } from \"node:assert\";\n\nimport { rIterate } from \"ranges-iterate\";\n\nconst visited = [];\nrIterate(\"abcdef\", [[3, 4, \"X\"]], (entry) => visited.push(entry), 2);\n\nassert.deepEqual(visited, [\n  { i: 2, val: \"c\" },\n  { i: 3, val: \"X\" },\n  { i: 4, val: \"e\" },\n  { i: 5, val: \"f\" },\n]);"}},"ranges-merge":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { rMerge } from \"ranges-merge\";\n\n// joining edges:\nassert.deepEqual(\n  rMerge([\n    [1, 2],\n    [2, 3],\n    [9, 10],\n  ]),\n  [\n    [1, 3],\n    [9, 10],\n  ],\n);"},"keep-touching-ranges-separate.js":{"title":"Keep the touching ranges separate","code":"import { strict as assert } from \"node:assert\";\n\nimport { rMerge } from \"ranges-merge\";\n\nassert.deepEqual(\n  rMerge(\n    [\n      [1, 3, \"a\"],\n      [3, 6, \"b\"],\n    ],\n    { joinRangesThatTouchEdges: false },\n  ),\n  [\n    [1, 3, \"a\"],\n    [3, 6, \"b\"],\n  ],\n);"},"merge-overlap.js":{"title":"Merge two overlapping ranges","code":"import { strict as assert } from \"node:assert\";\n\nimport { rMerge } from \"ranges-merge\";\n\nassert.deepEqual(\n  rMerge([\n    [1, 5],\n    [2, 10],\n  ]),\n  [[1, 10]],\n);"},"merge-type-two-prefers-latter-value.js":{"title":"Prefer the latter value with merge type two","code":"import { strict as assert } from \"node:assert\";\n\nimport { rMerge } from \"ranges-merge\";\n\nassert.deepEqual(\n  rMerge(\n    [\n      [3, 4, \"short\"],\n      [3, 12, \"long\"],\n    ],\n    { mergeType: 2 },\n  ),\n  [[3, 12, \"long\"]],\n);"},"null-replacement-wins.js":{"title":"A `null` replacement wins over text","code":"import { strict as assert } from \"node:assert\";\n\nimport { rMerge } from \"ranges-merge\";\n\nassert.deepEqual(\n  rMerge([\n    [1, 4, null],\n    [3, 8, \"text\"],\n  ]),\n  [[1, 8, null]],\n);"},"remove-futile-ranges.js":{"title":"Remove the ranges that do nothing","code":"import { strict as assert } from \"node:assert\";\n\nimport { rMerge } from \"ranges-merge\";\n\nassert.deepEqual(\n  rMerge([\n    [1, 1],\n    [2, 2, \"insert\"],\n    [3, 5],\n  ]),\n  [\n    [2, 2, \"insert\"],\n    [3, 5],\n  ],\n);"},"report-progress.js":{"title":"Report the merging progress","code":"import { strict as assert } from \"node:assert\";\n\nimport { rMerge } from \"ranges-merge\";\n\nconst percentages = [];\nconst result = rMerge(\n  [\n    [1, 4],\n    [3, 8],\n    [10, 12],\n    [11, 15],\n  ],\n  { progressFn: (percentage) => percentages.push(percentage) },\n);\n\nassert.deepEqual(result, [\n  [1, 8],\n  [10, 15],\n]);\nassert.equal(percentages.length > 0, true);\nassert.equal(percentages.every(Number.isInteger), true);"}},"ranges-process-outside":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { rProcessOutside } from \"ranges-process-outside\";\n\nconst gathered = [];\n\n// a callback interface:\nrProcessOutside(\n  \"abcdefghij\",\n  [\n    [1, 5], // delete from \"b\" to \"f\"\n  ],\n  (fromIdx, toIdx, offsetValueCb) => {\n    gathered.push(fromIdx);\n  },\n);\n\nassert.deepEqual(gathered, [0, 5, 6, 7, 8, 9]);"},"no-ranges.js":{"title":"Process the whole string when no ranges are supplied","code":"import { strict as assert } from \"node:assert\";\n\nimport { rProcessOutside } from \"ranges-process-outside\";\n\nconst gathered = [];\nrProcessOutside(\"abc\", null, (from, to) => gathered.push([from, to]));\n\nassert.deepEqual(gathered, [\n  [0, 1],\n  [1, 2],\n  [2, 3],\n]);"},"prevalidated-ranges.js":{"title":"Skip range validation in a prevalidated pipeline","code":"import { strict as assert } from \"node:assert\";\n\nimport { rProcessOutside } from \"ranges-process-outside\";\n\nconst indexes = [];\nrProcessOutside(\"abcdef\", [[1, 3]], (from) => indexes.push(from), true);\n\nassert.deepEqual(indexes, [0, 3, 4, 5]);"},"skip-ahead.js":{"title":"Skip ahead from inside the callback","code":"import { strict as assert } from \"node:assert\";\n\nimport { rProcessOutside } from \"ranges-process-outside\";\n\nconst gathered = [];\nrProcessOutside(\"abcdef\", null, (from, to, offset) => {\n  gathered.push([from, to]);\n  if (from === 0) offset(2);\n});\n\nassert.deepEqual(gathered, [\n  [0, 1],\n  [3, 4],\n  [4, 5],\n  [5, 6],\n]);"},"unicode-code-points.js":{"title":"Process Unicode code points without splitting surrogate pairs","code":"import { strict as assert } from \"node:assert\";\n\nimport { rProcessOutside } from \"ranges-process-outside\";\n\nconst gathered = [];\nrProcessOutside(\"a😀b\", null, (from, to) => gathered.push([from, to]));\n\nassert.deepEqual(gathered, [\n  [0, 1],\n  [1, 3],\n  [3, 4],\n]);"}},"ranges-push":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\nimport { rApply } from \"ranges-apply\";\nimport { Ranges } from \"ranges-push\";\n\nconst gatheredRanges = new Ranges();\n\nconst oldString = \"The quick brown fox jumps over the lazy dog.\";\n\n// push the ranges\ngatheredRanges.push(35, 43, \"little Red Riding Hood\");\ngatheredRanges.push(4, 19, \"bad grey wolf\");\n\n// retrieve the merged and sorted ranges by calling .current()\nassert.deepEqual(gatheredRanges.current(), [\n  [4, 19, \"bad grey wolf\"],\n  [35, 43, \"little Red Riding Hood\"],\n]);\n\nassert.equal(\n  rApply(oldString, gatheredRanges.current()),\n  \"The bad grey wolf jumps over the little Red Riding Hood.\",\n);"},"add-ranges-array.js":{"title":"Add a complete array of ranges in one call","code":"import { strict as assert } from \"node:assert\";\n\nimport { Ranges } from \"ranges-push\";\n\nconst ranges = new Ranges();\nranges.add([\n  [1, 3, \"A\"],\n  [5, 7, \"B\"],\n]);\n\nassert.deepEqual(ranges.current(), [\n  [1, 3, \"A\"],\n  [5, 7, \"B\"],\n]);"},"last-range.js":{"title":"Read the most recently gathered range","code":"import { strict as assert } from \"node:assert\";\n\nimport { Ranges } from \"ranges-push\";\n\nconst ranges = new Ranges();\nranges.add(1, 2);\nranges.add(4, 6, \"X\");\n\nassert.deepEqual(ranges.last(), [4, 6, \"X\"]);"},"limit-added-whitespace.js":{"title":"Collapse replacement whitespace to one character","code":"import { strict as assert } from \"node:assert\";\n\nimport { Ranges } from \"ranges-push\";\n\nconst ranges = new Ranges({ limitToBeAddedWhitespace: true });\nranges.add(1, 2, \"  \\t  \");\n\nassert.deepEqual(ranges.current(), [[1, 2, \" \"]]);"},"limit-linebreak-count.js":{"title":"Retain at most two line breaks in replacement whitespace","code":"import { strict as assert } from \"node:assert\";\n\nimport { Ranges } from \"ranges-push\";\n\nconst ranges = new Ranges({\n  limitToBeAddedWhitespace: true,\n  limitLinebreaksCount: 2,\n});\nranges.add(1, 2, \"\\n\\n\\n\");\n\nassert.deepEqual(ranges.current(), [[1, 2, \"\\n\\n\"]]);"},"merge-type-one.js":{"title":"Concatenate replacement values when same-start ranges merge","code":"import { strict as assert } from \"node:assert\";\n\nimport { Ranges } from \"ranges-push\";\n\nconst ranges = new Ranges({ mergeType: 1 });\nranges.add(1, 4, \"A\");\nranges.add(1, 5, \"B\");\n\nassert.deepEqual(ranges.current(), [[1, 5, \"AB\"]]);"},"merge-type-two.js":{"title":"Keep the later replacement value when same-start ranges merge","code":"import { strict as assert } from \"node:assert\";\n\nimport { Ranges } from \"ranges-push\";\n\nconst ranges = new Ranges({ mergeType: 2 });\nranges.add(1, 4, \"A\");\nranges.add(1, 5, \"B\");\n\nassert.deepEqual(ranges.current(), [[1, 5, \"B\"]]);"},"replace-gathered-ranges.js":{"title":"Replace all previously gathered ranges","code":"import { strict as assert } from \"node:assert\";\n\nimport { Ranges } from \"ranges-push\";\n\nconst ranges = new Ranges();\nranges.add(1, 2);\nranges.replace([[3, 4, \"X\"]]);\n\nassert.deepEqual(ranges.current(), [[3, 4, \"X\"]]);"},"string-merge-type-one.js":{"title":"Accept the string form of merge type one","code":"import { strict as assert } from \"node:assert\";\n\nimport { Ranges } from \"ranges-push\";\n\nconst ranges = new Ranges({ mergeType: \"1\" });\nranges.add(1, 4, \"A\");\nranges.add(1, 5, \"B\");\n\nassert.deepEqual(ranges.current(), [[1, 5, \"AB\"]]);"},"string-merge-type-two.js":{"title":"Accept the string form of merge type two","code":"import { strict as assert } from \"node:assert\";\n\nimport { Ranges } from \"ranges-push\";\n\nconst ranges = new Ranges({ mergeType: \"2\" });\nranges.add(1, 4, \"A\");\nranges.add(1, 5, \"B\");\n\nassert.deepEqual(ranges.current(), [[1, 5, \"B\"]]);"},"wipe-ranges.js":{"title":"Clear every gathered range","code":"import { strict as assert } from \"node:assert\";\n\nimport { Ranges } from \"ranges-push\";\n\nconst ranges = new Ranges();\nranges.add(1, 2);\nranges.wipe();\n\nassert.equal(ranges.current(), null);"}},"ranges-regex":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { rRegex } from \"ranges-regex\";\n\nconst oldString = \"The quick brown fox jumps over the lazy dog.\";\nconst result = rRegex(/the/gi, oldString);\n\n// all regex matches, but in Ranges notation (see codsen.com/ranges/):\nassert.deepEqual(result, [\n  [0, 3],\n  [31, 34],\n]);"},"clashing-replacements.js":{"title":"Clashing replacement values","code":"import { strict as assert } from \"node:assert\";\nimport { rApply } from \"ranges-apply\";\nimport { Ranges } from \"ranges-push\";\nimport { rRegex } from \"ranges-regex\";\n\nconst source = \"sequence: 1234 5678 0000 1234\";\nconst gatheredRanges = new Ranges();\ngatheredRanges.push(rRegex(/\\d/g, source, \"*\"));\ngatheredRanges.push(rRegex(/\\b[0]+\\b/g, source, null));\n\nassert.deepEqual(gatheredRanges.current(), [\n  [10, 14, \"****\"],\n  [15, 19, \"****\"],\n  [20, 24, null],\n  [25, 29, \"****\"],\n]);\n\nassert.equal(\n  rApply(source, gatheredRanges.current()),\n  \"sequence: **** ****  ****\",\n);"},"explicit-deletion.js":{"title":"Give deletion precedence with a null replacement","code":"import { strict as assert } from \"node:assert\";\n\nimport { rRegex } from \"ranges-regex\";\n\nassert.deepEqual(rRegex(/\\b0+\\b/gu, \"10 000 20\", null), [[3, 6, null]]);"},"global-flag-required.js":{"title":"Require the global flag so every match can be collected safely","code":"import { strict as assert } from \"node:assert\";\n\nimport { rRegex } from \"ranges-regex\";\n\nassert.throws(() => rRegex(/word/u, \"word word\"), /THROW_ID_05/u);"},"matched-text.js":{"title":"Slice the source text using the returned ranges","code":"import { strict as assert } from \"node:assert\";\n\nimport { rRegex } from \"ranges-regex\";\n\nconst source = \"The quick brown fox jumps over the lazy dog.\";\nconst ranges = rRegex(/the/gi, source);\n\nassert.deepEqual(\n  ranges.map(([from, to]) => source.slice(from, to)),\n  [\"The\", \"the\"],\n);"},"merge-adjacent-matches.js":{"title":"Merge adjacent regex matches into one range","code":"import { strict as assert } from \"node:assert\";\n\nimport { rRegex } from \"ranges-regex\";\n\nassert.deepEqual(rRegex(/ab/gu, \"abab x ab\"), [\n  [0, 4],\n  [7, 9],\n]);"},"nothing-to-find.js":{"title":"Nothing was found","code":"import { strict as assert } from \"node:assert\";\n\nimport { rRegex } from \"ranges-regex\";\n\nassert.equal(rRegex(/abc/g, \"xyz\"), null);\n// Falsy null means no ranges, other Ranges ecosystem\n// packages will accept null as input value\n// For the record, an empty array is truthy"},"replacement-mini.js":{"title":"Replacing values","code":"import { strict as assert } from \"node:assert\";\nimport { rApply } from \"ranges-apply\";\nimport { rRegex } from \"ranges-regex\";\n\nconst source = \"the typo in 'quick brow fox' sentence\";\nconst ranges = rRegex(/\\bbrow\\b/g, source, \"brown\");\n\nassert.deepEqual(ranges, [[19, 23, \"brown\"]]);\nassert.equal(rApply(source, ranges), \"the typo in 'quick brown fox' sentence\");"},"unicode-zero-width.js":{"title":"Advance over a complete Unicode code point after an empty match","code":"import { strict as assert } from \"node:assert\";\n\nimport { rRegex } from \"ranges-regex\";\n\nassert.deepEqual(rRegex(/(?:)/gu, \"😀\", \"|\"), [\n  [0, 0, \"|\"],\n  [2, 2, \"|\"],\n]);"},"zero-width-insertions.js":{"title":"Turn zero-width matches into insertion ranges","code":"import { strict as assert } from \"node:assert\";\n\nimport { rRegex } from \"ranges-regex\";\n\nassert.deepEqual(rRegex(/(?:)/gu, \"ab\", \"|\"), [\n  [0, 0, \"|\"],\n  [1, 1, \"|\"],\n  [2, 2, \"|\"],\n]);"}},"ranges-sort":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { rSort } from \"ranges-sort\";\n\n// Ranges (see codsen.com/ranges/) are sorted:\nassert.deepEqual(\n  rSort([\n    [2, 3],\n    [9, 10, \"bad grey wolf\"],\n    [1, 2],\n  ]),\n  [\n    [1, 2],\n    [2, 3],\n    [9, 10, \"bad grey wolf\"],\n  ],\n);"},"empty-input.js":{"title":"Preserve empty range collections","code":"import { strict as assert } from \"node:assert\";\n\nimport { rSort } from \"ranges-sort\";\n\nassert.deepEqual(rSort([]), []);\nassert.equal(rSort(null), null);"},"progress-callback.js":{"title":"Observe sorting progress","code":"import { strict as assert } from \"node:assert\";\n\nimport { rSort } from \"ranges-sort\";\n\nconst percentages = [];\nconst result = rSort(\n  [\n    [3, 4],\n    [1, 2],\n    [2, 3],\n  ],\n  { progressFn: (percentage) => percentages.push(percentage) },\n);\n\nassert.deepEqual(result, [\n  [1, 2],\n  [2, 3],\n  [3, 4],\n]);\nassert.equal(percentages[percentages.length - 1], 100);\nassert.equal(\n  percentages.every(\n    (percentage, index) => index === 0 || percentage > percentages[index - 1],\n  ),\n  true,\n);"},"strict-range-shape.js":{"title":"Require two-element ranges","code":"import { strict as assert } from \"node:assert\";\n\nimport { rSort } from \"ranges-sort\";\n\nassert.throws(\n  () =>\n    rSort([[1, 2, \"replacement\"]], {\n      strictlyTwoElementsInRangeArrays: true,\n    }),\n  /THROW_ID_01/,\n);"}},"regex-empty-conditional-comments":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { emptyCondCommentRegex } from \"regex-empty-conditional-comments\";\n\nconst regex = emptyCondCommentRegex();\n\nassert.equal(regex.flags, \"gi\");\nassert.equal(\n  regex.test(`<!--[if !mso]>\n<![endif]-->`),\n  true,\n);"},"extract-first-empty-comment.js":{"title":"Extract the first empty conditional comment","code":"import { strict as assert } from \"node:assert\";\n\nimport { emptyCondCommentRegex } from \"regex-empty-conditional-comments\";\n\nassert.equal(\n  emptyCondCommentRegex().exec(\"<html><!--[if !mso]><![endif]--><title>\")[0],\n  \"<!--[if !mso]><![endif]-->\",\n);"},"find-all-empty-conditional-comments.js":{"title":"Find all empty conditional comments","code":"import { strict as assert } from \"node:assert\";\n\nimport { emptyCondCommentRegex } from \"regex-empty-conditional-comments\";\n\nconst html = `<!--[if !mso]><![endif]-->\n<p>Keep me</p>\n<!--[if gte mso 9]><![endif]-->`;\n\nassert.equal(html.match(emptyCondCommentRegex()).length, 2);"},"ignore-nonempty-conditional-comments.js":{"title":"Ignore conditional comments that contain markup","code":"import { strict as assert } from \"node:assert\";\n\nimport { emptyCondCommentRegex } from \"regex-empty-conditional-comments\";\n\nassert.equal(\n  emptyCondCommentRegex().test(`<!--[if !mso]><!-- -->\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\" />\n<!--<![endif]-->`),\n  false,\n);\n\nassert.equal(\n  emptyCondCommentRegex().test(`<!--[if gte mso 9]><xml>\n<o:OfficeDocumentSettings>\n<o:AllowPNG/>\n<o:PixelsPerInch>96</o:PixelsPerInch>\n</o:OfficeDocumentSettings>\n</xml><![endif]-->`),\n  false,\n);"},"match-only-empty-comments.js":{"title":"Collect empty conditional comments but skip populated ones","code":"import { strict as assert } from \"node:assert\";\n\nimport { emptyCondCommentRegex } from \"regex-empty-conditional-comments\";\n\nassert.deepEqual(\n  `<html> <!--[if !mso]><![endif]--> <title>text</title> <!--[if gte mso 9]>\n<xml>\n<![endif]-->`.match(emptyCondCommentRegex()),\n  [\"<!--[if !mso]><![endif]-->\"],\n);"},"non-outlook-empty-comment.js":{"title":"Match the revealed form of an empty conditional comment","code":"import { strict as assert } from \"node:assert\";\n\nimport { emptyCondCommentRegex } from \"regex-empty-conditional-comments\";\n\nassert.equal(\n  emptyCondCommentRegex().test(`<!--[if !mso]><!-- -->\n<!--<![endif]-->`),\n  true,\n);"},"remove-empty-conditional-comments.js":{"title":"Remove empty conditional comments","code":"import { strict as assert } from \"node:assert\";\n\nimport { emptyCondCommentRegex } from \"regex-empty-conditional-comments\";\n\nconst html = \"<head><!--[if !mso]><![endif]--><title>Example</title></head>\";\n\nassert.equal(\n  html.replace(emptyCondCommentRegex(), \"\"),\n  \"<head><title>Example</title></head>\",\n);"},"use-a-fresh-regex.js":{"title":"Use a fresh regular expression for an independent scan","code":"import { strict as assert } from \"node:assert\";\n\nimport { emptyCondCommentRegex } from \"regex-empty-conditional-comments\";\n\nconst comment = \"<!--[if mso]><![endif]-->\";\nconst first = emptyCondCommentRegex();\nconst second = emptyCondCommentRegex();\n\nassert.notEqual(first, second);\nassert.equal(first.test(comment), true);\nassert.equal(first.lastIndex, comment.length);\nassert.equal(second.lastIndex, 0);"}},"regex-is-jinja-nunjucks":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { isJinjaNunjucksRegex } from \"regex-is-jinja-nunjucks\";\n\n// detects Jinja/Nunjucks code\nassert.equal(\n  isJinjaNunjucksRegex().test(\n    \"<div>{% if data.purchases.count > 1 %}these{% else %}this{% endif %}</div>\",\n  ),\n  true,\n);"},"delimiter-styles.js":{"title":"Recognise Jinja and Nunjucks delimiter styles","code":"import { strict as assert } from \"node:assert\";\n\nimport { isJinjaNunjucksRegex } from \"regex-is-jinja-nunjucks\";\n\nassert.equal(isJinjaNunjucksRegex().test(\"{{ user.name }}\"), true);\nassert.equal(isJinjaNunjucksRegex().test(\"{% if ready %}\"), true);\n\n// This package specifically detects output and statement delimiters.\nassert.equal(isJinjaNunjucksRegex().test(\"{# a template comment #}\"), false);"},"plain-html.js":{"title":"Reject HTML without Jinja or Nunjucks delimiters","code":"import { strict as assert } from \"node:assert\";\n\nimport { isJinjaNunjucksRegex } from \"regex-is-jinja-nunjucks\";\n\nassert.equal(isJinjaNunjucksRegex().test(\"<div>Plain text</div>\"), false);"}},"regex-is-jsp":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { isJSP } from \"regex-is-jsp\";\n\n// detects JSP code\nassert.equal(isJSP().test('<div><% out.println(\"Hi!\"); %></div>'), true);"},"directive.js":{"title":"Detect a JSP page directive","code":"import { strict as assert } from \"node:assert\";\n\nimport { isJSP } from \"regex-is-jsp\";\n\nassert.equal(isJSP().test('<%@ page contentType=\"text/html\" %>'), true);"},"jsp-action.js":{"title":"Detect a JSP action tag","code":"import { strict as assert } from \"node:assert\";\n\nimport { isJSP } from \"regex-is-jsp\";\n\nassert.equal(\n  isJSP().test('<jsp:useBean id=\"user\" class=\"example.User\" />'),\n  true,\n);"},"jsp-expression-property.js":{"title":"Detect an expression that refers to a JSP property","code":"/** biome-ignore-all lint/suspicious/noTemplateCurlyInString: fixture contains literal JSP expression syntax */\n\nimport { strict as assert } from \"node:assert\";\n\nimport { isJSP } from \"regex-is-jsp\";\n\nassert.equal(isJSP().test(\"${jspProp.accountNumber}\"), true);"},"plain-html.js":{"title":"Reject HTML without JSP syntax","code":"import { strict as assert } from \"node:assert\";\n\nimport { isJSP } from \"regex-is-jsp\";\n\nassert.equal(isJSP().test(\"<div>Plain text</div>\"), false);"},"tag-library.js":{"title":"Detect a JSP Standard Tag Library tag","code":"/** biome-ignore-all lint/suspicious/noTemplateCurlyInString: fixture contains literal JSP expression syntax */\n\nimport { strict as assert } from \"node:assert\";\n\nimport { isJSP } from \"regex-is-jsp\";\n\nassert.equal(isJSP().test('<c:if test=\"${enabled}\">Visible</c:if>'), true);"}},"regex-jinja-specific":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { isJinjaSpecific } from \"regex-jinja-specific\";\n\nassert.equal(\n  isJinjaSpecific().test(\"<div>{{ '%.2f'|format(3.1415926) }}</div>\"),\n  true,\n);"},"inline-conditional.js":{"title":"Detect Jinja's inline conditional ordering","code":"import { strict as assert } from \"node:assert\";\n\nimport { isJinjaSpecific } from \"regex-jinja-specific\";\n\nassert.equal(\n  isJinjaSpecific().test(\"{{'enabled' if active else 'disabled'}}\"),\n  true,\n);"},"namespace.js":{"title":"Detect Jinja namespace assignment syntax","code":"import { strict as assert } from \"node:assert\";\n\nimport { isJinjaSpecific } from \"regex-jinja-specific\";\n\nassert.equal(\n  isJinjaSpecific().test(\"{% set totals = namespace(value=0) %}\"),\n  true,\n);"},"number-formatting.js":{"title":"Detect Jinja's Python-style number formatting filter","code":"import { strict as assert } from \"node:assert\";\n\nimport { isJinjaSpecific } from \"regex-jinja-specific\";\n\nassert.equal(isJinjaSpecific().test(\"{{ '%+.2f'|format(total) }}\"), true);\nassert.equal(isJinjaSpecific().test(\"{{ total }}\"), false);"}},"rehype-responsive-tables":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\nimport { rehype } from \"rehype\";\nimport rehypeFormat from \"rehype-format\";\nimport rehypeResponsiveTables from \"rehype-responsive-tables\";\n\nconst input = `\n<table>\n  <tbody>\n    <tr>\n      <td>a</td>\n      <td>b</td>\n      <td>c</td>\n    </tr>\n  </tbody>\n</table>\n`;\n\nconst intended = `\n<table class=\"rrt-table\">\n  <tbody>\n    <tr class=\"rrt-new-tr\">\n      <td class=\"rrt-del-td\"></td>\n      <td colspan=\"2\"><span class=\"rrt-new-tr__span-top\">a</span></td>\n    </tr>\n    <tr>\n      <td class=\"rrt-del-td\">a</td>\n      <td>b</td>\n      <td>c</td>\n    </tr>\n  </tbody>\n</table>\n`;\n\nassert.equal(\n  rehype()\n    .data(\"settings\", { fragment: true })\n    .use(rehypeResponsiveTables, {\n      tableClassName: \"rrt-table\",\n    })\n    .use(rehypeFormat)\n    .processSync(input)\n    .toString(),\n  intended,\n);"},"contains-text.js":{"title":"Find exact text in a HAST tree","code":"import { strict as assert } from \"node:assert\";\n\nimport { contains } from \"rehype-responsive-tables\";\n\nconst tree = {\n  type: \"root\",\n  children: [\n    {\n      type: \"element\",\n      tagName: \"th\",\n      properties: {},\n      children: [{ type: \"text\", value: \" Role \" }],\n    },\n  ],\n};\n\nassert.equal(contains(tree, \"Role\"), \"Role\");\nassert.equal(contains(tree, [\"Name\", \"Role\"]), \"Role\");\nassert.equal(contains(tree, \"Missing\"), undefined);"},"custom-class-names.js":{"title":"Customise every generated class name","code":"import { strict as assert } from \"node:assert\";\nimport { rehype } from \"rehype\";\n\nimport rehypeResponsiveTables from \"rehype-responsive-tables\";\n\nconst source = `<table>\n  <thead><tr><th>Name</th><th>Value</th></tr></thead>\n  <tbody>\n    <tr><td>First</td><td>1</td></tr>\n    <tr><td>Second</td><td>2</td></tr>\n  </tbody>\n</table>`;\n\nconst result = rehype()\n  .data(\"settings\", { fragment: true })\n  .use(rehypeResponsiveTables, {\n    tableClassName: \"responsive\",\n    newTrClassName: \"label-row\",\n    hideTdClassName: \"visually-hidden\",\n    gapTrClassName: \"row-gap\",\n    newTrSpanTopClassName: \"primary-label\",\n    newTrSpanOtherClassName: \"secondary-label\",\n    up: [\"Value\"],\n  })\n  .processSync(source)\n  .toString();\n\nassert.equal(result.includes('class=\"responsive\"'), true);\nassert.equal(result.includes('class=\"label-row\"'), true);\nassert.equal(result.includes('class=\"visually-hidden\"'), true);\nassert.equal(result.includes('class=\"row-gap\"'), true);\nassert.equal(result.includes('class=\"primary-label\"'), true);\nassert.equal(result.includes('class=\"secondary-label\"'), true);"},"lift-all-columns.js":{"title":"Lift every labelled column with a wildcard","code":"import { strict as assert } from \"node:assert\";\nimport { rehype } from \"rehype\";\n\nimport rehypeResponsiveTables from \"rehype-responsive-tables\";\n\nconst source = `<table>\n  <thead><tr><th>Name</th><th>Role</th></tr></thead>\n  <tbody><tr><td>Ada</td><td>Engineer</td></tr></tbody>\n</table>`;\n\nconst result = rehype()\n  .data(\"settings\", { fragment: true })\n  .use(rehypeResponsiveTables, { up: [\"*\"] })\n  .processSync(source)\n  .toString();\n\nassert.equal(result.includes(\"Name:</span> Ada\"), true);\nassert.equal(result.includes(\"Role:</span> Engineer\"), true);"},"markdown-tables.js":{"title":"Renders markdown tables","code":"import { strict as assert } from \"node:assert\";\nimport rehypeFormat from \"rehype-format\";\nimport rehypeStringify from \"rehype-stringify\";\nimport remarkGfm from \"remark-gfm\";\nimport remarkParse from \"remark-parse\";\nimport remarkRehype from \"remark-rehype\";\nimport { unified } from \"unified\";\nimport rehypeResponsiveTables from \"rehype-responsive-tables\";\n\nconst markdownTable = `\n| Foo | Bar | Baz |\n|-----|-----|-----|\n| a   | b   | c   |\n| x   | y   | z   |\n`.trim();\n\nconst intended = `\n<table class=\"rrt-table\">\n  <thead>\n    <tr>\n      <th class=\"rrt-del-td\">Foo</th>\n      <th class=\"rrt-del-td\">Bar</th>\n      <th>Baz</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr class=\"rrt-new-tr\">\n      <td class=\"rrt-del-td\"></td>\n      <td colspan=\"2\"><span class=\"rrt-new-tr__span-top\">a</span><br><span class=\"rrt-new-tr__span-other\">Bar:</span> b</td>\n    </tr>\n    <tr>\n      <td class=\"rrt-del-td\">a</td>\n      <td class=\"rrt-del-td\">b</td>\n      <td>c</td>\n    </tr>\n    <tr class=\"rrt-gap-tr\">\n      <td class=\"rrt-del-td\"></td>\n      <td colspan=\"2\"></td>\n    </tr>\n    <tr class=\"rrt-new-tr\">\n      <td class=\"rrt-del-td\"></td>\n      <td colspan=\"2\"><span class=\"rrt-new-tr__span-top\">x</span><br><span class=\"rrt-new-tr__span-other\">Bar:</span> y</td>\n    </tr>\n    <tr>\n      <td class=\"rrt-del-td\">x</td>\n      <td class=\"rrt-del-td\">y</td>\n      <td>z</td>\n    </tr>\n  </tbody>\n</table>\n`;\n\nconst { value } = unified()\n  .data(\"settings\", { fragment: true })\n  .use(remarkParse)\n  .use(remarkGfm)\n  .use(remarkRehype)\n  .use(rehypeResponsiveTables, {\n    up: [\"Bar\"],\n  })\n  .use(rehypeFormat)\n  .use(rehypeStringify)\n  .processSync(markdownTable);\n\n// default behaviour:\nassert.equal(value, intended);"},"nth-child-tag.js":{"title":"Find a numbered child element by tag name","code":"import { strict as assert } from \"node:assert\";\n\nimport { getNthChildTag } from \"rehype-responsive-tables\";\n\nconst tree = {\n  children: [\n    { type: \"text\", value: \"\\n\" },\n    { type: \"element\", tagName: \"td\", children: [] },\n    { type: \"element\", tagName: \"th\", children: [] },\n    { type: \"element\", tagName: \"td\", children: [] },\n  ],\n};\n\nassert.equal(getNthChildTag(tree, \"td\", 1), tree.children[3]);\nassert.equal(getNthChildTag(tree, \"td\", 2), null);"}},"remark-conventional-commit-changelog-timeline":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\nimport rehypeFormat from \"rehype-format\";\nimport rehypeStringify from \"rehype-stringify\";\nimport remarkGfm from \"remark-gfm\";\nimport remarkParse from \"remark-parse\";\nimport remarkRehype from \"remark-rehype\";\nimport { unified } from \"unified\";\n\nimport c from \"remark-conventional-commit-changelog-timeline\";\n\nfunction render(str, opts) {\n  let res = unified()\n    .data(\"settings\", { fragment: true })\n    .use(remarkParse)\n    .use(remarkGfm)\n    .use(remarkRehype)\n    .use(c, opts)\n    .use(rehypeFormat)\n    .use(rehypeStringify)\n    .processSync(str);\n\n  return res.value;\n}\n\nlet input = `\n# Change Log\n\nAll notable changes to this project will be documented in this file.\nSee [Conventional Commits](https://conventionalcommits.org) for commit guidelines.\n\n# 3.1.0 (2022-08-12)\n\n### Features\n\n- abc\n- xyz\n`;\n\nlet expected = `\n<h2>3.1.0</h2>\n<div class=\"release-date\">Aug 12, <span>2022</span></div>\n<h3><span class=\"emoji\">✨</span> Features</h3>\n<ul>\n  <li>abc</li>\n  <li>xyz</li>\n</ul>\n`;\n\nassert.equal(\n  render(input, {\n    // defaults:\n    dateDivLocale: \"en-US\",\n\n    dateDivMarkup: ({ date, year, month, day }) =>\n      `${month} ${day}, <span>${year}</span>`,\n  }),\n  expected,\n);"},"arabic.js":{"title":"Arabic dates","code":"import { strict as assert } from \"node:assert\";\nimport rehypeFormat from \"rehype-format\";\nimport rehypeStringify from \"rehype-stringify\";\nimport remarkGfm from \"remark-gfm\";\nimport remarkParse from \"remark-parse\";\nimport remarkRehype from \"remark-rehype\";\nimport { unified } from \"unified\";\n\nimport c from \"remark-conventional-commit-changelog-timeline\";\n\nfunction render(str, opts) {\n  let res = unified()\n    .data(\"settings\", { fragment: true })\n    .use(remarkParse)\n    .use(remarkGfm)\n    .use(remarkRehype)\n    .use(c, opts)\n    .use(rehypeFormat)\n    .use(rehypeStringify)\n    .processSync(str);\n\n  return res.value;\n}\n\nlet input = `\n# 0.0.1 (2022-01-01)\n\n### Features\n\n- abc\n- xyz\n`;\n\n// beware it's right-to-left:\nlet arabicDate = `\n٢٠٢٢/يناير/١\n`.trim();\n\nlet expected = `\n<h2>0.0.1</h2>\n<div class=\"release-date\">${arabicDate}</div>\n<h3><span class=\"emoji\">✨</span> Features</h3>\n<ul>\n  <li>abc</li>\n  <li>xyz</li>\n</ul>\n`;\n\nassert.equal(\n  render(input, {\n    dateDivLocale: \"ar-EG\",\n    dateDivMarkup: ({ year, month, day }) => `${year}/${month}/${day}`,\n  }),\n  expected,\n);"},"linked-version.js":{"title":"Convert a linked release heading into timeline markup","code":"import { strict as assert } from \"node:assert\";\nimport rehypeFormat from \"rehype-format\";\nimport rehypeStringify from \"rehype-stringify\";\nimport remarkGfm from \"remark-gfm\";\nimport remarkParse from \"remark-parse\";\nimport remarkRehype from \"remark-rehype\";\nimport { unified } from \"unified\";\n\nimport timeline from \"remark-conventional-commit-changelog-timeline\";\n\nconst result = unified()\n  .data(\"settings\", { fragment: true })\n  .use(remarkParse)\n  .use(remarkGfm)\n  .use(remarkRehype)\n  .use(timeline)\n  .use(rehypeFormat)\n  .use(rehypeStringify)\n  .processSync(\n    \"# [2.0.0](https://example.com/releases/2.0.0) (2024-03-05)\\n\",\n  ).value;\n\nassert.equal(\n  result,\n  `\n<h2>2.0.0</h2>\n<div class=\"release-date\">Mar 5, <span>2024</span></div>\n`,\n);"},"section-emojis.js":{"title":"Add the conventional emoji for each recognised change section","code":"import { strict as assert } from \"node:assert\";\nimport rehypeStringify from \"rehype-stringify\";\nimport remarkParse from \"remark-parse\";\nimport remarkRehype from \"remark-rehype\";\nimport { unified } from \"unified\";\n\nimport timeline from \"remark-conventional-commit-changelog-timeline\";\n\nconst result = unified()\n  .use(remarkParse)\n  .use(remarkRehype)\n  .use(timeline)\n  .use(rehypeStringify)\n  .processSync(\n    \"### Features\\n\\n### BREAKING CHANGES\\n\\n### Reverts\\n\\n### Changes\\n\\n### Improvements\\n\\n### Bug Fixes\\n\",\n  ).value;\n\nassert.match(result, /<span class=\"emoji\">✨<\\/span> Features/);\nassert.match(result, /<span class=\"emoji\">💥<\\/span> BREAKING CHANGES/);\nassert.match(result, /<span class=\"emoji\">⏪<\\/span> Reverts/);\nassert.match(result, /<span class=\"emoji\">✈️<\\/span> Changes/);\nassert.match(result, /<span class=\"emoji\">🏗️<\\/span> Improvements/);\nassert.match(result, /<span class=\"emoji\">🔧<\\/span> Fixed/);"}},"remark-typography":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\nimport { remark } from \"remark\";\n\nimport fixTypography from \"remark-typography\";\n\n(async () => {\n  assert.equal(\n    (await remark().use(fixTypography, {}).process(\"Yes that's true but...\"))\n      .toString()\n      .trim(),\n    \"Yes that\\u2019s true\\u00A0but\\u2026\",\n  );\n})();"},"ellipsis.js":{"title":"Convert a three-dot ellipsis","code":"import { strict as assert } from \"node:assert\";\nimport { remark } from \"remark\";\n\nimport fixTypography from \"remark-typography\";\n\nassert.equal(\n  remark().use(fixTypography).processSync(\"Wait...\").toString().trim(),\n  \"Wait…\",\n);"},"inline-code-possessives.js":{"title":"Fix apostrophes following inline code nodes","code":"import { strict as assert } from \"node:assert\";\nimport { remark } from \"remark\";\n\nimport fixTypography from \"remark-typography\";\n\nassert.equal(\n  remark()\n    .use(fixTypography)\n    .processSync(\"The `deno`'s and `verb`'s approaches.\")\n    .toString()\n    .trim(),\n  \"The `deno`’s and `verb`’s\\u00A0approaches.\",\n);"},"multiplication.js":{"title":"Convert a multiplication marker","code":"import { strict as assert } from \"node:assert\";\nimport { remark } from \"remark\";\n\nimport fixTypography from \"remark-typography\";\n\nassert.equal(\n  remark().use(fixTypography).processSync(\"3 x 4\").toString().trim(),\n  \"3 × 4\",\n);"},"progress-and-completion.js":{"title":"Report document progress and completion","code":"import { strict as assert } from \"node:assert\";\nimport { remark } from \"remark\";\n\nimport fixTypography from \"remark-typography\";\n\nconst progress = [];\nconst file = remark()\n  .use(fixTypography, {\n    reportProgressFunc: (percentageDone) => progress.push(percentageDone),\n    reportProgressFuncFrom: 20,\n    reportProgressFuncTo: 40,\n  })\n  .processSync(\"Wait...\");\nconst completion = file.data.remarkTypography;\n\nassert.deepEqual(\n  {\n    completion: {\n      ...completion,\n      timeTakenInMilliseconds: typeof completion.timeTakenInMilliseconds,\n    },\n    output: file.toString().trim(),\n    progress: {\n      first: progress[0],\n      last: progress[progress.length - 1],\n      strictlyIncreasing: progress.every(\n        (value, index) => index === 0 || value > progress[index - 1],\n      ),\n    },\n  },\n  {\n    completion: {\n      apostrophesConverted: 0,\n      blocksProcessed: 1,\n      charactersProcessed: 7,\n      dashesConverted: 0,\n      ellipsesConverted: 1,\n      multiplicationSignsConverted: 0,\n      replacementsApplied: 1,\n      textNodesChanged: 1,\n      textNodesProcessed: 1,\n      timeTakenInMilliseconds: \"number\",\n      widowMeasuresAdded: 0,\n    },\n    output: \"Wait…\",\n    progress: {\n      first: 20,\n      last: 40,\n      strictlyIncreasing: true,\n    },\n  },\n);"},"quotes-and-apostrophes.js":{"title":"Convert straight quotes and apostrophes","code":"import { strict as assert } from \"node:assert\";\nimport { remark } from \"remark\";\n\nimport fixTypography from \"remark-typography\";\n\nassert.equal(\n  remark()\n    .use(fixTypography)\n    .processSync(`'single' and \"double\"`)\n    .toString()\n    .trim(),\n  \"‘single’ and “double”\",\n);"},"remove-widows.js":{"title":"Keep the last two words together","code":"import { strict as assert } from \"node:assert\";\nimport { remark } from \"remark\";\n\nimport fixTypography from \"remark-typography\";\n\nassert.equal(\n  remark()\n    .use(fixTypography)\n    .processSync(\"this is a long ending\")\n    .toString()\n    .trim(),\n  \"this is a long ending\",\n);"},"spaced-dashes.js":{"title":"Convert a spaced dash","code":"import { strict as assert } from \"node:assert\";\nimport { remark } from \"remark\";\n\nimport fixTypography from \"remark-typography\";\n\nassert.equal(\n  remark()\n    .use(fixTypography)\n    .processSync(\"Some text - more text.\")\n    .toString()\n    .trim(),\n  \"Some text — more text.\",\n);"}},"str-indexes-of-plus":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { strIndexesOfPlus } from \"str-indexes-of-plus\";\n\n// searches for string in a string, returns array:\nassert.deepEqual(strIndexesOfPlus(\"abc-abc-abc-abc\", \"abc\"), [0, 4, 8, 12]);"},"empty-search.js":{"title":"Search for an empty string","code":"import { strict as assert } from \"node:assert\";\n\nimport { strIndexesOfPlus } from \"str-indexes-of-plus\";\n\nassert.deepEqual(strIndexesOfPlus(\"content\", \"\"), []);"},"overlapping-matches.js":{"title":"Report overlapping matches","code":"import { strict as assert } from \"node:assert\";\n\nimport { strIndexesOfPlus } from \"str-indexes-of-plus\";\n\nassert.deepEqual(strIndexesOfPlus(\"aaaa\", \"aa\"), [0, 1, 2]);"},"string-start-offset.js":{"title":"Start searching from a given index","code":"import { strict as assert } from \"node:assert\";\n\nimport { strIndexesOfPlus } from \"str-indexes-of-plus\";\n\nassert.deepEqual(strIndexesOfPlus(\"one one one\", \"one\", \"4\"), [4, 8]);"},"unicode-indexes.js":{"title":"Emoji count as single characters","code":"import { strict as assert } from \"node:assert\";\n\nimport { strIndexesOfPlus } from \"str-indexes-of-plus\";\n\n// Emoji count as one grapheme, regardless of their native JavaScript length.\nassert.deepEqual(strIndexesOfPlus(\"🐴-🦄\", \"🦄\"), [2]);"}},"string-apostrophes":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertAll } from \"string-apostrophes\";\n\nassert.deepEqual(\n  convertAll(\"In the '60s, rock 'n' roll\", {\n    convertApostrophes: true,\n    convertEntities: false,\n  }),\n  {\n    result: \"In the ’60s, rock ’n’ roll\",\n    ranges: [\n      [7, 8, \"’\"],\n      [18, 21, \"’n’\"],\n    ],\n  },\n);"},"convert-one-apostrophe.js":{"title":"Convert one apostrophe into an entity","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertOne } from \"string-apostrophes\";\n\nassert.deepEqual(\n  convertOne(\"test's\", {\n    from: 4,\n    to: 5,\n    convertApostrophes: true,\n    convertEntities: true,\n  }),\n  [[4, 5, \"&rsquo;\"]],\n);"},"convert-one-supplied-value.js":{"title":"Supply the apostrophe value separately","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertOne } from \"string-apostrophes\";\n\nassert.deepEqual(\n  convertOne(\"Its ready\", {\n    from: 2,\n    to: 2,\n    value: \"'\",\n    convertEntities: true,\n  }),\n  [[2, 2, \"&rsquo;\"]],\n);"},"disable-apostrophe-conversion.js":{"title":"Disable the apostrophe conversion","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertAll } from \"string-apostrophes\";\n\nassert.equal(\n  convertAll(\"It\\u2019s called \\u2018alpha\\u2019.\", {\n    convertApostrophes: false,\n  }).result,\n  \"It's called 'alpha'.\",\n);"},"double-quotation-marks.js":{"title":"Convert double quotation marks","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertAll } from \"string-apostrophes\";\n\nassert.equal(\n  convertAll('She said, \"hello.\"').result,\n  \"She said, \\u201chello.\\u201d\",\n);"},"html-quote-entities.js":{"title":"Convert the quotes into HTML entities","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertAll } from \"string-apostrophes\";\n\nassert.equal(\n  convertAll('She said, \"hello.\"', { convertEntities: true }).result,\n  \"She said, &ldquo;hello.&rdquo;\",\n);"},"measurement-primes.js":{"title":"Convert measurement primes","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertAll } from \"string-apostrophes\";\n\nassert.equal(\n  convertAll(\"The board is 6' long.\").result,\n  \"The board is 6\\u2032 long.\",\n);"},"nested-quotations.js":{"title":"Convert nested quotations","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertAll } from \"string-apostrophes\";\n\nassert.equal(\n  convertAll(`She said, \"Call it 'alpha'.\"`).result,\n  \"She said, \\u201cCall it \\u2018alpha\\u2019.\\u201d\",\n);"},"offset-callback.js":{"title":"Report the index offsets through a callback","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertOne } from \"string-apostrophes\";\n\nconst skippedBy = [];\nconst ranges = convertOne(\"Rock ‘n‘ roll\", {\n  from: 5,\n  to: 6,\n  convertApostrophes: false,\n  convertEntities: false,\n  offsetBy: (amount) => skippedBy.push(amount),\n});\n\nassert.deepEqual(ranges, [[5, 8, \"'n'\"]]);\nassert.equal(skippedBy.join(\",\"), \"2\");"}},"string-character-is-astral-surrogate":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  isHighSurrogate,\n  isLowSurrogate,\n} from \"string-character-is-astral-surrogate\";\n\n// 🧢 = \\uD83E\\uDDE2\n\nassert.equal(isHighSurrogate(\"\\uD83E\"), true);\n// the first character, high surrogate of the cap is indeed a high surrogate\n\nassert.equal(isHighSurrogate(\"\\uDDE2\"), false);\n// the second character, low surrogate of the cap is NOT a high surrogate\n\nassert.equal(isLowSurrogate(\"\\uD83E\"), false);\n// the first character, high surrogate of the cap is NOT a low surrogate\n// it's a high surrogate\n\nassert.equal(isLowSurrogate(\"\\uDDE2\"), true);\n// the second character, low surrogate of the cap is indeed a low surrogate"},"missing-next-character.js":{"title":"Treat a missing code unit as not being a surrogate","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  isHighSurrogate,\n  isLowSurrogate,\n} from \"string-character-is-astral-surrogate\";\n\nassert.equal(isHighSurrogate(undefined), false);\nassert.equal(isLowSurrogate(undefined), false);"},"whole-astral-character.js":{"title":"Inspect the first UTF-16 code unit of an astral character","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  isHighSurrogate,\n  isLowSurrogate,\n} from \"string-character-is-astral-surrogate\";\n\nassert.equal(isHighSurrogate(\"🧢\"), true);\nassert.equal(isLowSurrogate(\"🧢\"), false);"}},"string-collapse-leading-whitespace":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { collWhitespace } from \"string-collapse-leading-whitespace\";\n\nassert.equal(collWhitespace(\"  aaa   \"), \" aaa \");"},"collapse-boundary-line-breaks.js":{"title":"Collapse boundary whitespace containing line breaks","code":"import { strict as assert } from \"node:assert\";\n\nimport { collWhitespace } from \"string-collapse-leading-whitespace\";\n\nassert.equal(collWhitespace(\"     \\n\\n   aaa  \\n\\n\\n    \"), \"\\naaa\\n\");"},"crlf.js":{"title":"Preserve CRLF line endings","code":"import { strict as assert } from \"node:assert\";\n\nimport { collWhitespace } from \"string-collapse-leading-whitespace\";\n\nassert.equal(\n  collWhitespace(\"\\r\\n\\r\\n\\r\\ncontent\\r\\n\\r\\n\\r\\n\", 2),\n  \"\\r\\n\\r\\ncontent\\r\\n\\r\\n\",\n);"},"line-break-limit.js":{"title":"Keep a chosen number of leading and trailing line breaks","code":"import { strict as assert } from \"node:assert\";\n\nimport { collWhitespace } from \"string-collapse-leading-whitespace\";\n\nassert.equal(collWhitespace(\"\\n\\n\\ncontent\\n\\n\\n\", 2), \"\\n\\ncontent\\n\\n\");\nassert.equal(collWhitespace(\"\\n\\n\\ncontent\\n\\n\\n\", 0), \"content\");"},"non-breaking-spaces.js":{"title":"Preserve non-breaking-space boundaries","code":"import { strict as assert } from \"node:assert\";\n\nimport { collWhitespace } from \"string-collapse-leading-whitespace\";\n\nconst nbsp = \"\\u00A0\";\n\nassert.equal(collWhitespace(`  ${nbsp}content`), `${nbsp}content`);\nassert.equal(collWhitespace(`content${nbsp}  `), `content${nbsp}`);"},"non-string-passthrough.js":{"title":"Pass through non-string input","code":"import { strict as assert } from \"node:assert\";\n\nimport { collWhitespace } from \"string-collapse-leading-whitespace\";\n\nconst value = { untouched: true };\n\nassert.equal(collWhitespace(value), value);"},"preserve-inner-whitespace.js":{"title":"Leave whitespace inside a multiline string unchanged","code":"import { strict as assert } from \"node:assert\";\n\nimport { collWhitespace } from \"string-collapse-leading-whitespace\";\n\nassert.equal(\n  collWhitespace(\"  abc  \\n  def  \\n  ghi  \"),\n  \" abc  \\n  def  \\n  ghi \",\n);"},"trimmed-string.js":{"title":"Preserve a string that has no boundary whitespace","code":"import { strict as assert } from \"node:assert\";\n\nimport { collWhitespace } from \"string-collapse-leading-whitespace\";\n\nassert.equal(collWhitespace(\"aaa\"), \"aaa\");"},"whitespace-only.js":{"title":"Collapse strings containing only whitespace","code":"import { strict as assert } from \"node:assert\";\n\nimport { collWhitespace } from \"string-collapse-leading-whitespace\";\n\nassert.equal(collWhitespace(\"    \"), \" \");\nassert.equal(collWhitespace(\"  \\n\\n  \"), \"\\n\");\nassert.equal(collWhitespace(\"  \\n\\n  \", 2), \"\\n\\n\");"}},"string-collapse-white-space":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.equal(\n  collapse(\"  aaa     bbb    ccc   dddd  \").result,\n  \"aaa bbb ccc dddd\",\n);"},"cb.js":{"title":"Minify a chunk of CSS selector","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.equal(\n  collapse(\"div > span\", {\n    cb: ({ suggested, whiteSpaceStartsAt, whiteSpaceEndsAt, str }) => {\n      if (str[whiteSpaceStartsAt - 1] === \">\") {\n        // console.log(`> on the left! - wipe this whitespace`);\n        return [whiteSpaceStartsAt, whiteSpaceEndsAt];\n      }\n      if (str[whiteSpaceEndsAt] === \">\") {\n        // console.log(`> on the right! - wipe this whitespace`);\n        return [whiteSpaceStartsAt, whiteSpaceEndsAt];\n      }\n      return suggested;\n    },\n  }).result,\n  \"div>span\",\n);"},"collapse-tabs.js":{"title":"Collapse a run containing tabs","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.equal(collapse(\"   \\t\\t\\t   aaa   \\t\\t\\t   \").result, \"aaa\");"},"enforce-spaces-only.js":{"title":"Replace tabs inside whitespace runs with ordinary spaces","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.equal(\n  collapse(\"one\\t\\ttwo\", { enforceSpacesOnly: true }).result,\n  \"one two\",\n);\nassert.equal(\n  collapse(\"one\\t\\ttwo\", { enforceSpacesOnly: false }).result,\n  \"one\\t\\ttwo\",\n);"},"limit-empty-lines.js":{"title":"Keep at most one consecutive empty line","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.equal(\n  collapse(\"first\\n\\n\\n\\nsecond\", {\n    removeEmptyLines: true,\n    limitConsecutiveEmptyLinesTo: 1,\n  }).result,\n  \"first\\n\\nsecond\",\n);"},"preserve-leading-space.js":{"title":"Collapse but preserve one leading space","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.equal(collapse(\"   value\", { trimStart: false }).result, \" value\");"},"preserve-line-padding.js":{"title":"Preserve one space around each line's content","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.equal(\n  collapse(\"   aaa   bbb  \\n    ccc   ddd   \", { trimLines: false }).result,\n  \"aaa bbb \\n ccc ddd\",\n);"},"preserve-trailing-space.js":{"title":"Collapse but preserve one trailing space","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.equal(collapse(\"value   \", { trimEnd: false }).result, \"value \");"},"remove-empty-lines.js":{"title":"Remove empty lines from multiline text","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.equal(\n  collapse(\"first\\n\\nsecond\", { removeEmptyLines: true }).result,\n  \"first\\nsecond\",\n);"},"replacement-ranges.js":{"title":"Inspect the ranges used to produce the collapsed result","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.deepEqual(collapse(\"one   two\").ranges, [[3, 5]]);"},"trim-each-line.js":{"title":"Trim whitespace from the start and end of every line","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.equal(\n  collapse(\"  first  \\n   second   \", { trimLines: true }).result,\n  \"first\\nsecond\",\n);"},"trim-multiline-non-breaking-spaces.js":{"title":"Trim multiline content whose boundaries contain non-breaking spaces","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.equal(\n  collapse(\n    \"     \\xa0    aaa   bbb    \\xa0    \\n     \\xa0     ccc   ddd   \\xa0   \",\n    { trimLines: true, trimnbsp: true },\n  ).result,\n  \"aaa bbb\\nccc ddd\",\n);"},"trim-non-breaking-spaces.js":{"title":"Trim raw non-breaking spaces with ordinary whitespace","code":"import { strict as assert } from \"node:assert\";\n\nimport { collapse } from \"string-collapse-white-space\";\n\nassert.equal(\n  collapse(\"\\u00a0  value  \\u00a0\", { trimnbsp: true }).result,\n  \"value\",\n);"}},"string-convert-indexes":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { nativeToUnicode } from \"string-convert-indexes\";\n\n// CONVERTING NATIVE JS INDEXES TO UNICODE-CHAR-COUNT-BASED\n// 𝌆 - \\uD834\\uDF06\n\n// at index 1, we have low surrogate, that's still grapheme index zero\nassert.equal(nativeToUnicode(\"\\uD834\\uDF06aa\", \"1\"), \"0\");\n// notice it's retained as string. The same type as input is retained!"},"convert-index-map.js":{"title":"Convert the indexes within a plain object","code":"import { strict as assert } from \"node:assert\";\n\nimport { nativeToUnicode } from \"string-convert-indexes\";\n\nconst selection = { start: 2, end: 3, metadata: [\"0\"] };\nconst unicodeSelection = nativeToUnicode(\"\\ud834\\udf06aa\", selection);\n\nassert.deepEqual(unicodeSelection, { start: 1, end: 2, metadata: [\"0\"] });"},"native-index-array.js":{"title":"Convert an array of native indexes","code":"import { strict as assert } from \"node:assert\";\n\nimport { nativeToUnicode } from \"string-convert-indexes\";\n\nassert.deepEqual(nativeToUnicode(\"\\uD834\\uDF06aa\", [1, 0, 2, 3]), [0, 0, 1, 2]);"},"native-numeric-index.js":{"title":"Convert a single native index","code":"import { strict as assert } from \"node:assert\";\n\nimport { nativeToUnicode } from \"string-convert-indexes\";\n\n// At native index 3, the second \"a\" is Unicode index 2.\nassert.equal(nativeToUnicode(\"\\uD834\\uDF06aa\", 3), 2);"},"nested-index-structure.js":{"title":"Convert the indexes within a nested structure","code":"import { strict as assert } from \"node:assert\";\n\nimport { nativeToUnicode } from \"string-convert-indexes\";\n\nassert.deepEqual(nativeToUnicode(\"\\uD834\\uDF06aa\", [1, \"0\", [[[2]]], 3]), [\n  0,\n  \"0\",\n  [[[1]]],\n  2,\n]);"},"out-of-range-unicode-index.js":{"title":"Throw on an out-of-range Unicode index","code":"import { strict as assert } from \"node:assert\";\n\nimport { unicodeToNative } from \"string-convert-indexes\";\n\nassert.throws(() => unicodeToNative(\"\\uD834\\uDF06aa\", [1, 0, 2, 3]));"},"round-trip-index-map.js":{"title":"Convert the indexes there and back","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  nativeToUnicode,\n  unicodeToNative,\n} from \"string-convert-indexes\";\n\nconst source = \"\\ud834\\udf06aa\";\nconst selection = { start: 2, end: 3, metadata: [\"0\"] };\nconst unicodeSelection = nativeToUnicode(source, selection);\n\nassert.deepEqual(unicodeToNative(source, unicodeSelection), selection);"},"unicode-to-native-indexes.js":{"title":"Convert Unicode indexes into native ones","code":"import { strict as assert } from \"node:assert\";\n\nimport { unicodeToNative } from \"string-convert-indexes\";\n\nassert.deepEqual(unicodeToNative(\"\\uD834\\uDF06aa\", [0, 1, 2]), [0, 2, 3]);"},"zwj-emoji-indexes.js":{"title":"Index a zero-width-joiner emoji sequence","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  nativeToUnicode,\n  unicodeToNative,\n} from \"string-convert-indexes\";\n\nconst text = \"a\\ud83e\\uddd1\\u200d\\ud83e\\udd1d\\u200d\\ud83e\\uddd1b\";\n\nassert.deepEqual(nativeToUnicode(text, [1, 2, 8, 9]), [1, 1, 1, 2]);\nassert.equal(unicodeToNative(text, 2), 9);"}},"string-dashes":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertAll } from \"string-dashes\";\n\nassert.deepEqual(\n  convertAll(\"Dashes come in two sizes - the en dash and the em dash.\", {\n    convertDashes: true,\n    convertEntities: true,\n  }),\n  {\n    result: \"Dashes come in two sizes &mdash; the en dash and the em dash.\",\n    ranges: [[25, 26, \"&mdash;\"]],\n  },\n);"},"ambiguous-hyphen-stays.js":{"title":"An ambiguous hyphen is left alone","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertAll } from \"string-dashes\";\n\nassert.equal(convertAll(\"m-m\").result, \"m-m\");"},"convert-one-em-dash.js":{"title":"Convert one em dash into an entity","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertOne } from \"string-dashes\";\n\nassert.deepEqual(\n  convertOne(\"Dashes come in two sizes - the en dash and the em dash.\", {\n    from: 25,\n    convertDashes: true,\n    convertEntities: true,\n  }),\n  [[25, 26, \"&mdash;\"]],\n);"},"disable-dash-conversion.js":{"title":"Disable the dash conversion","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertAll } from \"string-dashes\";\n\nconst source = \"Read pages 10-12 - then stop.\";\nconst result = convertAll(source, { convertDashes: false });\n\nassert.equal(result.result, source);\nassert.deepEqual(result.ranges, []);"},"en-dash-letter-range.js":{"title":"Convert a letter range into an en dash","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertAll } from \"string-dashes\";\n\nassert.equal(convertAll(\"An A-Z guide\").result, \"An A\\u2013Z guide\");"},"en-dash-number-range.js":{"title":"Convert a number range into an en dash","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertAll } from \"string-dashes\";\n\nassert.equal(convertAll(\"Read pages 10-12.\").result, \"Read pages 10\\u201312.\");"},"math-minus-as-en-dash.js":{"title":"Convert a maths minus into an en dash","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertAll } from \"string-dashes\";\n\nassert.equal(convertAll(\"5 - 2 = 3\").result, \"5 \\u2013 2 = 3\");"},"offset-callback.js":{"title":"Report the index offsets through a callback","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertOne } from \"string-dashes\";\n\nlet totalOffset = 0;\nconst ranges = convertOne(\"1-2\", {\n  from: 1,\n  offsetBy: (amount) => {\n    totalOffset += amount;\n  },\n});\n\nassert.deepEqual(ranges, [[1, 2, \"–\"]]);\nassert.equal(totalOffset, 0);"},"supplied-dash-value.js":{"title":"Supply the dash value separately","code":"import { strict as assert } from \"node:assert\";\n\nimport { convertOne } from \"string-dashes\";\n\n// Parsers can supply the logical character separately from their source text.\nassert.deepEqual(\n  convertOne(\"pages 1?2\", {\n    from: 7,\n    to: 8,\n    value: \"-\",\n    convertEntities: true,\n  }),\n  [[7, 8, \"&ndash;\"]],\n);"}},"string-extract-class-names":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"string-extract-class-names\";\n\n// Pass an isolated CSS selector fragment.\nconst str = \"div#brambles.nushes#croodles\";\nconst { res } = extract(str);\nassert.deepEqual(res, [\"#brambles\", \".nushes\", \"#croodles\"]);"},"bracket-notation.js":{"title":"Extract selectors from HTML-style attribute selectors","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"string-extract-class-names\";\n\nconst source = String.raw`td[class=\" alpha \\31 beta \"][class~=gamma][id=_main]`;\n\n// Attribute names use HTML's ASCII-case-insensitive matching. Exact class\n// strings can contain multiple class tokens, and values can use CSS escapes.\nassert.deepEqual(extract(source), {\n  res: [\".alpha\", String.raw`.\\31 beta`, \".gamma\", \"#_main\"],\n  ranges: [\n    [11, 16],\n    [17, 25],\n    [36, 41],\n    [46, 51],\n  ],\n});\n\n// The synthetic dot and hash are not covered by the source ranges."},"contrived-complex.js":{"title":"Non-parsing algorithm can tackle really dodgy CSS","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"string-extract-class-names\";\n\n// probably invalid input, but works anyway:\nassert.deepEqual(extract(\"?#id1#id2? #id3#id4> p > #id5#id6\").res, [\n  \"#id1\",\n  \"#id2\",\n  \"#id3\",\n  \"#id4\",\n  \"#id5\",\n  \"#id6\",\n]);"},"decode-css-escapes.js":{"title":"Decode CSS selector escapes","code":"import { strict as assert } from \"node:assert\";\n\nimport { decodeCssSelector } from \"string-extract-class-names\";\n\nassert.equal(decodeCssSelector(\".sm\\\\:hover\"), \".sm:hover\");\nassert.equal(decodeCssSelector(\"#\\\\31 23\"), \"#123\");"},"escaped-selector-extraction.js":{"title":"Extract raw escaped selectors","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"string-extract-class-names\";\n\nassert.deepEqual(extract(\".foo\\\\:bar#baz\"), {\n  res: [\".foo\\\\:bar\", \"#baz\"],\n  ranges: [\n    [0, 9],\n    [9, 13],\n  ],\n});"},"input-boundary.js":{"title":"Isolate a selector prelude before extraction","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"string-extract-class-names\";\n\nconst cssRule =\n  '.real { color: #fff; background: url(\"/icons/icon.svg#mark\"); content: \".not-a-selector\"; }';\n\n// In production, let a CSS parser isolate the selector prelude. This slice keeps\n// the example short; passing the complete rule would also match declaration data.\nconst selectorPrelude = cssRule.slice(0, cssRule.indexOf(\"{\"));\n\nassert.deepEqual(extract(selectorPrelude).res, [\".real\"]);\n\n// HTML character references belong to the HTML parser and must be decoded there\n// before selector input is constructed. extract() handles CSS escapes instead;\n// it does not decode a literal spelling such as &copy;."},"read-one-selector-token.js":{"title":"Read one selector token at an exact index","code":"import { strict as assert } from \"node:assert\";\n\nimport { readCssSelectorToken } from \"string-extract-class-names\";\n\nassert.deepEqual(readCssSelectorToken(\"a.foo\\\\:bar#baz\", 1), {\n  value: \".foo:bar\",\n  raw: \".foo\\\\:bar\",\n  range: [1, 10],\n});"},"returned-ranges.js":{"title":"Inspect the source ranges of extracted selectors","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"string-extract-class-names\";\n\nconst source = \"div#brambles.nushes#croodles\";\nconst { res, ranges } = extract(source);\n\nassert.deepEqual(ranges, [\n  [3, 12],\n  [12, 19],\n  [19, 28],\n]);\n\nassert.equal(\n  ranges.map(([from, to]) => source.slice(from, to)).join(\"|\"),\n  res.join(\"|\"),\n);"},"with-space.js":{"title":"Processes whole CSS selectors","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"string-extract-class-names\";\n\nassert.deepEqual(extract(\"div.first.second#third a[target=_blank]\").res, [\n  \".first\",\n  \".second\",\n  \"#third\",\n]);"}},"string-extract-sass-vars":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { extractVars } from \"string-extract-sass-vars\";\n\nassert.deepEqual(\n  extractVars(`// all variables are here!!!\n// ------------------------------------------\n$red: #ff6565; // this is red\n// $green: #63ffbd; // no green here\n$yellow: #ffff65; // this is yellow\n$blue: #08f0fd; // this is blue\n$fontfamily: Helvetica, sans-serif;\n$border: 1px solid #dedede;\n$borderroundedness: 3px;\n$customValue1: tralala;\n$customValue2: tralala;\n// don't mind this comment about #ff6565;\n$customValue3: 10;`),\n  {\n    red: \"#ff6565\",\n    yellow: \"#ffff65\",\n    blue: \"#08f0fd\",\n    fontfamily: \"Helvetica, sans-serif\",\n    border: \"1px solid #dedede\",\n    borderroundedness: \"3px\",\n    customValue1: \"tralala\",\n    customValue2: \"tralala\",\n    customValue3: 10,\n  },\n);"},"ignore-commented-variables.js":{"title":"Ignore variables inside both Sass comment styles","code":"import { strict as assert } from \"node:assert\";\n\nimport { extractVars } from \"string-extract-sass-vars\";\n\nassert.deepEqual(\n  extractVars(`// $disabled: red;\n/* $also-disabled: blue; */\n$enabled: green;`),\n  { enabled: \"green\" },\n);"},"numeric-values.js":{"title":"Convert number-only Sass values to JavaScript numbers","code":"import { strict as assert } from \"node:assert\";\n\nimport { extractVars } from \"string-extract-sass-vars\";\n\nassert.deepEqual(extractVars(\"$columns: 12;\\n$offset: -1.5;\"), {\n  columns: 12,\n  offset: -1.5,\n});"},"opts-cb.js":{"title":"Convert 3-digit color hex codes to 6-digit","code":"import { strict as assert } from \"node:assert\";\nimport { conv } from \"color-shorthand-hex-to-six-digit\";\n\nimport { extractVars } from \"string-extract-sass-vars\";\n\n// import \"color-shorthand-hex-to-six-digit\" to convert three-digit colour hex\n// codes to six-digit:\n\nassert.deepEqual(\n  extractVars(\"$blue: #2af;\", {\n    throwIfEmpty: true,\n    cb: (val) => conv(val), // converts hex codes only, bypasses the rest\n  }),\n  { blue: \"#22aaff\" },\n);"},"quoted-semicolon.js":{"title":"Keep semicolons that occur inside a quoted value","code":"import { strict as assert } from \"node:assert\";\n\nimport { extractVars } from \"string-extract-sass-vars\";\n\nassert.deepEqual(extractVars('$message: \"ready; set; go\";'), {\n  message: \"ready; set; go\",\n});"},"throw-if-empty.js":{"title":"Raises alarm if variables file has been wiped","code":"import { strict as assert } from \"node:assert\";\n\nimport { extractVars } from \"string-extract-sass-vars\";\n\nassert.throws(() =>\n  extractVars(\"\", {\n    throwIfEmpty: true,\n  }),\n);"}},"string-find-heads-tails":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { strFindHeadsTails } from \"string-find-heads-tails\";\n\n// processing an arbitrary, custom templating markup:\nassert.deepEqual(\n  strFindHeadsTails(\n    \"some text %%_var1-%% more text %%_var2_%%\",\n    [\"%%_\", \"%%-\"], // two flavours of heads\n    [\"-%%\", \"_%%\"], // two flavours of tails\n  ),\n  [\n    {\n      headsStartAt: 10,\n      headsEndAt: 13,\n      tailsStartAt: 17,\n      tailsEndAt: 20,\n    },\n    {\n      headsStartAt: 31,\n      headsEndAt: 34,\n      tailsStartAt: 38,\n      tailsEndAt: 41,\n    },\n  ],\n);"},"custom-error-source.js":{"title":"Prefix validation errors with the calling library's name","code":"import { strict as assert } from \"node:assert\";\n\nimport { strFindHeadsTails } from \"string-find-heads-tails\";\n\nassert.throws(\n  () =>\n    strFindHeadsTails(\"before {{ unfinished\", \"{{\", \"}}\", {\n      source: \"template-audit\",\n    }),\n  /template-audit/u,\n);"},"disallow-marker-only-input.js":{"title":"Reject an input made only from one opening marker","code":"import { strict as assert } from \"node:assert\";\n\nimport { strFindHeadsTails } from \"string-find-heads-tails\";\n\nassert.throws(\n  () =>\n    strFindHeadsTails(\"{{\", \"{{\", \"}}\", {\n      allowWholeValueToBeOnlyHeadsOrTails: false,\n    }),\n  /THROW_ID_14/u,\n);"},"from-index.js":{"title":"Start looking for marker pairs at a selected index","code":"import { strict as assert } from \"node:assert\";\n\nimport { strFindHeadsTails } from \"string-find-heads-tails\";\n\nassert.deepEqual(\n  strFindHeadsTails(\"{{ first }} and {{ second }}\", \"{{\", \"}}\", {\n    fromIndex: 14,\n  }),\n  [\n    {\n      headsStartAt: 16,\n      headsEndAt: 18,\n      tailsStartAt: 26,\n      tailsEndAt: 28,\n    },\n  ],\n);"},"relaxed-api.js":{"title":"Return an empty result for unusable marker inputs","code":"import { strict as assert } from \"node:assert\";\n\nimport { strFindHeadsTails } from \"string-find-heads-tails\";\n\nassert.deepEqual(\n  strFindHeadsTails(\"before {{ value }}\", [], \"}}\", { relaxedAPI: true }),\n  [],\n);"},"strict-marker-pairs.js":{"title":"Require each opening marker to use the tail at the same array index","code":"import { strict as assert } from \"node:assert\";\n\nimport { strFindHeadsTails } from \"string-find-heads-tails\";\n\nassert.throws(\n  () =>\n    strFindHeadsTails(\n      \"before %%_value-%% after\",\n      [\"%%_\", \"%%-\"],\n      [\"_%%\", \"-%%\"],\n      { matchHeadsAndTailsStrictlyInPairsByTheirOrder: true },\n    ),\n  /THROW_ID_17/u,\n);"},"tolerate-unmatched-markers.js":{"title":"Return completed pairs without throwing on an unmatched marker","code":"import { strict as assert } from \"node:assert\";\n\nimport { strFindHeadsTails } from \"string-find-heads-tails\";\n\nassert.deepEqual(\n  strFindHeadsTails(\"{{ complete }} and {{ unfinished\", \"{{\", \"}}\", {\n    throwWhenSomethingWrongIsDetected: false,\n  }),\n  [\n    {\n      headsStartAt: 0,\n      headsEndAt: 2,\n      tailsStartAt: 12,\n      tailsEndAt: 14,\n    },\n  ],\n);"}},"string-find-malformed":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { findMalformed } from \"string-find-malformed\";\n\n// Below, we look for dodgy cases of `<!--`\nconst gathered = [];\nfindMalformed(\n  \"<div><!-something--></div>\",\n  \"<!--\",\n  // your callback function:\n  (obj) => {\n    gathered.push(obj);\n  },\n  {\n    maxDistance: 1, // Levenshtein distance\n  },\n);\nassert.deepEqual(gathered, [\n  {\n    idxFrom: 5,\n    idxTo: 8,\n  },\n]);"},"add-index-offset.js":{"title":"Offset the reported indexes","code":"import { strict as assert } from \"node:assert\";\n\nimport { findMalformed } from \"string-find-malformed\";\n\nconst findings = [];\n\nfindMalformed(\n  \"<div><!-something--></div>\",\n  \"<!--\",\n  (finding) => findings.push(finding),\n  {\n    maxDistance: 1,\n    stringOffset: 100,\n  },\n);\n\nassert.deepEqual(findings, [{ idxFrom: 105, idxTo: 108 }]);"},"exact-match-is-not-reported.js":{"title":"An exact match is not reported","code":"import { strict as assert } from \"node:assert\";\n\nimport { findMalformed } from \"string-find-malformed\";\n\nconst findings = [];\n\nfindMalformed(\"<div><!-- note --></div>\", \"<!--\", (finding) =>\n  findings.push(finding),\n);\n\nassert.deepEqual(findings, []);"},"extended-distance.js":{"title":"Widen the allowed edit distance","code":"import { strict as assert } from \"node:assert\";\n\nimport { findMalformed } from \"string-find-malformed\";\n\nconst findings = [];\n\nfindMalformed(\"abcabcd.f\", \"abcdef\", (finding) => findings.push(finding), {\n  maxDistance: 2,\n});\n\nassert.deepEqual(findings, [{ idxFrom: 3, idxTo: 9 }]);"},"ignore-whitespace.js":{"title":"Ignore the whitespace between characters","code":"import { strict as assert } from \"node:assert\";\n\nimport { findMalformed } from \"string-find-malformed\";\n\nconst findings = [];\n\nfindMalformed(\"< ! - -\", \"<!--\", (finding) => findings.push(finding), {\n  ignoreWhitespace: true,\n});\n\nassert.deepEqual(findings, [{ idxFrom: 0, idxTo: 7 }]);"},"require-adjacent-characters.js":{"title":"Require the characters to be adjacent","code":"import { strict as assert } from \"node:assert\";\n\nimport { findMalformed } from \"string-find-malformed\";\n\nconst findings = [];\n\nfindMalformed(\"< ! - -\", \"<!--\", (finding) => findings.push(finding), {\n  ignoreWhitespace: false,\n});\n\nassert.deepEqual(findings, []);"}},"string-fix-broken-named-entities":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixEnt } from \"string-fix-broken-named-entities\";\n\nconst source = \"&nsp;x&nsp;y&nsp;\";\n\n// returns Ranges notation, see codsen.com/ranges/\nassert.deepEqual(fixEnt(source), [\n  [0, 5, \"&nbsp;\"],\n  [6, 11, \"&nbsp;\"],\n  [12, 17, \"&nbsp;\"],\n]);"},"apply-ranges.js":{"title":"Apply the returned ranges to repair the source string","code":"import { strict as assert } from \"node:assert\";\nimport { rApply } from \"ranges-apply\";\n\nimport { fixEnt } from \"string-fix-broken-named-entities\";\n\nconst source = \"&nsp;x&nsp;y&nsp;\";\n\nassert.equal(rApply(source, fixEnt(source)), \"&nbsp;x&nbsp;y&nbsp;\");"},"catch-healthy-entities.js":{"title":"Report healthy named-entity ranges","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixEnt } from \"string-fix-broken-named-entities\";\n\nconst healthy = [];\nconst ranges = fixEnt(\"A&nbsp;B &nsp; C\", {\n  entityCatcherCb: (from, to) => healthy.push([from, to]),\n});\n\nassert.deepEqual(healthy, [[1, 7]]);\nassert.equal(ranges.length, 1);\nassert.equal(ranges[0][2], \"&nbsp;\");"},"decode-entities.js":{"title":"Decode healthy named entities","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixEnt } from \"string-fix-broken-named-entities\";\n\nassert.deepEqual(fixEnt(\"Price: &pound;10\", { decode: true }), [[7, 14, \"£\"]]);"},"decode-numeric-entities.js":{"title":"Decode decimal and hexadecimal numeric entities","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixEnt } from \"string-fix-broken-named-entities\";\n\nassert.deepEqual(fixEnt(\"&#163; and &#xA3;\", { decode: true }), [\n  [0, 6, \"£\"],\n  [11, 17, \"£\"],\n]);"},"metadata-callback.js":{"title":"Map findings into custom callback results","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixEnt } from \"string-fix-broken-named-entities\";\n\nassert.deepEqual(\n  fixEnt(\"before &nsp; after\", {\n    cb: (finding) => ({\n      rule: finding.ruleName,\n      replacement: finding.rangeValEncoded,\n      from: finding.rangeFrom,\n      to: finding.rangeTo,\n    }),\n  }),\n  [\n    {\n      rule: \"bad-html-entity-malformed-nbsp\",\n      replacement: \"&nbsp;\",\n      from: 7,\n      to: 12,\n    },\n  ],\n);"},"multiple-encoding.js":{"title":"Repair repeatedly encoded entities","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixEnt } from \"string-fix-broken-named-entities\";\n\nassert.deepEqual(fixEnt(\"text&amp;amp;nbsp;text\"), [[4, 18, \"&nbsp;\"]]);"},"progress.js":{"title":"Observe scan progress","code":"import { strict as assert } from \"node:assert\";\n\nimport { fixEnt } from \"string-fix-broken-named-entities\";\n\nconst percentages = [];\nconst source = \"text &ang text&ang text \".repeat(10);\n\nfixEnt(source, {\n  progressFn: (percentage) => percentages.push(percentage),\n});\n\nassert.equal(percentages.length > 0, true);\nassert.equal(\n  percentages.every((value) => value >= 0 && value <= 100),\n  true,\n);"},"rule-names.js":{"title":"Access the complete public rule-name list","code":"import { strict as assert } from \"node:assert\";\n\nimport { allRules } from \"string-fix-broken-named-entities\";\n\nassert.equal(allRules.includes(\"bad-html-entity-malformed-nbsp\"), true);\nassert.equal(allRules.includes(\"bad-html-entity-multiple-encoding\"), true);\nassert.equal(new Set(allRules).size, allRules.length);"},"sift-raw-ampersands-from-entities.js":{"title":"Sift raw ampersands in a string from broken character references","code":"// encode those raw ampersands and fix broken character references\n\nimport { strict as assert } from \"node:assert\";\nimport { rApply } from \"ranges-apply\";\n\nimport { fixEnt } from \"string-fix-broken-named-entities\";\n\nconst source = \"&&nsp;&&nsp;&\";\n\nconst indexesOfRawAmpersands = [];\n\n// fixEnt() returns Ranges (see codsen.com/ranges/)\nconst resultRanges = fixEnt(source, {\n  textAmpersandCatcherCb: (idx) => indexesOfRawAmpersands.push(idx),\n});\n\n// check the ranges - all broken NBSP's were fixed:\nassert.deepEqual(resultRanges, [\n  [1, 6, \"&nbsp;\"],\n  [7, 12, \"&nbsp;\"],\n]);\n\n// check the positions of reported raw ampersands:\nassert.equal(indexesOfRawAmpersands.join(\",\"), \"0,6,12\");\n\n// replace each character at these positions: 0, 6 and 12\n// with string \"&amp;\" - in terms of Ranges, it's a matter\n// of building a Ranges array:\nconst replacementRanges = indexesOfRawAmpersands.map((idx) => [\n  idx,\n  idx + 1,\n  \"&amp;\",\n]);\n// push them into resultRanges as well:\nreplacementRanges.forEach((range) => {\n  resultRanges.push(range);\n});\n\n// apply Ranges onto a string - all amendments at once!\nconst finalResultStr = rApply(source, resultRanges);\n\n// check result\nassert.equal(finalResultStr, \"&amp;&nbsp;&amp;&nbsp;&amp;\");\n\n// Voilà! We fixed broken entities and encoded raw ampersands"}},"string-left-right":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  chompLeft,\n  chompRight,\n  left,\n  leftSeq,\n  leftStopAtNewLines,\n  right,\n  rightSeq,\n  rightStopAtNewLines,\n} from \"string-left-right\";\n\n// get the closest non-whitespace character to the left of \"d\" (which itself\n// is at string index 6)\nconst str = \"abc   def\";\n//             |   |\n//           012345678\n\nassert.equal(\n  `next non-whitespace character to the left of ${str[6]} (index 6) is ${\n    str[left(str, 6)]\n  } (index ${left(str, 6)})`,\n  \"next non-whitespace character to the left of d (index 6) is c (index 2)\",\n);"},"case-insensitive-sequence.js":{"title":"Match a character sequence without regard to letter case","code":"import { strict as assert } from \"node:assert\";\n\nimport { rightSeq } from \"string-left-right\";\n\nassert.deepEqual(rightSeq(\"X A b C\", 0, { i: true }, \"a\", \"B\", \"c\"), {\n  gaps: [\n    [1, 2],\n    [3, 4],\n    [5, 6],\n  ],\n  leftmostChar: 2,\n  rightmostChar: 6,\n});"},"chomp-left.js":{"title":"Match repeated sequences on the left and include nearby whitespace","code":"import { strict as assert } from \"node:assert\";\n\nimport { chompLeft } from \"string-left-right\";\n\nassert.equal(chompLeft(\"a  b c b c  x y\", 12, \"b\", \"c\"), 2);"},"chomp-modes.js":{"title":"Control how chomp functions include surrounding whitespace","code":"import { strict as assert } from \"node:assert\";\n\nimport { chompLeft, chompRight } from \"string-left-right\";\n\nconst leftSource = \"a\\n  b c b c  x y\";\n\nassert.equal(chompLeft(leftSource, 13, { mode: 0 }, \"b\", \"c\"), 2);\nassert.equal(chompLeft(leftSource, 13, { mode: 1 }, \"b\", \"c\"), 4);\nassert.equal(chompLeft(leftSource, 13, { mode: 2 }, \"b\", \"c\"), 2);\nassert.equal(chompLeft(leftSource, 13, { mode: 3 }, \"b\", \"c\"), 1);\n\nconst rightSource = \"a b c d  c d  \\nx\";\n\nassert.equal(chompRight(rightSource, 2, { mode: 0 }, \"c\", \"d\"), 14);\nassert.equal(chompRight(rightSource, 2, { mode: 1 }, \"c\", \"d\"), 12);\nassert.equal(chompRight(rightSource, 2, { mode: 2 }, \"c\", \"d\"), 14);\nassert.equal(chompRight(rightSource, 2, { mode: 3 }, \"c\", \"d\"), 15);"},"chomp-right.js":{"title":"Match repeated sequences on the right and include nearby whitespace","code":"import { strict as assert } from \"node:assert\";\n\nimport { chompRight } from \"string-left-right\";\n\nassert.equal(chompRight(\"a b c d  c d  x\", 2, \"c\", \"d\"), 13);"},"left-sequence.js":{"title":"Match a whitespace-tolerant character sequence on the left","code":"import { strict as assert } from \"node:assert\";\n\nimport { leftSeq } from \"string-left-right\";\n\nassert.deepEqual(leftSeq(\"a  b  c X\", 8, \"a\", \"b\", \"c\"), {\n  gaps: [\n    [1, 3],\n    [4, 6],\n    [7, 8],\n  ],\n  leftmostChar: 0,\n  rightmostChar: 6,\n});"},"optional-repeated-sequence-value.js":{"title":"Combine optional and repeated sequence flags","code":"import { strict as assert } from \"node:assert\";\n\nimport { rightSeq } from \"string-left-right\";\n\nassert.deepEqual(rightSeq(\"X b\", 0, \"a?*\", \"b\"), {\n  gaps: [[1, 2]],\n  leftmostChar: 2,\n  rightmostChar: 2,\n});"},"optional-sequence-value.js":{"title":"Mark one sequence value as optional with a question mark","code":"import { strict as assert } from \"node:assert\";\n\nimport { rightSeq } from \"string-left-right\";\n\nassert.deepEqual(rightSeq(\"X a c\", 0, \"a\", \"b?\", \"c\"), {\n  gaps: [\n    [1, 2],\n    [3, 4],\n  ],\n  leftmostChar: 2,\n  rightmostChar: 4,\n});"},"repeated-sequence-value.js":{"title":"Match one or more repeated sequence values with an asterisk","code":"import { strict as assert } from \"node:assert\";\n\nimport { rightSeq } from \"string-left-right\";\n\nassert.deepEqual(rightSeq(\"X a a a b\", 0, \"a*\", \"b\"), {\n  gaps: [\n    [1, 2],\n    [3, 4],\n    [5, 6],\n    [7, 8],\n  ],\n  leftmostChar: 2,\n  rightmostChar: 8,\n});"},"right-sequence.js":{"title":"Match a whitespace-tolerant character sequence on the right","code":"import { strict as assert } from \"node:assert\";\n\nimport { rightSeq } from \"string-left-right\";\n\nassert.deepEqual(rightSeq(\"X a  b  c\", 0, \"a\", \"b\", \"c\"), {\n  gaps: [\n    [1, 2],\n    [3, 5],\n    [6, 8],\n  ],\n  leftmostChar: 2,\n  rightmostChar: 8,\n});"},"right.js":{"title":"Find the nearest non-whitespace character on the right","code":"import { strict as assert } from \"node:assert\";\n\nimport { right } from \"string-left-right\";\n\nconst source = \"abc   def\";\n\nassert.equal(right(source, 2), 6);\nassert.equal(source[right(source, 2)], \"d\");"},"stop-at-newlines.js":{"title":"Treat a newline as a stopping point in either direction","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  left,\n  leftStopAtNewLines,\n  right,\n  rightStopAtNewLines,\n} from \"string-left-right\";\n\nconst source = \"abc\\n  def\";\n\nassert.equal(right(source, 2), 6);\nassert.equal(rightStopAtNewLines(source, 2), 3);\nassert.equal(left(source, 6), 2);\nassert.equal(leftStopAtNewLines(source, 6), 3);"},"stop-at-non-breaking-spaces.js":{"title":"Treat a raw non-breaking space as a stopping point","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  left,\n  leftStopAtRawNbsp,\n  right,\n  rightStopAtRawNbsp,\n} from \"string-left-right\";\n\nconst source = \"abc\\u00a0  def\";\n\nassert.equal(right(source, 2), 6);\nassert.equal(rightStopAtRawNbsp(source, 2), 3);\nassert.equal(left(source, 6), 2);\nassert.equal(leftStopAtRawNbsp(source, 6), 3);"}},"string-match-left-right":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { matchRight } from \"string-match-left-right\";\n\nassert.equal(matchRight(\"abcdefghi\", 3, [\"ef\", \"zz\"]), \"ef\");"},"callback-context.js":{"title":"Inspect the character and remainder after a match","code":"import { strict as assert } from \"node:assert\";\n\nimport { matchRight } from \"string-match-left-right\";\n\nlet context;\nconst result = matchRight(\"abcdef\", 2, \"de\", {\n  cb: (outsideCharacter, remainder, index) => {\n    context = { outsideCharacter, remainder, index };\n    return true;\n  },\n});\n\nassert.equal(result, \"de\");\nassert.deepEqual(context, {\n  outsideCharacter: \"f\",\n  remainder: \"f\",\n  index: 5,\n});"},"callback-veto.js":{"title":"Let a callback veto an otherwise successful match","code":"import { strict as assert } from \"node:assert\";\n\nimport { matchLeft } from \"string-match-left-right\";\n\nassert.equal(matchLeft(\"<a class=\", 8, \"class\"), \"class\");\nassert.equal(\n  matchLeft(\"<a class=\", 8, \"class\", {\n    cb: (characterBefore) => characterBefore === \"\\n\",\n  }),\n  false,\n);"},"case-insensitive.js":{"title":"Match without letter-case sensitivity","code":"import { strict as assert } from \"node:assert\";\n\nimport { matchRight } from \"string-match-left-right\";\n\nassert.equal(matchRight(\"abcdef\", 2, \"D\"), false);\nassert.equal(matchRight(\"abcdef\", 2, \"D\", { i: true }), \"D\");"},"cb.js":{"title":"The Callback Use","code":"import { strict as assert } from \"node:assert\";\n\nimport {\n  matchLeft,\n  matchLeftIncl,\n  matchRight,\n  matchRightIncl,\n} from \"string-match-left-right\";\n\n// imagine you looped the string and wanted to catch where does attribute \"class\" start\n// and end (not to mention to ensure that it's a real attribute, not something ending with this\n// string \"class\").\n// You catch \"=\", an index number 8.\n// This library can check, is \"class\" to the left of it and feed what's to the left of it\n// to your supplied callback function, which happens to be a checker \"is it a space\":\nfunction isSpace(char) {\n  return typeof char === \"string\" && char.trim() === \"\";\n}\n\nassert.equal(\n  matchLeft('<a class=\"something\">', 8, \"class\", { cb: isSpace }),\n  \"class\",\n);"},"default-next-index.js":{"title":"Advance to the next string index","code":"import { strict as assert } from \"node:assert\";\n\nimport { defaultGetNextIdx } from \"string-match-left-right\";\n\nassert.equal(defaultGetNextIdx(4), 5);"},"end-of-line-matcher.js":{"title":"Match the start or end of a string","code":"import { strict as assert } from \"node:assert\";\n\nimport { matchLeft, matchRight } from \"string-match-left-right\";\n\nconst endOfLine = () => \"EOL\";\n\nassert.equal(matchLeft(\"a\", 0, endOfLine), \"EOL\");\nassert.equal(matchRight(\"a\", 0, endOfLine), \"EOL\");\n\nassert.equal(\n  matchLeft(\" a\", 1, endOfLine, { trimBeforeMatching: true }),\n  \"EOL\",\n);"},"match-left-inclusive.js":{"title":"Include the indexed character in a left-side match","code":"import { strict as assert } from \"node:assert\";\n\nimport { matchLeftIncl } from \"string-match-left-right\";\n\nassert.equal(matchLeftIncl(\"abcdefghi\", 3, [\"bcd\"]), \"bcd\");"},"match-left.js":{"title":"Match a value immediately to the left of an index","code":"import { strict as assert } from \"node:assert\";\n\nimport { matchLeft } from \"string-match-left-right\";\n\nassert.equal(matchLeft(\"abcdefghi\", 3, [\"ab\", \"zz\"]), false);"},"match-right-inclusive.js":{"title":"Include the indexed character in a right-side match","code":"import { strict as assert } from \"node:assert\";\n\nimport { matchRightIncl } from \"string-match-left-right\";\n\nassert.equal(matchRightIncl(\"abcdefghi\", 3, [\"def\", \"zzz\"]), \"def\");"},"mismatch-boundaries.js":{"title":"Require boundary characters and choose hungry matching","code":"import { strict as assert } from \"node:assert\";\n\nimport { matchRight } from \"string-match-left-right\";\n\n// The first character mismatches. Hungry mode lets the matcher keep looking.\nassert.equal(\n  matchRight(\"ab.def\", 1, \"cde\", { maxMismatches: 1, hungry: true }),\n  \"cde\",\n);\nassert.equal(\n  matchRight(\"ab.def\", 1, \"cde\", {\n    maxMismatches: 1,\n    hungry: true,\n    firstMustMatch: true,\n  }),\n  false,\n);\n\n// The final character mismatches, so lastMustMatch rejects it.\nassert.equal(matchRight(\"abcd.f\", 1, \"cde\", { maxMismatches: 1 }), \"cde\");\nassert.equal(\n  matchRight(\"abcd.f\", 1, \"cde\", {\n    maxMismatches: 1,\n    lastMustMatch: true,\n  }),\n  false,\n);"},"mismatch-tolerance.js":{"title":"Tolerate a missing character","code":"import { strict as assert } from \"node:assert\";\n\nimport { matchRight } from \"string-match-left-right\";\n\nassert.equal(matchRight(\"a<!->z\", 0, \"<!-->\"), false);\nassert.equal(matchRight(\"a<!->z\", 0, \"<!-->\", { maxMismatches: 1 }), \"<!-->\");"},"trim-selected-characters.js":{"title":"Skip selected characters before matching","code":"import { strict as assert } from \"node:assert\";\n\nimport { matchRight } from \"string-match-left-right\";\n\nassert.equal(matchRight(\"</div>\", 0, \"div\"), false);\nassert.equal(\n  matchRight(\"</div>\", 0, \"div\", { trimCharsBeforeMatching: \"/\" }),\n  \"div\",\n);"},"trim-whitespace.js":{"title":"Skip whitespace before matching","code":"import { strict as assert } from \"node:assert\";\n\nimport { matchRight } from \"string-match-left-right\";\n\nassert.equal(matchRight(\"ab      cdef\", 1, \"cd\"), false);\nassert.equal(\n  matchRight(\"ab      cdef\", 1, \"cd\", { trimBeforeMatching: true }),\n  \"cd\",\n);"}},"string-process-comma-separated":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { processCommaSep } from \"string-process-comma-separated\";\n\nconst gatheredChunks = [];\n\n// it's a callback-interface:\nprocessCommaSep(\"alpha,beta\", {\n  cb: (idxFrom, idxTo) => {\n    gatheredChunks.push([idxFrom, idxTo]);\n  },\n});\n\nassert.deepEqual(gatheredChunks, [\n  [0, 5],\n  [6, 10],\n]);"},"bounded-slice-with-offset.js":{"title":"Process a bounded slice and offset reported indexes","code":"import { strict as assert } from \"node:assert\";\n\nimport { processCommaSep } from \"string-process-comma-separated\";\n\nconst chunks = [];\n\nprocessCommaSep(\"xxa,bzz\", {\n  from: 2,\n  to: 5,\n  offset: 10,\n  cb: (from, to) => chunks.push([from, to]),\n});\n\nassert.deepEqual(chunks, [\n  [12, 13],\n  [14, 15],\n]);"},"chunks-only.js":{"title":"Gather chunks without requesting diagnostics","code":"import { strict as assert } from \"node:assert\";\n\nimport { processCommaSep } from \"string-process-comma-separated\";\n\nconst chunks = [];\n\nprocessCommaSep(\"alpha,beta,gamma\", {\n  cb: (from, to) => chunks.push([from, to]),\n});\n\nassert.deepEqual(chunks, [\n  [0, 5],\n  [6, 10],\n  [11, 16],\n]);"},"custom-separator.js":{"title":"Use a custom separator","code":"import { strict as assert } from \"node:assert\";\n\nimport { processCommaSep } from \"string-process-comma-separated\";\n\nconst chunks = [];\nconst errors = [];\n\nprocessCommaSep(\".50%.50%.\", {\n  separator: \".\",\n  cb: (from, to) => chunks.push([from, to]),\n  errCb: (ranges, message, fixable) =>\n    errors.push({ ranges, message, fixable }),\n});\n\nassert.deepEqual(chunks, [\n  [1, 4],\n  [5, 8],\n]);\nassert.equal(errors.length, 2);\nassert.equal(errors[0].message, \"Remove separator.\");"},"edge-whitespace.js":{"title":"Allow leading and trailing whitespace","code":"import { strict as assert } from \"node:assert\";\n\nimport { processCommaSep } from \"string-process-comma-separated\";\n\nconst chunks = [];\nconst errors = [];\n\nprocessCommaSep(\" .jpg \", {\n  leadingWhitespaceOK: true,\n  trailingWhitespaceOK: true,\n  cb: (from, to) => chunks.push([from, to]),\n  errCb: (ranges, message) => errors.push({ ranges, message }),\n});\n\nassert.deepEqual(chunks, [[1, 5]]);\nassert.equal(errors.length, 0);"},"inner-whitespace.js":{"title":"Configure whitespace inside a chunk","code":"import { strict as assert } from \"node:assert\";\n\nimport { processCommaSep } from \"string-process-comma-separated\";\n\nfunction collect(innerWhitespaceAllowed) {\n  const errors = [];\n  processCommaSep(\"abc,def ghi,jkl\", {\n    innerWhitespaceAllowed,\n    errCb: (ranges, message, fixable) =>\n      errors.push({ ranges, message, fixable }),\n  });\n  return errors;\n}\n\nassert.deepEqual(collect(false), [\n  {\n    ranges: [[7, 8]],\n    message: \"Bad whitespace.\",\n    fixable: false,\n  },\n]);\nassert.equal(collect(true).length, 0);"},"one-space-after-comma.js":{"title":"Allow one space after a comma","code":"import { strict as assert } from \"node:assert\";\n\nimport { processCommaSep } from \"string-process-comma-separated\";\n\nconst errors = [];\n\nprocessCommaSep(\"50%,  50%\", {\n  oneSpaceAfterCommaOK: true,\n  errCb: (ranges, message, fixable) =>\n    errors.push({ ranges, message, fixable }),\n});\n\n// Only the second of the two spaces needs removal.\nassert.deepEqual(errors, [\n  {\n    ranges: [[5, 6]],\n    message: \"Remove whitespace.\",\n    fixable: true,\n  },\n]);"}},"string-range-expander":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { expander } from \"string-range-expander\";\n\n// let's say we have picked the \"zzzz\" index range - [16, 20]\n// \"something>\\n\\t    zzzz <here\"\n//                    |   |\n//                  from  to\n//\n// PS. \"\\n\" and \"\\t\" take up a single character's length\n\nassert.deepEqual(\n  expander({\n    str: \"something>\\n\\t    zzzz <here\",\n    from: 16,\n    to: 20,\n    ifRightSideIncludesThisThenCropTightly: \"<\",\n  }),\n  [10, 21],\n);"},"crop-left-marker.js":{"title":"Include configured left-side marker characters in the range","code":"import { strict as assert } from \"node:assert\";\n\nimport { expander } from \"string-range-expander\";\n\nassert.deepEqual(\n  expander({\n    str: \"something>\\n\\t    zzzz <here\",\n    from: 16,\n    to: 20,\n    ifLeftSideIncludesThisCropItToo: \"\\n\\t\",\n  }),\n  [10, 20],\n);"},"crop-right-marker.js":{"title":"Include a configured right-side marker in the range","code":"import { strict as assert } from \"node:assert\";\n\nimport { expander } from \"string-range-expander\";\n\nassert.deepEqual(\n  expander({\n    str: \"  ;  aaa  ;  \",\n    from: 5,\n    to: 8,\n    ifRightSideIncludesThisCropItToo: \";\",\n  }),\n  [4, 12],\n);"},"extend-left-only.js":{"title":"Expand whitespace only on the left side","code":"import { strict as assert } from \"node:assert\";\n\nimport { expander } from \"string-range-expander\";\n\nassert.deepEqual(\n  expander({\n    str: \"a>     <b\",\n    from: 4,\n    to: 5,\n    extendToOneSide: \"left\",\n  }),\n  [3, 5],\n);"},"extend-right-only.js":{"title":"Expand whitespace only on the right side","code":"import { strict as assert } from \"node:assert\";\n\nimport { expander } from \"string-range-expander\";\n\nassert.deepEqual(\n  expander({\n    str: \"a>     <b\",\n    from: 4,\n    to: 5,\n    extendToOneSide: \"right\",\n  }),\n  [4, 6],\n);"},"prevent-accidental-concatenation.js":{"title":"Request one replacement space when deletion would join words","code":"import { strict as assert } from \"node:assert\";\n\nimport { expander } from \"string-range-expander\";\n\nassert.deepEqual(\n  expander({\n    str: \"first second\",\n    from: 5,\n    to: 6,\n    addSingleSpaceToPreventAccidentalConcatenation: true,\n  }),\n  [5, 6, \" \"],\n);"},"prevent-international-concatenation.js":{"title":"Preserve a separator between international words","code":"import { strict as assert } from \"node:assert\";\n\nimport { expander } from \"string-range-expander\";\n\nassert.deepEqual(\n  expander({\n    str: \"你 你\",\n    from: 1,\n    to: 2,\n    addSingleSpaceToPreventAccidentalConcatenation: true,\n  }),\n  [1, 2, \" \"],\n);"},"tight-left-crop.js":{"title":"Crop tightly when a configured marker appears on the left","code":"import { strict as assert } from \"node:assert\";\n\nimport { expander } from \"string-range-expander\";\n\nassert.deepEqual(\n  expander({\n    str: \"a>     <b\",\n    from: 3,\n    to: 6,\n    ifLeftSideIncludesThisThenCropTightly: \">\",\n  }),\n  [2, 7],\n);"},"wipe-left-whitespace.js":{"title":"Include all adjacent whitespace on the left","code":"import { strict as assert } from \"node:assert\";\n\nimport { expander } from \"string-range-expander\";\n\nassert.deepEqual(\n  expander({\n    str: \"aaa  bbb  ccc\",\n    from: 5,\n    to: 8,\n    wipeAllWhitespaceOnLeft: true,\n  }),\n  [3, 9],\n);"},"wipe-right-whitespace.js":{"title":"Include all adjacent whitespace on the right","code":"import { strict as assert } from \"node:assert\";\n\nimport { expander } from \"string-range-expander\";\n\nassert.deepEqual(\n  expander({\n    str: \"aaa  bbb  ccc\",\n    from: 5,\n    to: 8,\n    wipeAllWhitespaceOnRight: true,\n  }),\n  [4, 10],\n);"}},"string-remove-duplicate-heads-tails":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { remDup } from \"string-remove-duplicate-heads-tails\";\n\nassert.equal(\n  remDup(\"{{ Hi {{ first_name }}! }}\", {\n    heads: \"{{ \",\n    tails: \" }}\",\n  }),\n  \"Hi {{ first_name }}!\",\n);"},"default-markers.js":{"title":"Remove a duplicate outer layer with the default markers","code":"import { strict as assert } from \"node:assert\";\n\nimport { remDup } from \"string-remove-duplicate-heads-tails\";\n\nassert.equal(remDup(\"{{ {{ customer }} }}\"), \"{{ customer }}\");"},"multiple-marker-pairs.js":{"title":"Remove mixed outer wrappers while preserving inner variables","code":"import { strict as assert } from \"node:assert\";\n\nimport { remDup } from \"string-remove-duplicate-heads-tails\";\n\nassert.equal(\n  remDup(\"?? ((( ?? first !! ?? last !! ))) !!\", {\n    heads: [\"??\", \"(((\"],\n    tails: [\"!!\", \")))\"],\n  }),\n  \"?? first !! ?? last !!\",\n);"},"remove-empty-edge-wrappers.js":{"title":"Remove empty marker pairs around meaningful text","code":"import { strict as assert } from \"node:assert\";\n\nimport { remDup } from \"string-remove-duplicate-heads-tails\";\n\nassert.equal(\n  remDup(\"((())) article ((()))\", {\n    heads: \"(((\",\n    tails: \")))\",\n  }),\n  \"article\",\n);"},"unmatched-wrapper.js":{"title":"Leave content intact unless both outer markers match","code":"import { strict as assert } from \"node:assert\";\n\nimport { remDup } from \"string-remove-duplicate-heads-tails\";\n\nassert.equal(\n  remDup(\"{{ customer\", {\n    heads: \"{{\",\n    tails: \"}}\",\n  }),\n  \"{{ customer\",\n);"}},"string-remove-thousand-separators":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { remSep } from \"string-remove-thousand-separators\";\n\nassert.equal(remSep(\"1,000,000.00\"), \"1000000.00\");"},"default-decimal-padding.js":{"title":"Pad a single decimal digit while removing thousand separators","code":"import { strict as assert } from \"node:assert\";\n\nimport { remSep } from \"string-remove-thousand-separators\";\n\nassert.equal(remSep(\"100,000.2\"), \"100000.20\");\nassert.equal(remSep(\"100 000,2\"), \"100000,20\");\nassert.equal(remSep(\"100'000.2\"), \"100000.20\");"},"disable-decimal-padding.js":{"title":"Leave a single decimal place unpadded","code":"import { strict as assert } from \"node:assert\";\n\nimport { remSep } from \"string-remove-thousand-separators\";\n\nassert.equal(\n  remSep(\"1,000.2\", { padSingleDecimalPlaceNumbers: false }),\n  \"1000.2\",\n);"},"force-uk-style.js":{"title":"Convert a comma decimal separator to a dot","code":"import { strict as assert } from \"node:assert\";\n\nimport { remSep } from \"string-remove-thousand-separators\";\n\nassert.equal(remSep(\"100 000,9\", { forceUKStyle: true }), \"100000.90\");"},"integer-with-spaces.js":{"title":"Remove spaced thousand separators when no decimal separator is present","code":"import { strict as assert } from \"node:assert\";\n\nimport { remSep } from \"string-remove-thousand-separators\";\n\nassert.equal(remSep(\"100 000 000 000\"), \"100000000000\");"},"keep-thousand-separators.js":{"title":"Keep thousand separators while still normalising the outer quotes","code":"import { strict as assert } from \"node:assert\";\n\nimport { remSep } from \"string-remove-thousand-separators\";\n\nassert.equal(\n  remSep('\"1,000,000.00\"', { removeThousandSeparatorsFromNumbers: false }),\n  \"1,000,000.00\",\n);"},"leave-text-unchanged.js":{"title":"Leave a value unchanged when it contains non-numeric text","code":"import { strict as assert } from \"node:assert\";\n\nimport { remSep } from \"string-remove-thousand-separators\";\n\nconst source = \"The price is 1,999.9\";\n\nassert.equal(remSep(source), source);"},"mixed-separators.js":{"title":"Preserve a number whose separators are ambiguous","code":"import { strict as assert } from \"node:assert\";\n\nimport { remSep } from \"string-remove-thousand-separators\";\n\nconst input = \"100,000,000.000\";\n\nassert.equal(remSep(input), input);"},"russian-notation.js":{"title":"Remove spaces used as thousand separators","code":"import { strict as assert } from \"node:assert\";\n\nimport { remSep } from \"string-remove-thousand-separators\";\n\nassert.equal(remSep(\"1 000 000,00\"), \"1000000,00\");"},"swiss-notation.js":{"title":"Remove apostrophes used as thousand separators","code":"import { strict as assert } from \"node:assert\";\n\nimport { remSep } from \"string-remove-thousand-separators\";\n\nassert.equal(remSep(\"1'000'000.00\"), \"1000000.00\");"}},"string-remove-widows":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nconst { ranges, res } = removeWidows(\"Some text with many words on one line.\");\n\n// see codsen.com/ranges/\nassert.deepEqual(ranges, [[32, 33, \"&nbsp;\"]]);\n\nassert.equal(res, \"Some text with many words on one&nbsp;line.\");"},"css-output.js":{"title":"Encode the inserted non-breaking space for CSS","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\"aaa bbb ccc ddd\", {\n    targetLanguage: \"css\",\n    minCharCount: 5,\n  }).res,\n  \"aaa bbb ccc\\\\0000A0ddd\",\n);"},"custom-ignore-markers.js":{"title":"Ignore a custom pair of template markers","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\n    \"Some text [[ do not change this ]]\\n\\nmore text and more text.\",\n    {\n      ignore: [{ heads: \"[[\", tails: \"]]\" }],\n      minCharCount: 5,\n    },\n  ).res,\n  \"Some text [[ do not change this ]]\\n\\nmore text and more&nbsp;text.\",\n);"},"hyphen-handling.js":{"title":"Keep a dash with its neighbouring words when hyphen handling is enabled","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nconst input = \"aaa bbb ccc - ddd\";\n\nassert.equal(\n  removeWidows(input, { hyphens: true, minWordCount: 0, minCharCount: 0 }).res,\n  \"aaa bbb ccc&nbsp;-&nbsp;ddd\",\n);\nassert.equal(\n  removeWidows(input, { hyphens: false, minWordCount: 0, minCharCount: 0 }).res,\n  \"aaa bbb ccc -&nbsp;ddd\",\n);"},"ignore-all-template-presets.js":{"title":"Ignore every built-in template syntax preset","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\n    \"Some {{ value }} and <%= page.title %>\\n\\nmore text and more text.\",\n    { ignore: \"all\", minCharCount: 5 },\n  ).res,\n  \"Some {{ value }}&nbsp;and <%= page.title %>\\n\\nmore text and more&nbsp;text.\",\n);"},"ignore-hexo.js":{"title":"Ignore Hexo template expressions while processing surrounding text","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\"Some text <%= page.title %>\\n\\nmore text and more text.\", {\n    ignore: \"hexo\",\n    minCharCount: 5,\n  }).res,\n  \"Some text <%= page.title %>\\n\\nmore text and more&nbsp;text.\",\n);"},"ignore-hugo.js":{"title":"Ignore Hugo template expressions while processing surrounding text","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\"Some text {{ .Title }}\\n\\nmore text and more text.\", {\n    ignore: \"hugo\",\n    minCharCount: 5,\n  }).res,\n  \"Some text {{ .Title }}\\n\\nmore text and more&nbsp;text.\",\n);"},"ignore-jinja.js":{"title":"Ignore Jinja tags while processing surrounding text","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\n    \"Some text {% if enabled %}fancy{% endif %}\\n\\nmore text and more text.\",\n    { ignore: \"jinja\", minCharCount: 5 },\n  ).res,\n  \"Some text {% if enabled %}fancy{% endif %}\\n\\nmore text and more&nbsp;text.\",\n);"},"ignore-liquid.js":{"title":"Ignore Liquid tags while processing surrounding text","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\n    \"Some text {% if customer %}fancy{% endif %}\\n\\nmore text and more text.\",\n    { ignore: \"liquid\", minCharCount: 5 },\n  ).res,\n  \"Some text {% if customer %}fancy{% endif %}\\n\\nmore text and more&nbsp;text.\",\n);"},"ignore-nunjucks.js":{"title":"Ignore Nunjucks tags while processing surrounding text","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\n    \"Some text {% if enabled %}fancy{% endif %}\\n\\nmore text and more text.\",\n    { ignore: \"nunjucks\", minCharCount: 5 },\n  ).res,\n  \"Some text {% if enabled %}fancy{% endif %}\\n\\nmore text and more&nbsp;text.\",\n);"},"javascript-output.js":{"title":"Encode the inserted non-breaking space for JavaScript","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\"aaa bbb ccc ddd\", {\n    targetLanguage: \"js\",\n    minCharCount: 5,\n  }).res,\n  \"aaa bbb ccc\\\\u00A0ddd\",\n);"},"minimum-character-count.js":{"title":"Apply widow prevention only after the minimum character count is reached","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\"a b c d\", { minWordCount: 0, minCharCount: 5 }).res,\n  \"a b c d\",\n);\nassert.equal(\n  removeWidows(\"a b c d\", { minWordCount: 0, minCharCount: 1 }).res,\n  \"a b c&nbsp;d\",\n);"},"minimum-word-count.js":{"title":"Apply widow prevention only after the minimum word count is reached","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\"one two three\", { minWordCount: 4, minCharCount: 0 }).res,\n  \"one two three\",\n);\nassert.equal(\n  removeWidows(\"one two three\", { minWordCount: 3, minCharCount: 0 }).res,\n  \"one two&nbsp;three\",\n);"},"operation-summary.js":{"title":"Inspect which transformations were applied","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nconst { res, ranges, whatWasDone } = removeWidows(\"aaa bbb\\\\0000A0ccc ddd\", {\n  convertEntities: true,\n  targetLanguage: \"html\",\n  minCharCount: 5,\n});\n\nassert.deepEqual(\n  { res, ranges, whatWasDone },\n  {\n    res: \"aaa bbb&nbsp;ccc&nbsp;ddd\",\n    ranges: [\n      [7, 14, \"&nbsp;\"],\n      [17, 18, \"&nbsp;\"],\n    ],\n    whatWasDone: {\n      removeWidows: true,\n      convertEntities: true,\n    },\n  },\n);"},"progress-range.js":{"title":"Map progress reports into a caller-owned percentage range","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nconst percentages = [];\nremoveWidows(\"a\".repeat(2100), {\n  reportProgressFunc: (percentage) => percentages.push(percentage),\n  reportProgressFuncFrom: 20,\n  reportProgressFuncTo: 30,\n});\n\nassert.equal(percentages[0], 20);\nassert.equal(percentages.at(-1), 30);\nassert.equal(\n  percentages.every((value) => value >= 20 && value <= 30),\n  true,\n);"},"raw-nonbreaking-space.js":{"title":"Insert a raw non-breaking space instead of an encoded entity","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\"aaa bbb ccc ddd\", {\n    convertEntities: false,\n    minCharCount: 5,\n  }).res,\n  \"aaa bbb ccc\\u00a0ddd\",\n);"},"remove-existing-measures.js":{"title":"Remove an existing widow-prevention entity","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\"aaa bbb ccc&nbsp;ddd\", {\n    removeWidowPreventionMeasures: true,\n    minCharCount: 5,\n  }).res,\n  \"aaa bbb ccc ddd\",\n);"},"uk-postcode.js":{"title":"Keep both halves of a UK postcode together","code":"import { strict as assert } from \"node:assert\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nassert.equal(\n  removeWidows(\"Office: SW1A 1AA\", {\n    UKPostcodes: true,\n    minWordCount: 99,\n    minCharCount: 99,\n  }).res,\n  \"Office: SW1A&nbsp;1AA\",\n);"},"widow-word-removal-from-html.js":{"title":"Widow word removal from text within HTML","code":"import { strict as assert } from \"node:assert\";\nimport { stripHtml } from \"string-strip-html\";\n\nimport { removeWidows } from \"string-remove-widows\";\n\nconst someHtml = 'The quick brown fox jumps of the lazy dog.<div class=\"a\">';\n\n// default widow word removal libs are not aware of HTML:\n// -----------------------------------------------------------------------------\n\nassert.equal(\n  removeWidows(someHtml).res,\n  'The quick brown fox jumps of the lazy dog.<div&nbsp;class=\"a\">', // 😱\n);\n\n// luckily, removeWidows() consumes optional HTML tag locations\nassert.equal(\n  removeWidows(someHtml, {\n    tagRanges: stripHtml(someHtml).allTagLocations,\n  }).res,\n  'The quick brown fox jumps of the lazy&nbsp;dog.<div class=\"a\">', // ✅\n);"}},"string-split-by-whitespace":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { splitByW } from \"string-split-by-whitespace\";\n\n// Split on any whitespace and omit empty edge values.\nassert.deepEqual(splitByW(\"\\n     \\n    a\\t \\nb    \\n      \\t\"), [\"a\", \"b\"]);"},"ignore-template-variable.js":{"title":"Exclude a template variable range from the returned words","code":"import { strict as assert } from \"node:assert\";\n\nimport { splitByW } from \"string-split-by-whitespace\";\n\nassert.deepEqual(\n  splitByW(\"before {{ full name }} after\", {\n    ignoreRanges: [[7, 22]],\n  }),\n  [\"before\", \"after\"],\n);"},"mixed-whitespace.js":{"title":"Split on line breaks, tabs, and repeated spaces","code":"import { strict as assert } from \"node:assert\";\n\nimport { splitByW } from \"string-split-by-whitespace\";\n\nassert.deepEqual(splitByW(\"one\\n\\ttwo   three\"), [\"one\", \"two\", \"three\"]);"}},"string-strip-html":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml(\"Some text <b>and</b> text.\").result,\n  \"Some text and text.\",\n);"},"c-plus-plus.js":{"title":"Ignores code tags and their contents","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nconst someHtml =\n  \"<code>#include <stdio.h>;</code> and <code>#include &lt;stdio.h&gt;</code>\";\n\n// default behaviour:\nassert.equal(stripHtml(someHtml).result, \"#include; and #include\");\n\n// ignore <code> tag pairs\nassert.equal(\n  stripHtml(someHtml, {\n    ignoreTagsWithTheirContents: [\"code\"],\n    skipHtmlDecoding: true,\n  }).result,\n  someHtml,\n);"},"cb-which-does-nothing.js":{"title":"A bypass callback and a do-nothing callback","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\n// Accept each range proposed during callback processing:\nconst cb1 = ({ rangesArr, proposedReturn }) => {\n  if (proposedReturn) {\n    rangesArr.push(...proposedReturn);\n  }\n};\nconst result1 = stripHtml(\"abc<hr>def\", { cb: cb1 }).result;\nassert.equal(result1, \"abc def\");\n\n// to prove it works, don't do anything:\nconst cb2 = () => {\n  // nothing here 🙈\n};\nconst result2 = stripHtml(\"abc<hr>def\", { cb: cb2 }).result;\nassert.equal(result2, \"abc<hr>def\");"},"cdata-section.js":{"title":"Strip an entire CDATA section","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml(\"before<![CDATA[ hidden <tag> ]]>after\").result,\n  \"before after\",\n);"},"decode-encoded-tags.js":{"title":"Decode HTML entities before recognising and stripping encoded tags","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(stripHtml(\"&lt;b&gt;bold&lt;/b&gt;\").result, \"bold\");"},"dump-link-href.js":{"title":"Keep a link destination next to its label","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml('<a href=\"https://example.com/docs\">Read the docs</a>', {\n    dumpLinkHrefsNearby: { enabled: true },\n  }).result,\n  \"Read the docs https://example.com/docs\",\n);"},"dump-link-on-new-line.js":{"title":"Put a retained link destination on a new paragraph","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml('<a href=\"https://example.com/docs\">Read the docs</a>', {\n    dumpLinkHrefsNearby: { enabled: true, putOnNewLine: true },\n  }).result,\n  \"Read the docs\\n\\nhttps://example.com/docs\",\n);"},"extract-html-head-contents.js":{"title":"Extract HTML `<head>` contents","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nconst someHtml = `<!DOCTYPE html>\n<html lang=\"en\" dir=\"ltr\">\n  <head>\n    <meta charset=\"utf-8\">\n    <title>the title</title>\n  </head>\n  <body>\n    the content\n  </body>\n</html>`;\n\n// The task asks not to include <head...> and </head>.\n// First, extract head tag-to-head tag, including contents\nconst { ranges } = stripHtml(someHtml, {\n  onlyStripTags: [\"head\"],\n  stripTogetherWithTheirContents: [\"head\"],\n});\nconst headRange = ranges?.find(([from, to]) => {\n  const candidate = someHtml.slice(from, to);\n  return candidate.includes(\"<head>\") && candidate.includes(\"</head>\");\n});\nconst headWithHeadTags = headRange\n  ? someHtml.slice(headRange[0], headRange[1]).trim()\n  : \"\";\n\nassert.equal(\n  headWithHeadTags,\n  `<head>\n    <meta charset=\"utf-8\">\n    <title>the title</title>\n  </head>`,\n);\n\nconst headContents = headWithHeadTags.replace(/<\\/?head>/g, \"\").trim();\nassert.equal(\n  headContents,\n  `<meta charset=\"utf-8\">\n    <title>the title</title>`,\n);"},"html-comment.js":{"title":"Strip an HTML comment and prevent adjacent text from joining","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(stripHtml(\"before<!-- hidden -->after\").result, \"before after\");"},"ignore-tags.js":{"title":"Preserve selected tags while stripping the rest","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml(\"<div>Read <b>this</b></div>\", { ignoreTags: [\"b\"] }).result,\n  \"Read <b>this</b>\",\n);"},"jsx-component.js":{"title":"Strip a JSX component tag from surrounding text","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml('before <Component name=\"demo\" /> after').result,\n  \"before after\",\n);"},"leave-href-and-label.js":{"title":"Retain href and link label","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nconst someHtml =\n  '<a href=\"https://twitter.com/loretparisi\">twitter:loretparisi&nbsp;&oslash;</a>';\n\nassert.equal(\n  stripHtml(someHtml, {\n    skipHtmlDecoding: true,\n  }).result,\n  \"twitter:loretparisi&nbsp;&oslash;\",\n);\n\nassert.equal(\n  stripHtml(someHtml, {\n    skipHtmlDecoding: true,\n    cb: ({ tag, deleteFrom, deleteTo, insert, rangesArr, proposedReturn }) => {\n      let temp;\n      if (\n        tag.name === \"a\" &&\n        tag.attributes?.some((attr) => {\n          if (attr.name === \"href\") {\n            temp = attr.value;\n            return true;\n          }\n          return false;\n        })\n      ) {\n        rangesArr.push([deleteFrom, deleteTo, `${temp} ${insert || \"\"}`]);\n      } else {\n        rangesArr.push(proposedReturn);\n      }\n    },\n  }).result,\n  \"https://twitter.com/loretparisi twitter:loretparisi&nbsp;&oslash;\",\n);"},"leave-only-html.js":{"title":"Leave only HTML","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nconst someHtml = `<!DOCTYPE html>\n<html lang=\"en\" dir=\"ltr\">\n  <head>\n    <meta charset=\"utf-8\">\n    <title></title>\n  </head>\n  <body>\n    <h1>Title</h1>\n    Some text.\n  </body>\n</html>`;\n\nassert.equal(\n  stripHtml(someHtml).allTagLocations.reduce(\n    (acc, [from, to]) => `${acc}${someHtml.slice(from, to)}`,\n    \"\",\n  ),\n  '<!DOCTYPE html><html lang=\"en\" dir=\"ltr\"><head><meta charset=\"utf-8\"><title></title></head><body><h1></h1></body></html>',\n);"},"leave-only-opening-td.js":{"title":"Leave only opening `td` tags","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nconst someHtml = `<table width=\"100\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\n  <tr>\n    <td class=\"col1\">\n      cell1\n    </td>\n    <td class=\"col2\">\n      cell2\n    </td>\n  </tr>\n  <tr>\n    <td class=\"col3\">\n      cell3\n    </td>\n    <td class=\"col4\">\n      cell4\n    </td>\n  </tr>\n</table>`;\n\n// the first way\n// -----------------------------------------------------------------------------\n\nassert.equal(\n  stripHtml(someHtml, {\n    // notice there's no: onlyStripTags: [\"td\"]\n    // we operate purely via callback\n    cb: ({ tag, deleteFrom, deleteTo, insert, rangesArr, proposedReturn }) => {\n      if (tag.name === \"td\" && !tag.slashPresent) {\n        rangesArr.push(proposedReturn);\n      }\n    },\n  }).ranges.reduce(\n    (acc, [from, to]) => `${acc}${someHtml.slice(from, to).trim()}`,\n    \"\",\n  ),\n  '<td class=\"col1\"><td class=\"col2\"><td class=\"col3\"><td class=\"col4\">',\n);\n\n// the second way:\n// -----------------------------------------------------------------------------\n\nlet resultStr = \"\";\n// notice we don't even assign stripHtml() output to anything - we rely only\n// on the callback, it mutates the \"resultStr\" in the upper scope\nstripHtml(someHtml, {\n  // notice there's no: onlyStripTags: [\"td\"]\n  // we operate purely via callback\n  cb: ({ tag, deleteFrom, deleteTo, insert, rangesArr, proposedReturn }) => {\n    if (tag.name === \"td\" && !tag.slashPresent) {\n      resultStr += someHtml.slice(deleteFrom, deleteTo).trim();\n    }\n  },\n});\nassert.equal(\n  resultStr,\n  '<td class=\"col1\"><td class=\"col2\"><td class=\"col3\"><td class=\"col4\">',\n);"},"leave-only-td.js":{"title":"Leave only `td` tags","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nconst someHtml = `<table width=\"100\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\">\n  <tr>\n    <td class=\"col1\">\n      cell1\n    </td>\n    <td class=\"col2\">\n      cell2\n    </td>\n  </tr>\n  <tr>\n    <td class=\"col3\">\n      cell3\n    </td>\n    <td class=\"col4\">\n      cell4\n    </td>\n  </tr>\n</table>`;\n\nassert.equal(\n  stripHtml(someHtml, {\n    onlyStripTags: [\"td\"],\n  }).filteredTagLocations.reduce(\n    (acc, [from, to]) => `${acc}${someHtml.slice(from, to)}`,\n    \"\",\n  ),\n  '<td class=\"col1\"></td><td class=\"col2\"></td><td class=\"col3\"></td><td class=\"col4\"></td>',\n);"},"minimal-ranges.js":{"title":"Minimal example using Ranges","code":"// We strip tags and fix apostrophes\n// that's part of what https://codsen.com/os/detergent/ does\n\nimport { strict as assert } from \"node:assert\";\n\nimport { rApply } from \"ranges-apply\";\nimport { convertAll } from \"string-apostrophes\";\nimport { stripHtml } from \"string-strip-html\";\n\nfunction stripAndFixApos(str) {\n  if (!str || typeof str !== \"string\") {\n    return \"\";\n  }\n  // Keep in mind, Ranges are array of 2-3 element arrays.\n  // But absent Ranges are marked as null, not empty array.\n  // It's so that we could test in \"if-else\" easily - null\n  // is falsy but empty array is truthy.\n  // That's why below we take precautions with \"|| []\".\n  return rApply(\n    str,\n    (stripHtml(str).ranges || []).concat(convertAll(str).ranges || []),\n  );\n}\n\n// strips tags and fixes apostrophes:\nassert.equal(\n  stripAndFixApos(\"Let's Go <strong>Larval</strong>\"),\n  \"Let’s Go Larval\",\n);\n\n// no tags, no apostrophes:\nassert.equal(stripAndFixApos(\"zzz\"), \"zzz\");"},"preserve-indentations.js":{"title":"Preserve indentation while collapsing whitespace around stripped tags","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml(\"  one <b>two</b>\\n    three <i>four</i>\", {\n    ignoreIndentations: true,\n  }).result,\n  \"  one two\\n    three four\",\n);"},"preserve-jsp.js":{"title":"Leave JSP scriptlets intact while stripping HTML","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nconst input = \"a<% if (enabled) { %>b<% } %>c\";\n\nassert.equal(stripHtml(input).result, input);"},"preserve-punctuation.js":{"title":"Preserve punctuation around removed inline tags","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml(\"Hello <b>world</b>, welcome!\").result,\n  \"Hello world, welcome!\",\n);"},"preserve-raw-brackets.js":{"title":"Preserve literal comparison brackets in plain text","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(stripHtml(\"a < b and c > d\").result, \"a < b and c > d\");"},"prevent-text-concatenation.js":{"title":"Insert spaces when removing tags between adjacent text","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(stripHtml(\"aaa<div>bbb</div>ccc\").result, \"aaa bbb ccc\");"},"progress-callback.js":{"title":"Map progress reporting into a custom percentage range","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nconst percentages = [];\nconst result = stripHtml(\"<em>a</em>\".repeat(150), {\n  reportProgressFunc: (percentage) => percentages.push(percentage),\n  reportProgressFuncFrom: 80,\n  reportProgressFuncTo: 100,\n});\n\nassert.equal(result.result, \"a\".repeat(150));\nassert.deepEqual(percentages, [90]);"},"remove-html.js":{"title":"Remove all HTML from a string","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nconst someHtml = `<!DOCTYPE html>\n<html lang=\"en\" dir=\"ltr\">\n  <head>\n    <meta charset=\"utf-8\">\n    <title></title>\n  </head>\n  <body>\n    <h1>Title</h1>\n    Some text.\n  </body>\n</html>`;\n\nassert.equal(stripHtml(someHtml).result, \"Title\\nSome text.\");"},"retain-paired-tag-content.js":{"title":"Strip script tags but retain their text when paired-content removal is disabled","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml(\"before<script>alert(1)</script>after\", {\n    stripTogetherWithTheirContents: [],\n  }).result,\n  \"before alert(1) after\",\n);"},"strip-from-json.js":{"title":"Strip HTML from a raw JSON string","code":"import { strict as assert } from \"node:assert\";\nimport { traverse } from \"ast-monkey-traverse\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nconst stripFromJsonStr = (str) => {\n  return traverse(JSON.parse(str), (key, val, innerObj) => {\n    // Objects supply a property key and value; arrays supply the element as key.\n    let current = innerObj.parentType === \"object\" ? val : key;\n    if (\n      // ensure it's a plain object, not array (monkey will report only \"key\" in\n      // arrays and \"val\" will be undefined)\n      // also ensure object's value a string, not boolean or number, because we\n      // don't strip HTML from booleans or numbers or anything else than strings\n      innerObj.parentType === \"object\" && typeof val === \"string\"\n    ) {\n      // monkey's callback is like Array.map - whatever you return gets written:\n      return stripHtml(val).result;\n    }\n    // default return, do nothing:\n    return current;\n  });\n};\n\n// nothing to strip, \"<\" is false alarm:\nassert.equal(\n  JSON.stringify(stripFromJsonStr('{\"Operator\":\"<\",\"IsValid\":true}'), null, 0),\n  '{\"Operator\":\"<\",\"IsValid\":true}',\n);\n\n// some HTML within one of key values, monkey will skip the boolean:\nassert.equal(\n  JSON.stringify(\n    stripFromJsonStr('{\"Operator\":\"a <div>b</div> c\",\"IsValid\":true}'),\n    null,\n    0,\n  ),\n  '{\"Operator\":\"a b c\",\"IsValid\":true}',\n);"},"strip-paired-tag-contents.js":{"title":"Remove a selected tag pair together with its contents","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml(\"a <pre><code>void a;</code></pre> b\", {\n    stripTogetherWithTheirContents: [\"script\", \"style\", \"xml\", \"pre\"],\n  }).result,\n  \"a b\",\n);"},"strip-recognised-html-only.js":{"title":"Preserve custom elements while stripping recognised HTML tags","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml(\"<div><custom>hello</custom></div>\", {\n    stripRecognisedHTMLOnly: true,\n  }).result,\n  \"<custom>hello</custom>\",\n);"},"title-case-with-tag-skipping.js":{"title":"Set the title case using `title` package","code":"// This program will not touch any single tags (<br class=\"z\"/> for example)\n// or in case of paired tags, paired tags and content between\n\nimport { strict as assert } from \"node:assert\";\nimport title from \"title\";\nimport { rApply } from \"ranges-apply\";\nimport { rInvert } from \"ranges-invert\";\nimport { rRegex } from \"ranges-regex\";\nimport { stripHtml } from \"string-strip-html\";\n\nfunction tagAwareTitle(str) {\n  let whitelist = [\"eslint\", \"readme\", \"npm\"];\n  let { ranges } = stripHtml(str, {\n    stripTogetherWithTheirContents: [\"*\"],\n  });\n  let inverted = rInvert(\n    (ranges || [])\n      .map(([from, to]) => [from, to])\n      .concat(\n        whitelist.reduce((acc, curr) => {\n          let rangesFindings = rRegex(new RegExp(curr, \"gi\"), str);\n          if (rangesFindings) {\n            return acc.concat(rangesFindings);\n          }\n          return acc;\n        }, []),\n      ),\n    str.length,\n  );\n\n  if (Array.isArray(inverted) && inverted.length) {\n    // take inverted ranges, for example, [[3, 4], [10, 15]]\n    // and add third element, replacement, which is same character\n    // indexes only processed through \"title\":\n    return rApply(\n      str,\n      inverted.map(([from, to]) => [from, to, title(str.slice(from, to))]),\n    );\n  }\n  // otherwise, just apply title() on the whole string:\n  return title(str);\n}\n\n// middle:\nassert.equal(\n  tagAwareTitle(\"This is a title with some <code>code</code> in it\"),\n  \"This Is a Title with Some <code>code</code> In It\",\n);\n\n// leading:\nassert.equal(\n  tagAwareTitle('<span class=\"xyz\">abc</span> defgh ESLint'),\n  '<span class=\"xyz\">abc</span> Defgh ESLint',\n);"},"trim-only-spaces.js":{"title":"Trim ordinary spaces while preserving tabs and line breaks","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml(\" \\t a \\n \", { trimOnlySpaces: true }).result,\n  \"\\t a \\n\",\n);"},"widow-word-removal-from-html.js":{"title":"Orphan removal from text within HTML","code":"import { strict as assert } from \"node:assert\";\nimport { removeWidows } from \"string-remove-widows\";\nimport { stripHtml } from \"string-strip-html\";\n\nconst someHtml = 'The quick brown fox jumps of the lazy dog.<div class=\"a\">';\n\n// default widow word removal libs are not aware of HTML:\n// -----------------------------------------------------------------------------\n\nassert.equal(\n  removeWidows(someHtml).res,\n  'The quick brown fox jumps of the lazy dog.<div&nbsp;class=\"a\">', // 😱\n);\n\n// luckily, removeWidows() consumes optional HTML tag locations\nassert.equal(\n  removeWidows(someHtml, {\n    tagRanges: stripHtml(someHtml)\n      // remove the third argument, what to insert (\"&nbsp;\" string in these cases)\n      .ranges.map(([from, to]) => [from, to]),\n  }).res,\n  'The quick brown fox jumps of the lazy&nbsp;dog.<div class=\"a\">', // ✅\n);"},"wrap-dumped-link.js":{"title":"Wrap a retained link destination with custom markers","code":"import { strict as assert } from \"node:assert\";\n\nimport { stripHtml } from \"string-strip-html\";\n\nassert.equal(\n  stripHtml('<a href=\"https://example.com/docs\">Read the docs</a>', {\n    dumpLinkHrefsNearby: {\n      enabled: true,\n      wrapHeads: \"[\",\n      wrapTails: \"]\",\n    },\n  }).result,\n  \"Read the docs [https://example.com/docs]\",\n);"}},"string-trim-spaces-only":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { trimSpaces } from \"string-trim-spaces-only\";\n\nassert.deepEqual(trimSpaces(\"  aaa   \"), {\n  res: \"aaa\",\n  ranges: [\n    [0, 2],\n    [5, 8],\n  ],\n});"},"carriage-returns.js":{"title":"Include carriage returns in the configured trim set","code":"import { strict as assert } from \"node:assert\";\n\nimport { trimSpaces } from \"string-trim-spaces-only\";\n\nassert.equal(trimSpaces(\"\\r  value  \\r\", { cr: true }).res, \"value\");"},"classic-trim.js":{"title":"Trim every JavaScript whitespace character","code":"import { strict as assert } from \"node:assert\";\n\nimport { trimSpaces } from \"string-trim-spaces-only\";\n\nassert.equal(\n  trimSpaces(\" \\t\\n value \\r\\n \", { classicTrim: true }).res,\n  \"value\",\n);"},"exclude-ordinary-spaces.js":{"title":"Trim tabs but preserve ordinary spaces at the edges","code":"import { strict as assert } from \"node:assert\";\n\nimport { trimSpaces } from \"string-trim-spaces-only\";\n\nassert.equal(\n  trimSpaces(\"\\t  value  \\t\", { space: false, tab: true }).res,\n  \"  value  \",\n);"},"line-feeds.js":{"title":"Include line feeds in the configured trim set","code":"import { strict as assert } from \"node:assert\";\n\nimport { trimSpaces } from \"string-trim-spaces-only\";\n\nassert.equal(trimSpaces(\"\\n  value  \\n\", { lf: true }).res, \"value\");"},"mixed-whitespace-boundaries.js":{"title":"Preserve non-space whitespace at the trimmed boundaries","code":"import { strict as assert } from \"node:assert\";\n\nimport { trimSpaces } from \"string-trim-spaces-only\";\n\nassert.deepEqual(trimSpaces(\"   \\t  zz   \\n    \"), {\n  res: \"\\t  zz   \\n\",\n  ranges: [\n    [0, 3],\n    [12, 16],\n  ],\n});"},"non-breaking-spaces.js":{"title":"Include raw non-breaking spaces in the configured trim set","code":"import { strict as assert } from \"node:assert\";\n\nimport { trimSpaces } from \"string-trim-spaces-only\";\n\nassert.equal(trimSpaces(\"\\u00a0  value  \\u00a0\", { nbsp: true }).res, \"value\");"},"nothing-to-trim.js":{"title":"Return an empty ranges array when the value needs no trimming","code":"import { strict as assert } from \"node:assert\";\n\nimport { trimSpaces } from \"string-trim-spaces-only\";\n\nassert.deepEqual(trimSpaces(\"value\"), { res: \"value\", ranges: [] });"},"tabs.js":{"title":"Include tabs in the configured trim set","code":"import { strict as assert } from \"node:assert\";\n\nimport { trimSpaces } from \"string-trim-spaces-only\";\n\nassert.equal(trimSpaces(\"\\t  value  \\t\", { tab: true }).res, \"value\");"}},"string-uglify":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { uglifyArr } from \"string-uglify\";\n\n// notice we put dots and hashes for classes and id's but algorithm will work\n// fine too if you won't.\nconst names = [\n  \".module-promo-all\",\n  \".module-promo-main\",\n  \".module-promo-second\",\n  \"#zzz\",\n];\n\nassert.deepEqual(uglifyArr(names), [\".o\", \".s\", \".z\", \"#l\"]);"},"duplicate-names.js":{"title":"Preserve mappings for duplicate names","code":"import { strict as assert } from \"node:assert\";\n\nimport { uglifyArr } from \"string-uglify\";\n\nconst result = uglifyArr([\".long-name\", \".long-name\", \"#long-name\"]);\n\nassert.equal(result[0], result[1]);\nassert.equal(result[0].startsWith(\".\"), true);\nassert.equal(result[2].startsWith(\"#\"), true);"},"empty-array.js":{"title":"Preserve an empty names array","code":"import { strict as assert } from \"node:assert\";\n\nimport { uglifyArr } from \"string-uglify\";\n\nconst input = [];\nconst result = uglifyArr(input);\n\nassert.deepEqual(result, []);\nassert.notEqual(result, input);\n\nresult.push(\"changed\");\nassert.deepEqual(input, []);"},"plain-names.js":{"title":"Uglify names without class or ID prefixes","code":"import { strict as assert } from \"node:assert\";\n\nimport { uglifyArr } from \"string-uglify\";\n\nconst result = uglifyArr([\"navigation\", \"navigation\", \"footer\"]);\n\nassert.equal(result[0], result[1]);\nassert.equal(\n  result.every((name) => !name.startsWith(\".\") && !name.startsWith(\"#\")),\n  true,\n);"},"reserve-short-names.js":{"title":"Keep existing short names reserved","code":"import { strict as assert } from \"node:assert\";\n\nimport { uglifyArr } from \"string-uglify\";\n\nassert.deepEqual(uglifyArr([\".a\", \".alpha\", \".b\", \".bravo\"]), [\n  \".a\",\n  \".s\",\n  \".b\",\n  \".m\",\n]);"},"uglify-by-id.js":{"title":"Uglify one name by its array index","code":"import { strict as assert } from \"node:assert\";\n\nimport { uglifyById } from \"string-uglify\";\n\nconst names = [\n  \".module-promo-all\",\n  \".module-promo-main\",\n  \".module-promo-second\",\n  \"#zzz\",\n];\n\nassert.equal(uglifyById(names, 3), \"#l\");"}},"string-unfancy":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { unfancy } from \"string-unfancy\";\n\n// U+2019\n// https://www.fileformat.info/info/unicode/char/2019/index.htm\n// https://mothereff.in/js-escapes\nconst rightSingleQuote = \"\\u2019\";\n\nassert.equal(unfancy(`someone${rightSingleQuote}s`), \"someone's\");"},"dashes-ellipsis-and-multiplication.js":{"title":"Normalise common typographic characters","code":"import { strict as assert } from \"node:assert\";\n\nimport { unfancy } from \"string-unfancy\";\n\nassert.equal(unfancy(\"Wait… 3 × 4 — done\"), \"Wait... 3 × 4 - done\");"},"encoded-html.js":{"title":"Normalise an HTML-encoded typographic character","code":"import { strict as assert } from \"node:assert\";\n\nimport { unfancy } from \"string-unfancy\";\n\nassert.equal(unfancy(\"someone&rsquo;s\"), \"someone's\");"},"non-breaking-spaces.js":{"title":"Convert non-breaking spaces","code":"import { strict as assert } from \"node:assert\";\n\nimport { unfancy } from \"string-unfancy\";\n\nassert.equal(unfancy(\"left&nbsp;&ndash;&nbsp;right\"), \"left - right\");"},"triple-encoded-html.js":{"title":"Decode repeatedly encoded HTML","code":"import { strict as assert } from \"node:assert\";\n\nimport { unfancy } from \"string-unfancy\";\n\nassert.equal(unfancy(\"it&amp;amp;rsquo;s ready\"), \"it's ready\");"}},"test-mixer":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { mixer } from \"test-mixer\";\n\n// Generate all possible combinations of boolean options.\nconst defaultOpts = {\n  enabled: true,\n  cached: false,\n};\n\nassert.deepEqual(mixer({}, defaultOpts), [\n  { enabled: false, cached: false },\n  { enabled: true, cached: false },\n  { enabled: false, cached: true },\n  { enabled: true, cached: true },\n]);"},"callback-values.js":{"title":"Preserve callback values without invoking them","code":"import { strict as assert } from \"node:assert\";\n\nimport { mixer } from \"test-mixer\";\n\nlet calls = 0;\nconst callback = () => {\n  calls += 1;\n};\nconst result = mixer({}, { enabled: true, callback });\n\nassert.equal(calls, 0);\nassert.equal(result[0].callback, callback);\nassert.equal(result[1].callback, callback);"},"cloned-values.js":{"title":"Clone nested values for every generated variation","code":"import { strict as assert } from \"node:assert\";\n\nimport { mixer } from \"test-mixer\";\n\nconst defaults = { enabled: true, metadata: { mode: \"safe\" } };\nconst result = mixer({}, defaults);\n\ndefaults.metadata.mode = \"changed\";\n\nassert.equal(result[0].metadata.mode, \"safe\");\nassert.equal(result[1].metadata.mode, \"safe\");\n\nresult[0].metadata.mode = \"changed in the first row\";\n\nassert.equal(result[1].metadata.mode, \"safe\");"},"lazy-combinations.js":{"title":"Process combinations lazily and stop when enough rows have been handled","code":"import { strict as assert } from \"node:assert\";\n\nimport { mixerLazy } from \"test-mixer\";\n\nconst handled = [];\nfor (const row of mixerLazy({}, { first: true, second: false, third: true })) {\n  handled.push(row);\n  if (handled.length === 3) {\n    break;\n  }\n}\n\nassert.deepEqual(handled, [\n  { first: false, second: false, third: false },\n  { first: true, second: false, third: false },\n  { first: false, second: true, third: false },\n]);"},"no-defaults.js":{"title":"No defaults means no variations","code":"import { strict as assert } from \"node:assert\";\n\nimport { mixer } from \"test-mixer\";\n\nassert.deepEqual(mixer({}, {}), []);"},"non-boolean-values.js":{"title":"Carry non-boolean values into every variation","code":"import { strict as assert } from \"node:assert\";\n\nimport { mixer } from \"test-mixer\";\n\nassert.deepEqual(\n  mixer({ requiredValue: \"present\" }, { enabled: true, mode: \"safe\" }),\n  [\n    { enabled: false, mode: \"safe\", requiredValue: \"present\" },\n    { enabled: true, mode: \"safe\", requiredValue: \"present\" },\n  ],\n);"},"pinned-option.js":{"title":"Pin one option while varying the others","code":"import { strict as assert } from \"node:assert\";\n\nimport { mixer } from \"test-mixer\";\n\nconst defaultOpts = {\n  enabled: true,\n  cached: false,\n};\n\nassert.deepEqual(mixer({ enabled: true }, defaultOpts), [\n  { enabled: true, cached: false },\n  { enabled: true, cached: true },\n]);"}},"tsd-extract":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\nimport { extract } from \"tsd-extract\";\n\nconst { value } = extract(\n  `interface Opts1 { foo: boolean };\ninterface Opts2 { bar: boolean };`,\n  \"Opts2\",\n);\n\nassert.equal(value, \"interface Opts2 { bar: boolean };\");"},"extract-nested-member.js":{"title":"Extract a nested member","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"tsd-extract\";\n\nconst source = `interface Options {\n  output: {\n    format: \"json\" | \"text\";\n    pretty: boolean;\n  };\n}`;\n\nassert.equal(\n  extract(source, \"Options.output\").value,\n  'output: {\\n  format: \"json\" | \"text\";\\n  pretty: boolean;\\n};',\n);"},"function-definitions.js":{"title":"Extracting function type definitions","code":"import { strict as assert } from \"node:assert\";\nimport { extract } from \"tsd-extract\";\n\n// Real type definitions from ast-monkey-util:\nconst source = `\ndeclare function pathNext(str: string): string;\ndeclare function pathPrev(str: string): null | string;\ndeclare function pathUp(str: string): string;\ndeclare function parent(str: string): null | string;\ndeclare const version: string;\nexport { parent, pathNext, pathPrev, pathUp, version };\n`;\n\n// If you try to extract a function,\nconst { value, content: content1 } = extract(source, \"parent\");\n//                    ^\n//                 that's ES6 destructuring assignment + renaming\n\n// The \"value\" will be the whole statement:\nassert.equal(value, \"declare function parent(str: string): null | string;\");\n\n// But what do we do if we don't want the \"declare\" part?\n// extract \"content\", then manually prepend:\nassert.equal(content1, \"(str: string): null | string;\");\n\n// Imagine, if this was JSX, you'd create a functional component\n// which accepts the \"prepend\" prop. A primitive substitute example:\n\nfunction extractWithPrepend(prepend, ...etc) {\n  return `${prepend}${extract(...etc).content}`;\n}\n\nassert.equal(\n  extractWithPrepend(\n    \"function parent\", // prepend this\n    // all the same args as before:\n    source,\n    \"parent\",\n  ),\n  \"function parent(str: string): null | string;\",\n);\n\n// On codsen.com, we manually prepend \"content\" the same way\n// because if we used \"value\", resulting \"declare\" would confuse people."},"join-object-types.js":{"title":"Join two object types into one","code":"import { strict as assert } from \"node:assert\";\n\nimport { join } from \"tsd-extract\";\n\nassert.equal(\n  join(\n    \"interface Identity { id: string; }\",\n    \"type Timestamps = { updated: Date; }\",\n  ),\n  \"{\\n  id: string;\\n  updated: Date;\\n}\",\n);"},"list-all-declarations.js":{"title":"List all declarations in the source","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"tsd-extract\";\n\nconst source = `interface First { value: string }\ninterface Second { count: number }`;\n\nassert.deepEqual(extract(source, \"Second\", { extractAll: true }).all, [\n  \"First\",\n  \"Second\",\n]);"},"not-found-result.js":{"title":"Report a declaration that was not found","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"tsd-extract\";\n\nconst result = extract(\"interface Present { value: string }\", \"Missing\");\n\nassert.equal(result.error, \"not found\");\nassert.equal(result.value, null);"},"omit-semicolon.js":{"title":"Omit the trailing semicolon","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"tsd-extract\";\n\nassert.equal(\n  extract('declare type Mode = \"light\" | \"dark\";', \"Mode\", { semi: false })\n    .value,\n  'declare type Mode = \"light\" | \"dark\"',\n);"},"require-statement-content.js":{"title":"Require a statement to contain a string","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"tsd-extract\";\n\nconst source = `export { first } from \"one\";\nexport { second } from \"two\";`;\n\nassert.equal(\n  extract(source, \"export\", { mustInclude: \"second\" }).value,\n  'export { second } from \"two\";',\n);"},"sorting-exports.js":{"title":"Sorting exports","code":"import { strict as assert } from \"node:assert\";\nimport { extract, roysSort } from \"tsd-extract\";\n\n// Often, in .d.ts files, the main function is not the first in the list:\nconst dtsSource = `\nexport { Attribute, CbObj, Opts, Res, Tag, defaults, stripHtml, version };\n`;\n\n// If you try to extract a function,\nconst { content: content1 } = extract(dtsSource, \"export\");\n//                    ^\n//                 that's ES6 destructuring assignment + renaming\n\n// The \"content\" will come as-is:\nassert.equal(\n  content1,\n  \"{ Attribute, CbObj, Opts, Res, Tag, defaults, stripHtml, version };\",\n);\n\n// -----------------------------------------------------------------------------\n\n// But, you can sort it using Roy's Favourite Sort Function™\nconst { content: content2 } = extract(dtsSource, \"export\", {\n  contentSort: roysSort,\n});\n\nassert.equal(\n  content2,\n  \"{ stripHtml, defaults, version, Attribute, CbObj, Opts, Res, Tag };\",\n);\n// The lower case export go first, then uppercase;\n// also, \"defaults\" and \"version\" go last (among lower-case ones)\n// we use this very function on codsen.com/os/* readmes\n\n// -----------------------------------------------------------------------------\n\n// Alternatively, you can supply your own sort function, it's the\n// Array.prototype.sort() under the hood, see:\n// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/sort#examples\n// also, see the roysSort() source for reference:\n// https://github.com/codsen/codsen/blob/main/packages/tsd-extract/src/util.ts\n\nfunction myCustomSort(a, b) {\n  if (a.toLowerCase() < b.toLowerCase()) {\n    // sort b after a\n    return -1;\n  }\n  if (a.toLowerCase() > b.toLowerCase()) {\n    // sort a after b\n    return 1;\n  }\n  // keep the existing order\n  return 0;\n}\nconst { content: content3 } = extract(dtsSource, \"export\", {\n  contentSort: myCustomSort,\n});\n\nassert.equal(\n  content3,\n  \"{ Attribute, CbObj, defaults, Opts, Res, stripHtml, Tag, version };\",\n);"},"strip-export-aliases.js":{"title":"Strip the `as` aliases from an export","code":"import { strict as assert } from \"node:assert\";\n\nimport { extract } from \"tsd-extract\";\n\nconst source = \"export { original as publicName, unchanged };\";\n\nassert.equal(\n  extract(source, \"export\", { stripAs: true }).content,\n  \"{ publicName, unchanged };\",\n);"}},"util-array-object-or-both":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { arrObjOrBoth } from \"util-array-object-or-both\";\n\nassert.equal(arrObjOrBoth(\"arrays\"), \"array\");"},"array-aliases.js":{"title":"Normalise the accepted array aliases","code":"import { strict as assert } from \"node:assert\";\n\nimport { arrObjOrBoth } from \"util-array-object-or-both\";\n\nassert.equal(arrObjOrBoth(\"arrays\"), \"array\");\nassert.equal(arrObjOrBoth(\"array\"), \"array\");\nassert.equal(arrObjOrBoth(\"arr\"), \"array\");\nassert.equal(arrObjOrBoth(\"a\"), \"array\");"},"custom-error-context.js":{"title":"Customise the thrown error's context","code":"import { strict as assert } from \"node:assert\";\n\nimport { arrObjOrBoth } from \"util-array-object-or-both\";\n\nassert.throws(\n  () =>\n    arrObjOrBoth(\"map\", {\n      msg: \"renderer/configure(): [THROW_ID_03]\",\n      optsVarName: \"only\",\n    }),\n  /renderer\\/configure\\(\\): \\[THROW_ID_03\\].*variable \"only\".*map/,\n);"},"either-aliases.js":{"title":"Normalise aliases that allow either arrays or objects","code":"import { strict as assert } from \"node:assert\";\n\nimport { arrObjOrBoth } from \"util-array-object-or-both\";\n\nassert.equal(arrObjOrBoth(\"whatever\"), \"any\");\nassert.equal(arrObjOrBoth(\"either\"), \"any\");\nassert.equal(arrObjOrBoth(\"both\"), \"any\");\nassert.equal(arrObjOrBoth(\"any\"), \"any\");\nassert.equal(arrObjOrBoth(\"all\"), \"any\");\nassert.equal(arrObjOrBoth(\"e\"), \"any\");"},"normalise-case-and-whitespace.js":{"title":"Case and surrounding whitespace are normalised","code":"import { strict as assert } from \"node:assert\";\n\nimport { arrObjOrBoth } from \"util-array-object-or-both\";\n\nassert.equal(arrObjOrBoth(\"  ARR\\n\"), \"array\");\nassert.equal(arrObjOrBoth(\"\\tObjects \"), \"object\");\nassert.equal(arrObjOrBoth(\" EVERYTHING \"), \"any\");"},"object-aliases.js":{"title":"Normalise the accepted object aliases","code":"import { strict as assert } from \"node:assert\";\n\nimport { arrObjOrBoth } from \"util-array-object-or-both\";\n\nassert.equal(arrObjOrBoth(\"objects\"), \"object\");\nassert.equal(arrObjOrBoth(\"object\"), \"object\");\nassert.equal(arrObjOrBoth(\"obj\"), \"object\");\nassert.equal(arrObjOrBoth(\"o\"), \"object\");"}},"util-nonempty":{"_quickTake.js":{"title":"Quick Take","code":"import { strict as assert } from \"node:assert\";\n\nimport { nonEmpty } from \"util-nonempty\";\n\nassert.equal(nonEmpty(\"z\"), true);\nassert.equal(nonEmpty(\"\"), false);"},"arrays.js":{"title":"Check whether an array contains a value","code":"import { strict as assert } from \"node:assert\";\n\nimport { nonEmpty } from \"util-nonempty\";\n\nassert.equal(nonEmpty([\"a\"]), true);\nassert.equal(nonEmpty([123]), true);"},"nested-arrays.js":{"title":"Treat a deeply nested array as non-empty","code":"import { strict as assert } from \"node:assert\";\n\nimport { nonEmpty } from \"util-nonempty\";\n\nassert.equal(nonEmpty([[[[[[[[[[[]]]]]]]]]]]), true);"},"numbers.js":{"title":"Treat every number, including zero and NaN, as non-empty","code":"import { strict as assert } from \"node:assert\";\n\nimport { nonEmpty } from \"util-nonempty\";\n\nassert.equal(nonEmpty(0), true);\nassert.equal(nonEmpty(42), true);\nassert.equal(nonEmpty(Number.NaN), true);"},"objects.js":{"title":"Check whether an object contains a property","code":"import { strict as assert } from \"node:assert\";\n\nimport { nonEmpty } from \"util-nonempty\";\n\nassert.equal(nonEmpty({ a: \"\" }), true);\nassert.equal(nonEmpty({ a: \"a\" }), true);\nassert.equal(nonEmpty({}), false);"},"unsupported-values.js":{"title":"Treat nullish and Boolean values as empty","code":"import { strict as assert } from \"node:assert\";\n\nimport { nonEmpty } from \"util-nonempty\";\n\nassert.equal(nonEmpty(null), false);\nassert.equal(nonEmpty(undefined), false);\nassert.equal(nonEmpty(true), false);\nassert.equal(nonEmpty(false), false);\n\nconst callback = () => \"z\";\n\nassert.equal(nonEmpty(callback), false);"}}};
